            <p>‘小报’则是另一条线索。它由民间或部分官员私下刊印，提前透露尚未定论的除授与章奏，屡遭禁绝而未能根除。小报的存在说明，官方对信息的垄断并不彻底，读者对时效与内幕的需求始终存在。宋会要所录多为制度规定，实际抄传情形还须借文集、笔记与方志补充。</p>
