            <p>效果与局限并存。合并项目确实压缩了里胥加派的空间，银两征收也便利了跨区域调拨；但火耗、折色与额外派征随之出现，地方财政的缺口往往转嫁回编户。张居正死后，一条鞭法并未废止，却在各地演化出不同的加派名目，明末的辽饷、剿饷、练饷即在其框架上叠加。</p>
