            <p>《隋书》的纪传部分由魏徵、令狐德棻等奉敕修撰，贞观年间成书，其《东夷传》依次排列高句丽、百济、新罗、倭国等条，体例沿袭四夷传的传统。这类传目所依据的材料，包括隋代的起居注、国史以及使臣的见闻，因此对隋代东北亚关系的记载相对贴近，但仍属唐初的官方编纂，带有取舍。</p>
