            <p>三镜分列身、史、人三层：铜镜正衣冠，是日常起居之鉴；古镜见兴替，是以王朝更迭为参照；人镜知得失，则落在谏诤之臣的具体批评上。层次由近及远，由物及己，最后归到眼前这位刚去世的谏臣。《通鉴》作「见兴替」「知得失」，《旧唐书·魏徵传》作「知兴替」「明得失」，用字轻重不同，属文本流传中的异文，不宜据以判定孰是。</p>
