            <p>「理乱兴衰，不相因者也」指治乱之迹前后并无沿袭之理，故序中以晋之得国异乎汉、隋之丧邦殊乎唐为例，说明每一代的兴起与崩坏各有其故。「典章经制，实相因者也」则谓制度有承继累积之迹，可溯其源流、较其同异。「相因」即沿袭、承继，二句对举，正为说明《通鉴》详于治乱而略于制度，故须别作一书以补其阙。</p>
