            <p>范宣子先以家族自陶唐氏以来的世系与世禄自夸，叔孙豹却把它降为「世禄」，另立立德、立功、立言为不朽。「太上」指最高一层，三等之间有分明的高下；判断不朽的标准则是「虽久不废」，即能否经得起时间。德、功、言都不依赖宗族血食，而依赖个人作为在后世的持续影响。「立言」一项尤其关键：臧文仲身死而「其言立」，说明言辞与著述可以成为独立的传世之物。</p>
