        date: "2026-11-29",
        tags: ["明清之际", "制度史", "王夫之"],
        excerpt: "郡县之制，垂二千年而弗能改矣，合古今上下皆安之，势之所趋，岂非理而能然哉？",
        commentary: `
            <p>王夫之（一六一九—一六九二），字而农，号姜斋，湖南衡阳人，明亡后曾举兵抗清，晚年隐居石船山，人称船山先生。《读通鉴论》三十卷，是就《资治通鉴》所载史事逐条评论的史论集，撰于晚年。卷一论秦事，此句出自其中论郡县的一条。文体是札记式史论，长于辨析制度得失。</p>
            <p>「势」与「理」是这句的两个支点。先说郡县制「垂二千年而弗能改」，是事实判断；再说「合古今上下皆安之」，是实效与人心的判断；最后以「势之所趋，岂非理而能然哉」把势与理打通——长久而不可改的形势，本身就体现了理。这比柳宗元只讲势更进一步：势不是盲目的外力，而是有理可循的必然。他接着还说，郡县使「才可长民者皆居民上」，是天下之公。</p>
            <p>价值在于，这条史论把制度史从道德评判中拉出来，用势与理解释制度的长期合理性，是古代制度史论的高峰；它也回应了顾炎武、黄宗羲复封建的议论，构成明清之际郡县与封建之争的一方。局限是，「理势合一」仍属哲学化的解释，缺少具体历史条件的分析；「合古今上下皆安之」也有以果证因之嫌，存在已久不等于合理。船山论史在明亡语境中，褒郡县亦含对明代集权的复杂态度。</p>
        `,
