        commentary: `
            <p>杜佑（七三五—八一二），字君卿，京兆万年人，历仕玄宗至宪宗，官至宰相，封岐国公。《通典》二百卷，大历年间始撰，贞元十七年成书进献，是中国第一部典章制度通史。全书分食货、选举、职官、礼、乐、兵、刑法、州郡、边防九门，以食货居首。自序述编纂缘起与体例，此句在序中，标明全书宗旨。杜佑久任地方与中央的财政、军事职务，此书有实际政务的经验背景。</p>
            <p>「采群言」是取材，「征诸人事」是验证，「将施有政」是目的，三层递进，把一部大型资料书定位为治国参考，而非书斋考据。「征诸人事」尤其值得注意，它意味着以人事实效检验制度记载，带有明显的经世取向。这一取向也解释了全书以食货居首的次序：杜佑认为理道之先在于行教化，教化之本在于足衣食，谷帛不足则教化无从谈起。</p>
            <p>价值在于，它以制度为纲，把分散的典章沿革编成通史，开创「三通」谱系，郑樵《通志》、马端临《文献通考》续之；也为研究唐代财政、军事、选举提供了系统材料。局限是，全书以抄录文献为主，考辨不多，礼门篇幅畸重而分析较薄；杜佑的立场是官僚本位，对民间社会着墨有限。使用时须注意其材料多转引前史，应回溯原文。</p>
        `,
