            <p>「能具史识者，必知史德」承刘知几才、学、识三长而增一德，三长之说见于《旧唐书·刘子玄传》；「德者何？谓著书者之心术也」，心术指史家的内在修养与用意，不是外加的规范。章氏由此要求史家慎辨于天人之际，尽其天而不益以人，即不以私意增损事实；他反对的正是以气与情干扰记事，而非取消判断。</p>
