            <p>「荧惑」在此指人心惶惑、议论纷然，不是火星，也不是妖异。「不比周隋之主」是先扬后抑：承认太宗神武，随即指出正因声名太盛，更不能承受失败。「兵若渡辽，事须克捷」点出渡辽之后没有退路，粮运、天寒、归师都成问题。末句以万一不获起，接以必更发怒、再动兵众，直指隋炀帝三征的旧辙：一次失利会迫使朝廷加码，直到安危难测。全段以假设句层层推进，是谏诤文字的典型句法。</p>
