// ===== 专题研究 =====
const research = [
    {
        id: "tang-goguryeo-background",
        title: "“唐代东北亚国际格局：高句丽、百济、新罗与唐的四方博弈”",
        date: "2026-06-14",
        tags: ["唐与高句丽", "东亚史", "国际关系"],
        summary: "唐初的东北亚并非唐与高句丽的双边对峙，而是唐、高句丽、百济、新罗四方，再加不时介入的倭国与漠北突厥共同构成的体系。高句丽据辽东与半岛北部，百济联倭以制新罗，新罗则以称臣纳贡换取唐朝支持。理解这一格局的地理基础、制度往来、各国动机与联盟转换，是理解此后七十年战争的前提。",
        content: `
            <p>七世纪的东北亚，并非只有唐与高句丽两方的对决。至少四方势力——唐、高句丽、百济、新罗——外加不时介入的倭国和漠北的突厥，构成了一个多极化的国际体系。</p>
            <p>这一体系的形成有其地理基础。辽东半岛与朝鲜半岛北部山多平地少，河谷切割出狭窄的农耕带；半岛南部的汉江与洛东江流域则适宜稻作。地理的碎片化使这一区域难以出现单一中心，也使任何外来势力都必须借助本地盟友才能立足。</p>
            <p>体系运转依靠一套制度化的往来形式。唐朝以册封、朝贡、质子与赐物维持与三国的上下名分，三国则借此获取贸易机会与军事背书；使节多沿辽东陆路与黄海海路往来，行程动辄数月，信息传递的滞后本身就影响决策。</p>
            <p>高句丽自公元前37年立国，至唐初已立国六百余年，是东北亚最古老的政治实体之一。其疆域覆盖辽东半岛和朝鲜半岛北部，占据农耕与游牧的交接地带，军事传统深厚。</p>
            <p>高句丽的国力基础在于对辽东与半岛北部的双重控制。它经营辽东山地的城邑与铁矿，又通过互市获取草原马匹；军事组织以城为单位，山城与平原城相互呼应。隋文帝与隋炀帝先后发动数次大规模征讨而无功，很大程度上即因这种纵深防御难以被一次性击穿。</p>
            <p>高句丽的政治结构也不是高度集权的官僚国家。王权之下有诸多城邑集团与部族首领，中央通过联姻、赐爵与军事征调维持协调；这种结构在防御时韧性很强，在中央权威动摇时却容易迅速离散。</p>
            <p>百济位于半岛西南部，与高句丽同属扶余系民族。百济与倭国保持着密切的联盟关系，是牵制新罗的重要力量。</p>
            <p>百济的地缘处境比高句丽更为窘迫。它西临黄海，与中原的海路联系最为便捷，却又必须面对新罗在东侧的持续挤压。因此百济的外交长期在两条线之间摆动：向唐纳贡请封以换取承认，同时联合倭国与高句丽牵制新罗。两面下注在唐初尚可维持，一旦唐朝决意介入半岛事务，便迅速失效。</p>
            <p>新罗位于半岛东南部，在三国中实力最弱，但外交手腕最为灵活。新罗主动向唐称臣纳贡，利用唐朝的力量制衡高句丽和百济。新罗的战略是“以唐制敌”——事实证明，这一策略最终为它赢得了整个半岛。</p>
            <p>新罗的优势不在兵力而在制度与情报。它较早接受唐朝的册封与律令格式，遣唐使与质子往来频繁，因而对唐朝的决策节奏有较准确的判断。真德女王与金春秋时期，新罗把求援本身当作战略工具：每一次遣使求救，都在把唐朝一步步拉入半岛战争。</p>
            <p>唐太宗即位后重新评估了东北亚局势。贞观十七年（643年），新罗遣使求救，称百济联合高句丽攻占其四十余城。太宗以此为由，于贞观十九年（645年）亲征高句丽。</p>
            <p>唐的目标并非自始即为灭国。太宗初期的措辞是恢复辽东故地、惩罚高句丽对新罗的侵扰；直到战事推进，灭国之议才逐渐浮现。目标的模糊性，后来成为唐军在形势不利时难以宣称胜利的原因之一。</p>
            <p>贞观二十二年，金春秋亲自入唐，请求唐朝出兵夹击高句丽，并借机考察唐廷的军事准备与礼仪制度。此事常被视为新罗外交的转折：此后新罗不再只是被动求援，而是主动参与唐的作战规划，甚至在战利分配上开始讨价还价。</p>
            <p>倭国的介入使局势更加复杂。七世纪中期，倭国在半岛南部的利益主要通过百济体现；百济灭亡后，倭国出兵救援，663年白江口一役水战失利，此后长期未再大规模介入半岛事务。</p>
            <p>突厥因素同样不可忽略。唐初的东突厥、此后的薛延陀与后突厥汗国，牵制了唐朝北方的兵力；太宗亲征高句丽时，北方防线仍须重兵留守，这直接限制了可投入辽东的兵力上限。东北与漠北两个方向，在唐朝的战略盘算中始终相互牵扯。</p>
            <p>靺鞨与室韦等部族虽未形成独立的大国，却在各方之间充当兵力与马匹的供应者。高句丽曾征调部分靺鞨部众，唐朝也以官职与赐物招抚其首领；这些边缘势力的向背，往往在具体战役中产生超出其规模的影响。</p>
            <p>从今天的视角回望，唐与高句丽的战争不只是两国间的冲突，而是东北亚国际秩序的一次深刻重组。战争的结局——高句丽的灭亡、新罗统一半岛——奠定了此后数百年东北亚政治格局的基本框架。</p>
            <p>联盟关系在七世纪中期完成了一次关键转换。唐与高句丽的对抗原本夹杂着恢复旧壤与惩戒侵扰的双重动机；百济灭亡后，唐朝在半岛的存在从盟主变为占领者，新罗的处境也随之从求援者变为竞争者。盟友之间的边界问题，有时比敌国之间的战争更难处理。</p>
            <p>学界对这套格局的解释并不一致。一种看法强调唐朝的主动建构，认为册封与羁縻体系把半岛纳入天下秩序；另一种看法强调半岛三国的能动性，认为新罗才是真正的受益者与操盘者。近年研究更倾向于把两者结合：唐朝提供秩序框架，半岛势力在其中寻找自己的位置。</p>
            <p>若把视野放宽，这场博弈还牵动了日本列岛与后来的渤海国。高句丽灭亡后，其遗民部分北迁，参与渤海国的建立；半岛与列岛之间的移民与技术流动，反而在战后更加频繁。格局的重组不只意味着某一方的覆灭，也意味着新的通道被打通。</p>
            <p>从长时段看，七世纪的这场重组确定了此后数百年的基本框架：中原王朝在辽东设治而不常驻重兵，半岛中南部形成统一政权，日本列岛则以摄取大陆制度为主线。战争只是这一框架形成的触发点，真正沉淀下来的是交通、册封与贸易的网络。</p>
        `,
    },
    {
        id: "tang-taizong-campaign",
        title: "“唐太宗征高句丽：一场不完美的胜利”",
        date: "2026-06-13",
        tags: ["唐与高句丽", "战争", "李世民"],
        summary: "贞观十九年，唐太宗亲率水陆大军征讨高句丽，连下辽东十余城，却在安市城下受阻，因雨季、粮运与严寒被迫撤军。此役战果可观而未竟灭国之功，暴露出府兵远征、补给线过长与辽东气候的三重限制。太宗晚年改行疲敌之策，把决战转为消耗，为高宗朝最终灭国埋下伏笔，此役也成为太宗朝对外用兵的转折点。",
        content: `
            <p>贞观十九年四月，唐太宗率军从洛阳出发，水陆并进直指辽东。这是他一生中唯一一次亲自指挥的大规模对外战争，也是他帝王生涯中少有的未竟全功之举。</p>
            <p>出兵的兵力构成值得注意。唐军以府兵为主力，另配营州、幽州边兵与契丹、奚等蕃族骑兵；水路由张亮统率，自莱州渡海直趋辽东半岛南端。水陆两路的会合点选在辽东城下，说明首要目标是夺取辽河以东的城邑群，而非直取平壤。</p>
            <p>战前的准备持续了将近一年。唐廷在营州集结粮秣、修治道路，并遣使联络新罗与奚、契丹，试图在侧翼形成牵制；同时以诏书责问高句丽，为其后出兵提供名分。这种先外交后军事的顺序，是太宗用兵的惯常做法。</p>
            <p>军中将领的构成也反映了唐初军事体系的特点。李勣、李道宗、张亮各领一路，契丹与奚的首领以蕃将身份随征；这种汉蕃混编、多路并进的部署，便于分散高句丽的守军，却也增加了协同的难度，各路之间的会师时间因此屡有延误。</p>
            <p>亲征的决定还带有政治考量。太宗即位以来，对外用兵多委之于将帅；晚年亲征，既有建立不世之功的意图，也有向朝野显示天子尚能统军的用意。这种个人化的决策方式，使战役的目标与节奏高度依赖太宗本人的判断，一旦受挫便难以调整。</p>
            <p>唐军攻克辽东城、白岩城等十余座城池，斩首四万余级。太宗在给房玄龄的信中写道：“朕率辽东之众，扫清玄菟之氛，所过城邑，望风款附。”</p>
            <p>辽东城的攻取显示了唐军在攻城技术上的优势。唐军使用抛车、撞车与土山，昼夜强攻；城破之后，太宗下令收敛战殁者骸骨、设祭祭奠，既安抚军心，也向辽东诸城传递归附可保的信号。战后唐在所得城邑设置州县，以行政建置巩固军事成果。</p>
            <p>白岩城等地的抵抗与归降交替出现，说明高句丽在辽东的防御并非铁板一块。部分城守由地方豪族把持，他们对中央的忠诚有限，更多依据自身利害决定降附；唐军的招抚政策因此与军事压力同等重要，赏格与赦令往往先于云梯到达城下。</p>
            <p>然而安市城久攻不下。守将杨万春据城坚守两个月，唐军围城期间正值辽东雨季，粮草不继。八月太宗被迫撤军。太宗慨叹：“魏征若在，不使朕行此役！”</p>
            <p>安市城的防御之所以成功，与其地形和守将的判断有关。城依山而建，外侧陡峭，唐军难以展开兵力；守将拒绝诱降，并当众处置主张投降者，以绝内部动摇之念。唐军在城下筑土山、昼夜强攻，土山崩塌压毁城墙一段，却因守军迅速堵塞而未成突破口。</p>
            <p>后勤是此役的关键变量。唐军自幽州、营州一线转运粮秣，路程数百里，途中须穿越辽泽沼泽；雨季到来后道路泥泞，车运几乎停滞。太宗一度令就地取粮于敌境，但辽东城邑多已残破，难以供给大军；粮尽与天寒叠加，撤军遂成唯一选项。</p>
            <p>撤军本身也充满风险。唐军在归途中遭遇暴风雪，士卒冻死、马匹倒毙者甚众，太宗亦因受寒而病。此役唐军战果可观而代价不小，史书对伤亡数字的记载互有出入，但普遍承认这是一次消耗巨大的远征。</p>
            <p>此战暴露了唐军远征的弱点：高句丽城池坚固、后勤补给线过长、辽东气候制约军事行动。太宗撤军后采取持续骚扰策略消耗高句丽的国力，这一策略后被高宗继承并最终见效。</p>
            <p>从制度层面看，此役暴露的另一个问题是府兵制下远征的动员极限。府兵自备资装，服役有期限，长期屯驻辽东会打乱农时与轮番宿卫的安排；唐廷此后在辽东方向更多依赖营州边兵与归附蕃族，正是对这一限制的回应。</p>
            <p>太宗晚年的战略调整值得注意。他不再追求一次性灭国，而改为每年以偏师袭扰高句丽的农耕区，破坏其收成与城邑修缮。这种疲敌策略成本低、见效慢，却把战争从决战转为长期消耗，为高宗时期的灭国创造了条件。</p>
            <p>战后的外交并未完全中断。双方在战后又恢复朝贡与交涉，高句丽遣使谢罪，唐亦以册封与回赐维持表面往来。战争与外交并行，是七世纪东亚国家间关系的常态；军事上的失利并不必然导致关系断裂。</p>
            <p>后世对此次亲征的评价分歧明显。传统史家多惋惜其功败垂成，强调太宗晚年用兵过度的教训；现代研究更关注战役的组织、后勤与情报层面，认为唐军在战术上并不失败，失败的是把一次惩罚性远征当作灭国战争来期待的政治设想。</p>
            <p>与隋炀帝的征讨相比，太宗的规模较小而组织较严密。隋军动员号称百万，后勤与指挥都超出当时的技术条件；唐军则依托营州与海运，兵力相对精简。两次远征的结局相似，原因却不完全相同：前者败于动员过度，后者败于目标过高。</p>
            <p>此役对高句丽的影响同样深远。唐军虽退，高句丽在辽东的城邑与人口损失惨重，国力进一步削弱；其对唐朝的戒备随之加深，此后在半岛事务上更依赖与百济的协调，而这恰恰落入唐军先取百济的方略之中。</p>
            <p>关于此役的记载主要见于《旧唐书》《新唐书》与《资治通鉴》，三者的详略与倾向不尽相同。本纪文字偏向铺陈战果，通鉴对撤军的叙述则较为直白；比对不同记载，才能看出战果与代价之间的落差，也才能理解太宗晚年为何对此次用兵反复致意。</p>
        `,
    },
    {
        id: "tang-goguryeo-fall",
        title: "“高句丽的灭亡：从内部看一个王朝的崩溃”",
        date: "2026-06-12",
        tags: ["唐与高句丽", "战争", "灭亡原因"],
        summary: "总章元年，李勣攻破平壤，高句丽亡。唐朝先灭百济、再南北夹击的方略固然高明，但真正掏空这个七百年政权的，是渊盖苏文专权之后的继承内讧、长期战争造成的人口与仓储损耗，以及城邑联合体在中央权威失效后的迅速离散。高句丽并非集权国家，中央一旦失灵，地方降附便迅速蔓延。外部压力与内部裂痕互为条件，缺一不可。",
        content: `
            <p>公元668年九月，唐将李勣攻破平壤，高句丽末王高藏被俘，立国七百余年的高句丽覆灭。</p>
            <p>平壤的陷落并非孤立的围城战。战事后期，唐军先攻取辽东与半岛北部的枢纽城邑，切断高句丽各部分之间的联系；李勣随后南下，与新罗军会合于平壤城下。高句丽此时可调的野战兵力极为有限，守城成为唯一选择。</p>
            <p>灭国之后的处置延续了此前灭百济的模式：俘其王、收其府库、置都护府、迁其豪族。高藏被押送长安，后虽受封爵，实同羁縻；大批贵族与百姓被迁往中原及江淮一带。人口迁徙成为削弱地方抵抗的常规手段，也是唐朝处理亡国政权的制度惯性。</p>
            <p>从外部看，唐朝战略确实高明。唐高宗采纳了“先灭百济，再图高句丽”的方略。660年唐将苏定方跨海攻灭百济，此后唐与新罗南北夹击高句丽。</p>
            <p>先灭百济、再图高句丽的方略并非高宗一朝突然形成，而是太宗晚年消耗战的延续。百济灭亡使高句丽失去南面盟友，也使唐军获得从半岛南部北上夹击的通道；新罗则由此从被保护者变成进攻链条上的一环。</p>
            <p>唐军在灭国战中的技术优势同样重要。唐军善于使用攻城器械与水路运输，能在辽东与半岛西海岸之间灵活调动；高句丽的山城防御虽坚固，却难以应对多点登陆与长期封锁。当陆路与海路同时被切断，平壤的粮储便迅速耗尽。</p>
            <p>但外部压力只是催化剂。高句丽末年权臣渊盖苏文当政，对内残杀政敌、对外穷兵黩武。渊盖苏文死后诸子内讧，长子渊男生投奔唐朝成为唐军向导——这几乎是高句丽版的“开门揖盗”。</p>
            <p>渊盖苏文的执政本身建立在政变之上。他在642年杀荣留王、立宝藏王，自任莫离支，把王权置于军府之下。这种以军事强人维持的体制在对外战争中效率很高，却缺乏权力交接的制度安排；一旦强人去世，继承问题便直接演变为内战。</p>
            <p>渊盖苏文死后，长子渊男生与弟渊男建、渊男产争权，男生失利后据城自守，遣子入唐求援，并引导唐军进攻。这一选择常被后世视为卖国，但放在高句丽的政治结构里看，它更接近于一次失败的内战方寻求外援的常规操作。</p>
            <p>高句丽末年的人才流失同样值得注意。长期战争与内部清洗使一批能战的将领或死或降；渊男生引唐军入境后，原属其部的城邑纷纷倒向唐军。军事精英的离散，往往比城池的失守更能说明一个政权的末期状态。</p>
            <p>唐朝在选择进攻时机上也颇为讲究。灭国战的最后阶段在秋季推进，避开辽东的雨季与泥泞，又赶在封冻之前完成围城；粮运依托此前数年经营的营州与海运路线，比太宗亲征时更为顺畅。时机与后勤的改善，是灭国战得以速决的技术条件。</p>
            <p>从598年到668年，中原王朝对高句丽的大规模征讨不下十次。持续七十年的战争，对高句丽的人口和经济造成了难以估量的破坏。高句丽的军事技术可以守住城池，但其国力远不足以支撑与大一统王朝的长期消耗战。</p>
            <p>长期战争对高句丽社会的破坏是多层的。青壮年被征发从军，农耕劳力短缺；城邑反复修葺又反复被毁，仓储难以积累；贵族在战争中扩张私兵，中央对地方的控制反而减弱。这些结构性损耗不会立刻导致崩溃，却使国家在最后阶段失去动员余地。</p>
            <p>人口数字是理解这场崩溃的关键，也是史料最薄弱之处。现存记载中的户数与口数往往出自不同来源，彼此矛盾；学界通常只能给出数量级的估计，无法确定具体规模。可以确定的是，高句丽灭亡后迁出的人口相当可观，故地一度出现城邑空虚的景象。</p>
            <p>学界对灭亡原因的争论集中在外部压力与内部政治各占多少比重。一种解释强调唐朝综合国力的压倒性优势，认为灭亡只是时间问题；另一种解释强调高句丽末年权力结构的崩解，认为若无内讧，战争可能长期僵持。折中的看法把两者视为互为条件：外部压力放大内部裂痕，内部裂痕又为外部进攻提供入口。</p>
            <p>还有一层容易被忽略：高句丽并非单纯的集权国家，而是由多个城邑集团与部族联合而成的政治体。中央权威依赖对这些集团的协调，一旦协调机制失效，各地的降附与观望便迅速蔓延。灭国之战中大量城邑不战而降，正说明这种联合体的脆弱。</p>
            <p>与百济的灭亡相比，高句丽的崩溃更为缓慢而彻底。百济在660年一战而亡，其王室与贵族被整体迁走，复国运动虽持续数年却缺乏统一核心；高句丽则经历了近七十年的战争消耗与一次继承危机，灭亡之后遗民的反抗更为分散，也更容易被各个击破。</p>
            <p>遗民的去向塑造了战后的东北亚。部分高句丽贵族入唐为将，部分百姓被迁往中原，另有相当数量的人北迁，与靺鞨部众共同参与渤海国的建立。一个政权的覆灭，往往以人口流动的方式在邻国留下长期痕迹。</p>
            <p>从史料角度看，高句丽一方的记载留存极少，今人对其内部情形的了解，主要依赖中原王朝的史书与少量金石材料。这种视角的不对称，使高句丽的决策动机常被简化为服从或对抗，其内部的政治计算反而难以复原。</p>
        `,
    },
    {
        id: "tang-annandong",
        title: "“安东都护府：唐朝对高句丽故地的统治及其困境”",
        date: "2026-06-11",
        tags: ["唐与高句丽", "统治政策", "安东都护府"],
        summary: "灭亡高句丽后，唐在平壤设安东都护府，下辖九都督府四十二州，试图把辽东与半岛北部纳入直接统治。然而遗民抵抗、新罗北进、吐蕃牵制与后勤成本叠加，都护府不到十年便内迁辽东，继而退往辽西、幽州。它的收缩说明边疆统治取决于成本与收益的平衡，也取决于本地合作者的向背；这不足十年的经营更像一次多方试探，而非单向的统治实验。",
        content: `
            <p>总章元年（668年）唐在高句丽故地设立安东都护府，治所在平壤。这是中原王朝势力在朝鲜半岛达到的最大范围。</p>
            <p>都护府的建置并非凭空设立。唐在灭百济后已置熊津都督府，灭高句丽后又将故地划分为九都督府、四十二州，以高句丽旧官与唐将分领，并于平壤置重兵；安东都护府统摄其上。这套安排借用了羁縻府州的形式，却比羁縻更强调直接控制。</p>
            <p>治所的选择本身就有争议。平壤位于半岛西北，既是高句丽的旧都，也靠近唐军海运的登陆点；但对唐朝而言，它距辽东与幽州过远，补给须跨海或穿越辽东山道。行政中心与补给基地的分离，是都护府后来内迁的深层原因之一。</p>
            <p>安东都护府面临重重困难：高句丽遗民的武装抵抗、新罗向北扩张蚕食故地、后勤补给成本过高等。仅670年至672年间就爆发了多次大规模反唐起事。</p>
            <p>遗民抵抗的组织形式值得分析。起事者多为原高句丽的城守与地方豪族，他们以恢复旧国为号召，依托山城与乡里网络展开游击；唐军虽能攻破城邑，却难以长期驻守每一处山谷。镇压与安抚交替进行，消耗了大量兵力。</p>
            <p>新罗的角色在此期间发生转变。作为唐的盟友，新罗在灭国战中出兵助战；灭国之后，新罗迅速向北推进，收纳原高句丽的南部城邑，并就边界与俘虏归属与唐朝发生争执。盟友关系的破裂，使都护府南面始终处于压力之下。</p>
            <p>670年至672年的冲突并非偶然。唐此时正与吐蕃在西线激战，关中与陇右的兵力被大量牵制，无力向东北增援；新罗抓住这一窗口，支持高句丽遗民起事，并出兵攻取唐在半岛的据点。多线作战的限制，在这里体现得格外清楚。</p>
            <p>都护府的军队来源也限制了它的行动方式。驻军多为轮番戍守的府兵与配属的蕃兵，缺乏长期驻屯的地方根基；一旦轮换周期与农时冲突，兵力便出现空档。相比之下，新罗的军队在本土作战，动员与补给都更为便利；唐军每逢战事须先从辽东或山东调集，战役节奏因此常被后勤牵着走。</p>
            <p>唐朝对高句丽旧官的任用是一把双刃剑。以旧官治理旧地，可以减少反抗、迅速建立秩序；但这些官员与本地豪族关系密切，在唐与新罗冲突时往往态度暧昧。都护府的政令能否贯彻，取决于这些中间人的合作程度。</p>
            <p>仅过了不到十年，676年安东都护府便从平壤内迁至辽东，此后又陆续内迁至辽西、幽州。这个过程说明：帝国的边界不仅取决于军事征服的能力，更取决于行政统治的成本与收益的平衡。</p>
            <p>内迁的每一步都伴随辖区的收缩与属州的废置，而不只是治所的迁移。都护府初辖数十州，退至辽东后属州陆续废置，退至幽州时已仅存名号；行政机构一步步后退，实际上是把直接统治改回间接控制，辽东留给营州与羁縻州，半岛交给新罗。</p>
            <p>从制度史的角度看，安东都护府的困境并非孤例。唐在西北的安西四镇、在漠北的安北都护府，都经历过类似的伸缩；边疆治理依赖交通、粮运与本地合作者三项条件，任何一项不足，直接统治便难以为继。</p>
            <p>成本问题尤其关键。维持一个远离核心区的都护府，需要常年转运粮秣、轮换戍卒、修治道路与烽燧；这些支出能否换来稳定的赋税与兵源，往往短期内看不出来。唐朝的选择是现实的：收益不足以覆盖成本时，宁可收缩，也不愿让边镇变成财政无底洞。</p>
            <p>本地行动者的选择同样决定了统治的成败。高句丽故地的豪族在唐、新罗与渤海之间反复权衡，他们的去向决定了地方秩序的重建方式；唐朝若不能把这些力量纳入新的利益结构，都护府的政令便只能停留在城邑之内。</p>
            <p>安东都护府的遗产并不全然消失。它留下的州县名号、交通路线与户口记录，后来被渤海国与新罗分别继承和改写；唐朝与半岛之间的册封、朝贡与贸易网络，也在都护府内迁之后继续运转。制度可以撤退，交往的网络却会沉淀下来。</p>
            <p>学界近年更强调从本地社会看这段历史。把安东都护府仅仅看作唐朝政策的失败，会忽略高句丽遗民、新罗边将与地方豪族在秩序重建中的主动作用；都护府不足十年的经营，更像是一次多方试探的过程，而非单向的统治实验。</p>
            <p>与熊津都督府的经历对照，可以看到唐朝在半岛的制度尝试有共同节奏：先以军事胜利设治，再因补给与本地抵抗而收缩，最后把直接统治转换为册封关系。这一节奏在此后的东北亚反复出现，成为中原王朝经营半岛的一种模式。</p>
            <p>安东都护府的内迁还有一层象征意义。治所从故都平壤退回辽东，等于放弃了以半岛为行政中心的构想；此后唐朝对半岛事务更多通过册封与使节施加影响，军事存在的比重下降，外交与贸易的比重上升。</p>
            <p>都护府的内迁也改变了唐朝的东北防线。此后唐在辽东的经营更多依托营州与平卢军镇，防线从半岛退至辽西，东北的军事重心随之西移；这一布局延续到安史之乱前夕，并深刻影响了河北藩镇的形成。</p>
        `
    },

    {
        id: "sui-goguryeo-campaigns",
        title: "隋征高句丽：大业年间三次东征的失败逻辑",
        date: "2026-08-05",
        tags: ["隋与高句丽", "战争", "隋炀帝"],
        summary: "612至614年，隋炀帝三次征讨高句丽，百万大军久困于辽东坚城之下，萨水一役九军溃散，生还者寥寥，杨玄感之乱又迫使仓促撤军。远征的失败不只是军事问题，更暴露了隋朝强大动员能力与僵化战略决策之间的巨大落差。后勤、指挥与时机，构成了三次远征共同的失败逻辑，也把大业盛世推向了崩溃的边缘。",
        content: `
            <p>大业八年（612年），隋炀帝第一次征讨高句丽，发兵一百一十三万，号称二百万。这支史无前例的大军以兵团编制有序推进，却在高句丽坚固的辽东城下陷入僵持。隋炀帝要求诸将不得专决军机，凡攻守进退皆须奏报，贻误战机，致使大军疲于奔命。</p>
            <p>辽东城下的僵持并非隋军第一次在辽东受挫。开皇十八年，高句丽婴阳王联合靺鞨进扰辽西，隋文帝命汉王杨谅统三十万军出塞，正值雨季，粮道断绝，军中疫病流行，回师时人马死者十之八九。此后高句丽遣使谢罪，双方维持了十余年的表面安宁，但辽东城防与辽水一线的堡戍在这段时间里被反复加固。</p>
            <p>大业七年的备战把这种安宁彻底打破。诏令天下丁男征发，民夫转运粮械于道路，死者相枕；东莱海口造船的工匠昼夜立在水中，腰以下溃烂生蛆。隋朝能在短期内聚合如此规模的人力物力，说明其行政机器运转高效，也说明这种效率以透支基层社会为代价。</p>
            <p>辽东城的攻防持续了整个春夏。隋军造飞楼、撞车、云梯，又掘地道相攻，守军随机应变，以火与滚木应对；炀帝还令每军设置受降使者，高句丽守军数次诈称请降以拖延工期，前线将领因之不敢强攻。坚城之下，百万之众的优势被逐日消磨。</p>
            <p>第一次东征的转折点发生在萨水。宇文述率九军三十余万渡鸭绿江追击高句丽军，被诱敌深入、伏击于萨水之滨，一夜之间溃不成军，生还者不足两千七百人。隋军不是败于兵力，而是败于指挥系统的僵化与轻敌冒进。</p>
            <p>萨水之败的直接原因，是前线将领在信息不对称下的判断失误。高句丽大臣乙支文德先以诈降入营窥探虚实，脱身后又遣使相激；宇文述等九军渡江后一日七战皆捷，遂轻装急进，直到平壤城下三十里才发现城防险固、士卒疲敝、粮秣已尽。撤军半渡之际被伏兵冲击，九军溃散，生还者寥寥。</p>
            <p>更值得注意的是，萨水之后隋军并未立刻全线崩溃，辽东城下的主力仍在，水军也已抵达平壤附近。真正使第一次东征无法收场的是指挥层对败报的反应：炀帝既不愿承认失利，也没有收缩战线的预案，大军在辽东与辽西之间滞留，粮运压力持续放大，最后只能以撤军收场。</p>
            <p>水陆两路的脱节同样致命。来护儿率江淮水军自东莱渡海，直抵平壤附近，一度攻入外城，却因陆军未至、孤军深入而被迫退走。此后水军只能在海上游弋，无法与辽东主力形成夹击，高句丽得以集中兵力各个应对。</p>
            <p>大业九年（613年）的第二次东征，正当辽东战事胶着之际，杨玄感在黎阳举兵反隋，隋炀帝被迫仓促撤军回援。第三次东征（614年）则在高句丽求和后草草收场，隋炀帝虽以胜利者自居，却已无力回天。</p>
            <p>杨玄感之乱的时机，恰好利用了东征造成的后方空虚。他身为杨素之子，在黎阳督运粮草，以替天下解倒悬为号召起兵，李密为之谋划上中下三策，玄感却取了攻取东都的下策。叛乱在数十日内被平定，但炀帝不得不放弃已经展开的辽东攻势，第二次东征由此不了了之。</p>
            <p>第三次东征的规模已明显收缩。来护儿率水军自东莱入海，直趋平壤，高句丽遣使请和，送还叛将斛斯政。炀帝顺势接受，班师回朝，把求和包装成臣服。此时山东、河北的民变已成蔓延之势，朝廷再没有组织第四次远征的能力。</p>
            <p>三次东征暴露的根本问题，是隋朝高效动员能力与低效战略决策之间的巨大落差。隋能调动百万大军，却无法将这种力量转化为战场上的灵活指挥；隋炀帝将战争视为个人意志的延伸，却忽视了后勤极限与政治风险。东征的失败直接激化了国内矛盾，成为隋末大起义的重要导火索。</p>
            <p>把三次东征放回制度脉络里看，失败带有结构性。隋以府兵与征发民夫相结合的动员方式，擅长一次性聚合资源，却不具备支撑长期远征的后勤官僚体系；军权高度集中于皇帝，前线将领须层层奏报，面对高句丽以诈降、坚壁清野拖延战局的打法，反应总是慢一步。</p>
            <p>战略目标同样摇摆。炀帝既要收复汉四郡旧地，又要以天子亲征树立威望，还要确保辽西与河北的安全，几重目标在战场上的优先次序从未被清晰排定。高句丽则把战争定义为防守，用坚城、山地与季节拖住远征军，把胜负交给时间。</p>
            <blockquote>隋征高句丽的教训在于：一个王朝的动员能力越强，其战略决策的失误所造成的破坏也越深。百万大军不只是国力，更是一种需要审慎驾驭的力量。</blockquote>
            <p>三次东征的代价最终落在隋朝自身。大业七年以后的连续征发，使河北、山东的青壮年大量脱离生产，辽东之役的伤亡与粮运的苛扰叠加，民变由此蔓延。一个能够动员百万大军的王朝，在不到十年间失去对基层的控制，这条因果链是理解隋亡的关键。</p>
            <p>隋亡之后，唐太宗、唐高宗汲取了部分教训，以更灵活的战略最终平灭高句丽。但隋朝三征的失败，始终是理解隋唐之际历史转折的重要一章。</p>
            <p>唐朝的后续经验说明问题不在目标本身。唐太宗亲征受阻于安市城，同样未能一举成功；唐高宗改为水陆并进，先灭百济再南北夹击，并以新罗分担陆上压力，经过长期围困才在668年攻灭高句丽。方法、节奏与盟友的选择，往往比兵力数字更具决定性。</p>
        `
    },
    {
        id: "baekgang-east-asia",
        title: "白江口之战的东亚意义：海权与朝贡秩序",
        date: "2026-08-03",
        tags: ["唐代", "白江口", "海权"],
        summary: "663年白江口之战，唐军以七千余人、一百七十艘战船大破倭国水军，焚其战船四百余艘，百济复国运动随之终结。此战之后，半岛局势与倭国的国家转型同时被改写，唐朝在东亚朝贡秩序中的核心地位由此确立。战事规模有限，影响却绵延千年。一场海战如何重塑七世纪东亚的国际结构，海权在其中又扮演了什么角色？",
        content: `
            <p>龙朔三年（663年）的白江口海战，唐军以劣势兵力大破倭国水军。这场战役的直接战果是百济复国运动的终结，但它的历史意义远不止于此——它标志着东亚海权格局的一次根本性重组。</p>
            <p>要理解白江口的胜负，须回到660年。唐与新罗联军攻灭百济，义慈王被押送长安，唐在百济故地设置熊津等五都督府。但百济的复国运动随即而起，鬼室福信拥立故王子扶余丰，据周留城等地抵抗，并向倭国求援，半岛西南部由此成为三方角力的战场。</p>
            <p>倭国对半岛的介入有其自身逻辑。齐明天皇与中大兄皇子把百济视为藩属与前沿，先后派兵护送扶余丰归国，并筹划更大规模的远征。唐军在百济的据点只剩熊津城一带，刘仁愿、刘仁轨以孤军固守，靠新罗的粮运与策应维持，双方都在等待对方先露出破绽。</p>
            <p>战前，倭国长期通过百济间接介入半岛事务，形成与唐朝对抗的松散联盟。白江口战败后，倭国彻底放弃了对半岛的军事野心，转而全面转向对唐学习。从663年到894年停派的二百余年间，遣唐使的航船频繁往来于东海之上，将唐朝的制度、宗教与文化源源不断输入日本。政治上的失败，意外地开启了文化上的深度交流。</p>
            <p>663年八月，倭国水军护送百济余部北上，与唐军在白江口相遇。据《日本书纪》，倭军战船千余艘；唐军仅有战船一百七十艘、兵七千余人。唐军四战皆捷，焚毁倭船四百余艘，海水为之变色。扶余丰脱身逃往高句丽，百济复国运动至此失去外援与核心。</p>
            <p>战役的胜负很大程度上由船制与战术决定。唐军多用楼船、艨艟，船体高大，便于居高临下施行火攻与弓弩压制；倭船小而密集，一旦火势蔓延便难以脱离。加之白江口处于锦江入海口，潮汐与水流限制了两侧阵形的展开，数量优势无法转化，反而加剧了混乱。</p>
            <p>百济复国阵营内部并不团结。鬼室福信拥立扶余丰后握有实权，与王子之间的猜忌日深，最终福信被杀，复国军失去最有能力的统帅；周留城等据点各自为战，难以统一调度。外援未至而内部分裂，使百济一方在白江口之前就已失去组织优势。</p>
            <p>对半岛而言，白江口之战清除了百济复国与倭国介入的外部变量，使新罗得以全力应对唐朝的军事压力。此后数年，新罗一面与唐周旋，一面加速统一进程，最终在676年迫使唐军退出大同江以南。可以说，白江口之战间接促成了新罗统一半岛的历史进程。</p>
            <p>战后唐朝在百济故地设熊津都督府，以扶余隆为都督，迁其民入中原者不在少数；熊津、东明等地的行政建置与唐的羁縻体制接轨。百济王室与贵族部分进入唐朝的官僚与军伍，百济故地的社会结构由此被改写，复国的政治基础不复存在。</p>
            <p>倭国一侧的反应更为深远。天智天皇在战后迁都近江大津宫，于九州筑水城、设防人与烽燧，重整军制与地方户籍，并在此后数十年间以律令制重建国家。《大宝律令》的编纂虽晚至八世纪初，其制度蓝本却可追溯到战败带来的危机感与文化转向。</p>
            <p>从区域秩序的视角看，白江口之战确立了唐朝在东亚朝贡体系中的核心地位。此后近千年间，东亚各国无论实力如何消长，大体上都在这一秩序框架内互动。海权在其中扮演的角色值得深思：唐朝没有维持常备水军，却凭借关键战役中的绝对优势，塑造了区域海洋秩序的基本规则。</p>
            <p>朝贡秩序并非只有军事一面。唐以册封、羁縻州府、质子宿卫、定期朝贡与互市编织出一套等级关系，其运行依赖礼仪、名分与实际利益的交换。白江口之后，倭国、新罗与唐的往来被纳入这套框架，海路因此成为制度输送与人员流动的通道。</p>
            <p>朝贡体系这一概念本身也受到重新审视。传统叙述以唐朝为中心，强调册封与礼仪的等级性；近年的研究更注意各方的主动选择、贸易利益与多中心的实际运作，认为所谓秩序是不断协商的结果，而非单向的支配。白江口之战因此被放在更复杂的互动网络中理解。</p>
            <p>海权的限度也在这里显现。唐朝并未维持常备水军，战役中的舰队多为临时征调，战后亦未在半岛常驻海上力量；它依靠关键节点的胜利确立规则，再以陆上建置与外交安排维持秩序。研究者对此评价不一，有人认为这是低成本的主导，也有人指出其投射能力的脆弱。</p>
            <blockquote>白江口之战表明：在东亚朝贡体系中，海权的作用不在于持续霸占海面，而在于关键节点上确立无可争议的优势，从而为区域秩序奠定稳定基础。</blockquote>
            <p>史料层面的谨慎同样必要。白江口之战的主要记载见于《旧唐书》《三国史记》与《日本书纪》，三者立场各异，兵力数字往往带有夸饰。日本方面的记述强调己方动员之盛，唐与罗的记载则突出以少胜多。把数字当作精确统计来使用，容易得出过度推断的结论。</p>
            <p>长时段看，白江口之后的东亚海域进入相对稳定的时期。遣唐使的航线、新罗的商团与唐登州、楚州之间的贸易网络逐渐成形，九世纪张保皋的海上势力便依托这一格局而起。军事冲突让位于制度与商业的往来，海洋由此从战场转为通道。</p>
            <p>今天重提白江口之战，不仅是回顾一场战役，更是在追问：海洋力量如何在东亚秩序中发挥建设性作用？这一问题的答案，或许就藏在一千三百年前的那场海战里。</p>
        `
    },
    {
        id: "tang-silla-war-revisited",
        title: "唐罗战争再考：半岛主导权之争的始末",
        date: "2026-07-30",
        tags: ["唐代", "新罗", "唐罗战争"],
        summary: "668年唐罗联军攻灭高句丽，不到两年盟友反目。双方在城戍与粮道之间反复拉锯，新罗以山地游击牵制唐军，唐朝则因吐蕃西线告急而力不从心，在核算成本之后选择了体面的收缩。676年安东都护府内迁，半岛主导权之争以唐的事实退让告终。这场常被忽略的战争，如何改写了半岛与中原关系的走向？",
        content: `
            <p>668年，唐与新罗联军灭亡高句丽。然而不到两年，这对昔日的盟友便兵戎相见。新罗文武王金法敏不仅接纳高句丽遗民、招纳百济旧部，更向唐军占领区扩张，公然挑战唐朝在半岛的权威。</p>
            <p>战前的合作曾十分紧密。660年唐罗联军灭百济，663年白江口之战后百济复国失败，668年唐军攻破平壤，高句丽灭亡。新罗出兵出力，却在战后安排中收获有限：唐在平壤设安东都护府，以薛仁贵镇守，百济故地由唐直接控制，新罗期望的领土回报被大幅压缩。</p>
            <p>争端的性质也因此与灭国战争不同。唐罗之间并非要消灭对方，而是争夺半岛中南部城戍、人口与交通线的控制权，双方都避免全面动员，也都在交战的同时保留外交渠道。这种有限战争的特征，决定了战场上的胜负很难直接转化为政治结果。</p>
            <p>争端从百济故地开始。670年，新罗以助唐为名出兵，实际攻取百济旧境，扶余隆弃职奔唐，唐罗之间的盟友关系公开破裂。唐廷随即调兵反击，双方在石门等地交战，战事沿半岛中部的山地与河谷展开，补给线与城戍成为争夺焦点。</p>
            <p>唐罗战争的形态与唐对高句丽的战争截然不同。新罗军力远逊于唐，却深谙地形优势：半岛多山，交通不便，新罗以分散游击的方式牵制唐军主力，避免正面决战。唐军虽能攻占要地，却难以巩固统治——后勤补给线漫长，当地民众对新罗的认同远高于对远道而来的唐军。</p>
            <p>新罗的战法与其国力相匹配。它避免与唐军主力正面决战，转而围攻孤立的城戍、截断粮道、袭击运输队，并在获胜后迅速撤回山林。唐军虽屡次攻占要地，却难以长期驻守；一旦主力西调或粮尽，新罗便重新出现在同一片区域，形成反复拉锯的局面。</p>
            <p>唐军方面的指挥也并不稳定。薛仁贵、李谨行、高侃等将领先后被派往半岛，兵力从关中、辽东与山东各处抽调，编制屡次调整；将领之间权限交叉，遇到战事不利便易帅再战。这种轮换维持了压力，却难以形成连续的战役计划。</p>
            <p>唐军的困难首先是距离。从中原到半岛，陆路须经辽东，沿途人烟稀少、运费高昂；海路自登州、莱州出发，受季风与滩险限制，运量有限。熊津、平壤等地的驻军依赖水陆转运维持，一旦战事延长，粮饷与兵员的补充就成为比战场胜负更紧迫的问题。</p>
            <p>更关键的是唐朝的全球战略困境。670年代，吐蕃在西线大举扩张，攻陷安西四镇，唐朝被迫将精锐力量西调。与此同时，半岛的军事行动成本高昂、收益有限，与新罗维持和平反而更符合唐朝的利益。这种战略优先级的变化，使唐朝逐渐失去继续半岛战争的政治意愿。</p>
            <p>西线的压力有具体的时间坐标。670年唐军在大非川一役失利，安西四镇的守御随之动摇，河西与青海方向的军情接连告急。对唐朝而言，半岛是可以退让的边缘，吐蕃则是威胁关中与陇右的核心问题，兵力与粮饷的分配由此向西方倾斜。</p>
            <p>唐朝内部的政治节奏也在变化。高宗晚年多病，武则天逐步掌权，朝廷对边功的兴趣下降，更关注内部的权力重组与西线的吐蕃威胁。主事者并不认为半岛值得长期投入，只要新罗名义上仍称臣纳贡，实际的边界退让便可被包装成体面的安排。</p>
            <p>战事后期，新罗在海上也取得主动。676年前后，新罗水军在伎伐浦一带击败唐军，唐在半岛的据点进一步收缩。同年安东都护府自平壤内迁至辽东，唐朝在事实上放弃了对大同江以南的直接统治，新罗则把疆域推进到汉江流域与半岛东南部。</p>
            <p>676年，唐安东都护府从平壤内迁至辽东，标志着唐朝事实上承认了新罗对大同江以南的统治。唐罗战争由此告终：新罗完成了半岛统一，唐朝则得以集中力量应对西线威胁。此后二百余年，半岛与中原维持着"册封—朝贡"的稳定关系，直到十世纪半岛再度分裂。</p>
            <p>学界对这场战争的评价并不一致。起止年代有670年与669年等不同说法；新罗是否完成了半岛的统一，也取决于如何界定高句丽故地与百济旧境的实际控制；至于唐朝是否算作战略失败，则要将其与吐蕃战线的得失放在一起衡量。</p>
            <p>战争之后的关系反而趋于稳定。新罗持续遣使入唐，献方物、请封号，派遣宿卫与留学生；唐则通过册封与赐地确认既成事实，八世纪前期正式承认大同江以南归新罗。此后二百余年，双方以礼节与贸易维系关系，大规模的军事冲突不再出现。</p>
            <p>统一之后的半岛内部同样需要整合。新罗把高句丽故地的一部分遗民编入军伍与户籍，在旧百济与新得之地设置州郡，强化王权与地方城寨的联系；九州的巡守与五小京的设立，使以庆州为中心的统治结构趋于定型。战争带来的疆域扩张，反过来推动了新罗的国家建设。</p>
            <blockquote>唐罗战争揭示了一条重要的历史规律：当帝国的军事优势遭遇高昂的统治成本与分散的战略资源时，即便战场上未分胜负，政治的边界也会重新划定。</blockquote>
            <p>重新审视唐罗战争，能帮助我们跳出"军事胜败"的单一视角，看到古代帝国边疆战略中成本、意愿与时机等复杂变量的博弈。</p>
            <p>史料基础相对集中。《三国史记》提供了新罗一侧的编年与人事，《旧唐书》《新唐书》与《资治通鉴》记载唐廷的决策与用兵，《日本书纪》则保留了倭国对半岛局势的观察。几种记述互有出入，年代与地名的考订至今仍是研究的前提工作。</p>
        `
    },
    {
        id: "salsu-battle",
        title: "萨水之战：隋军东征的崩溃",
        date: "2026-11-20",
        tags: ["唐与高句丽", "隋唐", "军事史"],
        summary: "大业八年，隋炀帝以号称二百万之众东征，九军三十万五千人渡辽，水军自东莱直趋平壤。高句丽大臣乙支文德以请和窥探虚实，又以七战七退诱隋军深入。萨水半渡之际伏兵齐发，九军一夜溃散，还至辽东城者仅二千七百人。此役断送第一次东征，也把隋朝动员的极限与决策的僵化一同暴露，水陆脱节与指挥不一是溃败的直接缘由。",
        content: `
            <p>大业八年（612年），隋炀帝下诏征讨高句丽，天下兵马汇聚涿郡。史书所记总兵力为一百一十三万余人，号称二百万，转运粮械的民夫又倍于此数；真正渡过辽水进入高句丽境内的，是九军三十万五千人。九军每日发一军，前后相继，四十日方才发尽，旌旗鼓角相望于道。这个数字本身已说明战役的组织方式：它更像一次以声势压垮对手的示威，而非讲求速度的突袭。在涿郡集结的还有大批民夫，他们转运粮械，队伍与军队交错于道路。</p>
            <p>九军分道而进，目标指向平壤。宇文述出扶余道，于仲文出乐浪道，另有诸将分出辽东等道，约定会师于平壤城下；来护儿则统江淮水军自东莱入海，由海路直趋大同江口。水陆两路相距千里，中间隔着高句丽的纵深城邑，通信与协同从一开始就十分脆弱。隋廷把希望寄托在各路齐至、一举夺城的设想上，却未为任何一路的失利准备预案；每军又设受降使者，用意在招抚而非强攻，这使前线将领遇到诈降时更加迟疑。</p>
            <p>来护儿的水军先抵浿水，击败沿岸守军，顺势攻入平壤外城，纵兵剽掠。高句丽军伏于城内，待隋军散乱之际出击，水军大败，死者甚众；来护儿退泊海口，此后只能在海上游弋。水军的失利使陆军失去唯一可以牵制平壤的力量，而陆军对此几乎一无所知，仍按原定日期向鸭绿水推进。</p>
            <p>陆军渡辽水后先攻辽东城。隋炀帝亲临城下，却沿袭出征前定下的规矩：诸将不得专决，凡攻守进退皆须奏报。高句丽守军数次诈称请降，前线将领不敢乘机强攻，坚城之下的重兵被一日日消磨。隋军造飞楼、撞车，掘地道相攻，守军以火与滚木应对，城始终不下。辽东城未破，战役的时间表由此彻底打乱；等到宇文述一路南追时，其他各路仍滞留在城外围。</p>
            <p>六月以后，宇文述、于仲文率九军渡鸭绿水，追击高句丽大臣乙支文德。乙支文德先至隋营请和，实则观察虚实；他见隋军士卒面带饥色、阵伍不整，脱身而去。于仲文主张将其扣留，宇文述以诏令抚纳降者为由阻止；文德既遁，于仲文力主追击，宇文述不得已从之。这一场争执，后来被视为全军覆没的起点。</p>
            <p>乙支文德一路接战，一日七战，每战皆退。隋军每战小胜，便以为敌军溃散，遂弃辎重、轻装急进。据说他还遣人送去一首诗，讽谕隋将知足而止。这种以空间换时间的退却，把隋军拉长在半岛北部的山谷与河谷之间；等到平壤城下三十里处，士卒疲敝、粮秣已尽，宇文述才察觉城防险固，不敢再进。</p>
            <p>诸将议撤军，皆言士卒疲敝、不可复战，遂结阵而退。高句丽军尾随而至，且战且行，隋军昼夜不得休息。退至萨水时，大军半渡，伏兵自后猛击，阵形立时崩解；前面的人争相登岸，后面的人尚在涉水，指挥系统在极短的时间里失去作用。</p>
            <p>溃败极为彻底。据《资治通鉴》，隋军一日一夜退至鸭绿水，行程四百五十里；右屯卫将军辛世雄战殁，诸军不复成列。将吏弃军而走，士卒争渡，溺死者不计其数。所谓九军三十万五千，回到辽东城的只剩二千七百人，军资器械尽弃于道。这个数字近于全军覆没，在古代史书中亦属罕见。</p>
            <blockquote>《资治通鉴》卷一百八十一记此役结局：「初，九军渡辽，凡三十万五千，及还至辽东城，唯二千七百人，资储器械巨万计，亡失荡尽。」</blockquote>
            <p>败因首先是孤军深入与粮运不继。隋军每人负百日之粮，又须自带兵器甲仗，负重难行，遂有人将粮秣沿途埋弃；及至深入，军中已无余粮。高句丽以坚城与空野相对，既不与决战，也不留可供掠取的储积。远征军越是深入，补给线越是被拉长，而平壤附近的仓储与人口早已转移或坚壁；转运的民夫在道路上来回，死者相枕，后勤的损耗并不比战场上的伤亡轻。</p>
            <p>其次是情报与地形。乙支文德以请和为名进入隋营，亲眼看到隋军的疲态，这是隋军未能识破的一次侦察。半岛北部的河谷与山隘限制了兵力展开，隋军不熟悉道路与水文，只能跟着对手的退却方向走，越走越远离自己的粮道。再次是指挥不一：宇文述与于仲文意见相左，诸将又受制于临行前的诏令，遇事层层请示；水军与陆军各自为战，终未能形成夹击。</p>
            <p>萨水之败使第一次东征无法收场。辽东城下的主力尚在，水军也仍泊于海口，但朝廷既不愿承认失利，也没有收缩战线的预案，大军滞留于辽西与辽东之间，粮运压力持续放大，最后只能撤军。大业九年第二次东征，杨玄感在黎阳起兵，炀帝仓促回师；大业十年第三次东征，高句丽遣使请和，隋朝以体面的措辞结束了这场消耗。</p>
            <p>从长时段看，萨水不只是一次战术失败。它把隋朝动员能力的上限与决策机制的僵化同时暴露出来：能聚合百万之众，却不能把命令传到恰当的层级；能修造海船、开辟海运，却不能使水陆两路互相支援。此后不过数年，隋在民变中崩溃。唐朝后来经营辽东，改取水陆并进、先弱后强的方略，可视为对这一教训的反向回应。</p>
            <p>关于萨水的具体位置，通行说法以今清川江当之，也有学者提出异说；兵力数字出自中原史书，难免有夸饰与传抄之误。但九军溃散、资储荡尽这一结局，诸书所记一致，可以视为信史。</p>
        `
    },
    {
        id: "ansic-seige",
        title: "安市城之役：唐太宗攻坚的极限",
        date: "2026-11-19",
        tags: ["唐与高句丽", "唐太宗", "攻城战"],
        summary: "贞观十九年，唐太宗连下辽东、白岩诸城，进围安市。安市依山为城，守御坚固，唐军筑土山、昼夜强攻，土山崩塌压城而守军旋即堵塞缺口；薛仁贵白衣先登实发生于城东南的驻跸山之战。久攻不下，辽左早寒、粮运将尽，太宗只得班师。此役使唐放弃一举灭国的设想，改取长期消耗，为高宗朝先灭百济、再图平壤的方略留下伏笔。",
        content: `
            <p>贞观十九年（645年）五月，唐军攻拔辽东城；六月，白岩城归降。太宗随即引军南下，进围安市。安市位于辽东通往半岛的走廊上，城未下则唐军不敢越城而南，否则粮道与退路都暴露在高句丽守军的侧击之下。这一地理条件，决定了此后的三个月唐军只能顿于城下，而不能像隋军那样直趋平壤。唐军此次水陆并进，张亮所率水军自莱州渡海，攻取辽东半岛南端城邑，陆路主力则由太宗亲自节制。</p>
            <p>安市城的形制，学界一般比定为今辽宁海城一带的山城，具体遗址仍有争论。城依山势而筑，外侧坡陡，城垣随山脊起伏；攻方难以在狭窄的坡面上展开兵力，攻城器械的推进也受地形限制。这样的城不易强攻，却利于长期坚守，守军只要保住水源与仓储，便能拖住数量占优的唐军。山城的另一项优势是视野：守军可以俯瞰唐军营垒的调动，而攻方很难判断城内的兵力与储粮。</p>
            <p>守城者的姓名不见于中原正史。今本《旧唐书》《新唐书》《资治通鉴》记安市攻守甚详，却始终未留下城主之名；朝鲜后世文献所传的姓名，年代晚出，难以视为信史。可以确定的只是守军意志坚定：唐军数次强攻、数次招抚，城始终未降，城内也没有出现足以开城投降的动摇。</p>
            <p>安市被围之初，高句丽北部耨萨高延寿、南部耨萨高惠真率援军来救，号称十五万。太宗采纳李勣之策，先破援军于城东南的驻跸山。唐军分路夹击，高句丽军大溃，高延寿、高惠真率众请降。此战的战果，使安市彻底失去外援，也让唐军得以专心攻城。驻跸山一战的规模不小，援军若与城内守军会合，唐军将陷入腹背受敌的处境，因此太宗把破援军置于攻城之前。</p>
            <p>值得一提的是薛仁贵白衣先登的著名记载。此事发生在驻跸山破援军之时，而非登安市城：仁贵着白衣，持戟呼喝，率先冲入敌阵，太宗在远处望见，遣人询问白衣者是谁，战后加以拔擢。后世叙述常把它移到安市城下，与攻城混为一谈，实则两事相隔数日，性质也不同。</p>
            <p>援军既破，唐军全力攻城。李勣主攻南面，诸将分攻各门，昼夜不息；唐军又于城东南筑土山，高与城齐，欲藉此俯瞰城中、填塞城垣。抛车、撞车与云梯并用，石炮击城，城堞屡坏，守军随即以木石修补。攻城的技术并不落后，问题在于城垣可以反复修补，而唐军的粮运与士气无法反复补充；唐军营垒环绕城周，断绝出入，但城外的坡地狭窄，营地拥挤，士卒的疲劳也日积月累。</p>
            <p>土山一度成为胜负的关键。据《资治通鉴》，土山筑成后山体崩颓，压坏城墙一段，守军自缺口出战，夺据土山；唐军反攻三日不克。负责守山的果毅都尉傅伏爱因擅离所部而被治罪。此事的细节未必尽实，但它说明唐军在协同与临阵纪律上的疏漏，往往抵消了器械与兵力的优势。</p>
            <p>守军之所以能守，除了地形，还在于城内的组织。高句丽经营辽东城邑多年，守城有固定的分工：壮丁登城，老弱转输，妇女炊爨；城破之处即行堵塞，夜间缒城袭扰唐军营栅。唐军虽众，却必须在狭窄的坡面上轮番进攻，兵力优势无从展开，久攻之下反而疲于应付。高句丽在辽东经营城邑数百年，山城的储备与修缮有惯例可循，守将即便姓名不传，其组织能力仍可从唐军久攻不下推知。</p>
            <p>时间站在守军一边。围城进入八九月，辽左早寒，草枯水冻，士马难以久留；唐军的粮运自幽州、营州一线转输，穿越辽泽沼泽，雨季之后道路泥泞，车运几近停滞。太宗与诸将议班师，顾虑的正是粮尽与天寒，而非城下的一时胜负。</p>
            <p>九月初，唐军班师。据《资治通鉴》，太宗以安市城主守御甚固、有守节，赐绢百匹以褒之。回程遭遇风雪，士卒冻死、马匹倒毙者甚众，太宗亦因受寒而病。归途之上，他说了一句常被后人引用的话。</p>
            <blockquote>《资治通鉴》卷一百九十八记太宗班师后的感慨：「魏征若在，不使朕有此行。」</blockquote>
            <p>此役的军事意义，不在于唐军攻城的技艺不足，而在于攻坚成本与战略目标之间的落差。安市不下，唐军便无法安全南下；若绕过坚城直趋平壤，则后方城邑随时可能截断粮道，隋军在萨水的覆辙便是前车之鉴。太宗选择顿兵城下，正是不愿重蹈孤军深入的旧路，但这一选择同样把战役拖入了消耗。从战役层面看，唐军并非不能破城，而是不能在入冬之前以可接受的代价破城；这一判断后来被唐廷反复引用。</p>
            <p>对唐丽战争的走势而言，安市之役促成了方略的转变。唐廷此后不再追求一次亲征定局，而改以偏师袭扰高句丽的农耕区，破坏其收成与城邑修缮；高宗朝更进一步，先灭百济以取得半岛南部的登陆点，再南北夹击平壤。可以说，安市城下的三个月，把唐人的注意力从攻城器械转向了后勤、季节与盟友；此后唐军在辽东多取守势，等待高句丽内部生变，泉氏兄弟之乱便是这一等待的结果。</p>
            <p>史料方面，此役主要见于《旧唐书》《新唐书》与《资治通鉴》，三者详略不同；安市城的今地比定、土山的位置与城垣规模，至今仍有考古与历史地理上的讨论。守城者姓名既不可考，后世附加其上的种种传说，阅读时尤须与正史记载分开。</p>
        `
    },
    {
        id: "quan-brothers-coup",
        title: "泉氏兄弟之乱与平壤的陷落",
        date: "2026-11-16",
        tags: ["唐与高句丽", "高句丽内政", "灭国"],
        summary: "乾封元年泉盖苏文死后，长子泉男生与弟泉男建、泉男产争权，男生据国内城自守，遣子献诚入唐求援。唐以李勣为辽东道行军大总管，分道进击，新城、扶余城相继失守。总章元年平壤被围，宝藏王出降，男建固守至城门被启，高句丽亡。兄弟阋墙为唐军提供了向导与口实，城邑联合体的离散则使抵抗难以持续。",
        content: `
            <p>乾封元年（666年），高句丽权臣泉盖苏文死去。盖苏文自贞观十六年（642年）杀荣留王、立宝藏王以来，以莫离支之名专擅国政二十余年，对外拒唐，对内剪除异己。他的权力建立在军事强人与个人威望之上，未曾建立可操作的继承制度；因此他一死，三个儿子之间的争夺便迅速公开化。盖苏文当政期间，高句丽与唐的关系由朝贡转为对抗，辽东城防与兵力部署也围绕长期战争展开。</p>
            <p>长子泉男生继任莫离支，出巡诸城；弟泉男建、泉男产趁其在外，闭门拒之，不令入主。男生遂走据国内城，收合部众自守，兄弟之间由猜忌转为兵戎。高句丽中央由此分裂为两个中心：平壤一方由男建、男产掌握，国内城一方由男生据守，双方各自以中央自居，互相攻伐。</p>
            <p>中原史书称其姓为泉，是唐人避高祖李渊讳而改渊为泉，故泉盖苏文、泉男生、泉男建、泉男产诸名，皆渊氏之转写。二十世纪出土于洛阳的泉男生墓志与泉献诚墓志，正用泉姓，可与史书互证。这一层避讳痕迹，提醒读者现存记载经过唐人的整理与改写。</p>
            <p>男生自知以一城之力难以抗衡平壤，遂遣子泉献诚入唐求救，并请内附。唐廷接纳，以此为契机把长期的对峙转为进攻。对唐朝而言，高句丽的内讧提供了两样东西：一是熟悉道路、城邑与兵力部署的向导，二是干预其内政的名分。此后唐军的推进，很大程度上依托男生一系的引导与招抚。献诚入唐的具体年份与随行人员，史书所记简略，墓志则提供了若干细节，两者可以参看。</p>
            <p>乾封元年末，唐以李勣为辽东道行军大总管，契苾何力、庞同善、薛仁贵、高侃等分领诸军，自辽东多道并进。唐军的目标不再是直趋平壤，而是先夺取辽东南部与半岛北部的枢纽城邑，逐段切断高句丽各部之间的联系；这一方略与太宗亲征时不同，更像是把灭国拆成若干可完成的步骤。唐军此次动员的规模不及太宗亲征，但诸路配合更为紧密，粮运也多依托已控制的辽东城邑。</p>
            <p>乾封二年（667年），唐军攻拔新城。新城是高句丽西境的重镇，扼辽东南下的通道，学界一般比定为今抚顺一带的山城。泉男建遣兵袭击唐军，薛仁贵率部驰援，破高句丽军于金山，乘胜连下南苏、木底、苍岩三城。这几处城邑的易手，使唐军在辽东与半岛之间打开了一条较为安全的走廊。</p>
            <p>总章元年（668年），薛仁贵攻扶余城。诸将以其兵少而劝阻，仁贵坚持进击，破城之后，扶余川中四十余城望风归附。李勣继进，拔大行城，与诸路会师于平壤城下。至此高句丽可调的野战兵力已所剩无几，守城成为唯一的选择；而守城所需的粮储，又因连年战争与城邑残破而难以支撑。</p>
            <p>平壤被围月余。宝藏王高藏遣泉男产率首领九十八人持白幡出降，男建仍闭门固守，并遣兵出战，屡为唐军所败。城中的粮食与士气同时耗尽，最终由其部将信诚开启城门，唐军得以入城。男建自刺不死，被擒；高藏亦被俘，押送长安。平壤城内有高句丽王与莫离支两个权力中心，投降与固守的主张同时存在，这种分裂加速了城门的开启。</p>
            <p>平壤陷落之后，唐朝在高句丽故地设置安东都护府，下辖九都督府、四十二州、百县，以薛仁贵检校安东都护，领兵镇守；高句丽王室、贵族与大批百姓被迁往中原。泉男生入唐后授官赐爵，其子献诚亦在唐为将，泉氏一门由高句丽的权臣之家转为唐朝的官僚家族。</p>
            <p>若把这场内乱放回高句丽的政治结构，兄弟相争并非单纯的道德败坏。高句丽的权力由王权、莫离支府与各地城邑集团层层构成，中央权威依赖对这些集团的协调；盖苏文以军事强人身份压服各方，却未把这种压服转化为制度。强人一死，继承者只能凭实力与外部支持重新划定秩序，求援于唐便是其中一种选择。</p>
            <p>唐朝的胜利同样不能只归因于内应。唐军在辽东经营多年，熟悉道路与季节，后勤依托营州与海运，攻城器械与水军配合也较隋代成熟；李勣的稳健推进与薛仁贵的机动突击相辅相成。内乱提供机会，能否把握机会则取决于此前的积累。</p>
            <p>高句丽的灭亡因此是内外两种力量叠加的结果：兄弟阋墙使中央失去调度全境的能力，城邑集团在观望中选择降附；唐军则沿着被打开的走廊逐城推进，把军事压力转化为政治收编。平壤的陷落只是最后一步，真正的瓦解在此之前已经发生。高句丽灭亡后，部分遗民北迁，参与渤海国的建立；泉氏家族则在中原继续其仕宦生涯，两条去向都说明亡国之后的人口流动比政权更替更为持久。</p>
            <p>从史料角度看，这场内乱与其后的灭国战，主要见于《旧唐书》《新唐书》的《高丽传》与《资治通鉴》的乾封、总章部分；《三国史记》提供了半岛一侧的编年与人事，泉氏父子的墓志则补正了家族世系与仕唐经历。几种材料的立场不同，对男生求援一事的评价也相去甚远。</p>
            <p>后世对泉氏兄弟的评说，多聚焦于引唐军入境一节。若只以忠奸论之，便容易忽略高句丽权力结构的固有缺陷：莫离支之位本无明确的传承规则，兄弟各自拥兵，中央又没有足以裁决的机构。理解这一点，才能解释为何一个立国七百余年的政权，会在一次继承危机之后迅速崩解。从长时段看，泉氏兄弟之乱是七世纪东北亚秩序重组的最后一环：内部权力交接失败，外部强权顺势而入，二者共同结束了这个政权。</p>
        `
    },
    {
        id: "goguryeo-mountain-fortresses",
        title: "高句丽的山城：城邑防御与战争形态",
        date: "2026-11-18",
        tags: ["唐与高句丽", "军事地理", "城防"],
        summary: "高句丽的政治与军事组织以城为单位，王城与山城构成平原城居住、山城避战储粮的组合。丸都山城、国内城与平壤一带的城址显示石筑与土筑并存、马面与瓮城等设施渐备。这种城邑网络迫使隋唐以长期围城和逐城争夺取代一战决胜，城破后的降服与迁民又重塑了辽东的人口与秩序，也使战争形态长期停留于攻城与守城。",
        content: `
            <p>高句丽的国家组织，与其说建立在郡县之上，不如说建立在城邑之上。城既是聚落，也是行政、军事与仓储的单位；大城统摄周边小城，城主之下有村落与山谷，战时则按城征发丁壮、征集粮秣。中原史书以都督、刺史比附其城邑长官，是为了把陌生的制度纳入熟悉的框架，实际情形要松散得多。这种以城为节点的结构，使高句丽的战争很少以野战决战开场，而多以攻城、守城与粮道争夺展开。</p>
            <p>这种结构最直观地体现在王城的组合上。高句丽迁都国内城（今吉林集安）后，在城北的山上筑尉那岩城，即后世所称的丸都山城；五世纪迁都平壤，大城山城与安鹤宫所在的平原宫城，同样构成一山一平的两重城址。平原城用于居住、行政与手工业，山城则在山脊上围出避难所与粮仓，二者相距不远，构成一套可以随时切换的防御体系。</p>
            <p>丸都山城的形制常被用来说明这种组合。城垣沿山脊起伏，以石垒砌，谷口处设门，城内有宫殿址、蓄水池与瞭望设施；据考古调查，城址中还见排水涵洞与瓮城一类结构。国内城位于平原，城垣外砌石、内包夯土，规模与山城相配。两城一住一守，平时政令出自平原，战事一起则退保山上。</p>
            <p>筑城技术上有石筑与土筑两条脉络。石筑者多取楔形石，城墙断面呈梯形，内外壁向上收分，缝隙填以碎石，坚固而耐久；土筑者则夯土成垣，多见于平原城与部分河谷城址。据考古调查，城墙及城门附近的马面、女墙、角楼、瓮城与水门等设施，在各城址中的配置并不一致，年代也有早有晚，未可一概而论。</p>
            <p>选址多依地形。山城常建于临河的断崖或三面环山的山脊，控制渡口、谷道与水源；城与城之间以烽燧、道路和河谷相连，形成纵深。进攻一方即便攻破一城，也难以绕过侧后的城邑直趋腹地，因为粮道与退路都暴露在这些城的手里。防御的韧性，正来自这种互相牵制的网络。</p>
            <p>城邑由地方贵族把持。城主往往出自世居此地的豪族，中央以爵位、联姻与军事征调换取他们的效忠；史书所见耨萨、褥萨一类称号，常被用来指称部或大城的长官，但其等级、职掌与彼此的统属关系，各家整理并不一致，中原史书的比附也带有整齐化的成分。中央与地方之间因此不是单纯的命令关系，而更接近于一种持续的协商；城主在战时的选择，既是军事决定，也是政治表态。</p>
            <p>这种联合体的强处与弱处是一体两面。中央权威稳固时，城邑网络能迅速动员，把入侵者拖入逐城争夺；中央权威动摇时，各城便自行计算利害，或闭城观望，或遣使请降。高句丽末年的情形尤为明显：唐军尚未抵达，部分城邑已先后来归，降附的连锁反应比城破本身更具决定性。</p>
            <p>隋唐两朝在辽东城下的经历，说明山城如何消耗进攻方的优势。隋军以空前规模渡辽，却在辽东城下顿兵数月，云梯、撞车与地道轮番使用，守军以火攻、滚木与诈降应对；唐太宗围安市城两月不下，筑土山强攻，土山崩塌压坏城墙，仍未能破城。兵力优势在山地与坚城之间被逐日消磨。</p>
            <p>围城还受补给与季节的双重约束。攻方数万乃至十数万人屯于城下，粮秣须从辽西、河北转运，道路一经雨雪便难以通行；辽东春季泥泞、秋季早寒，可用的作战窗口很短。守方却可以依托山城的仓储与山地退路，把时间拖到攻方粮尽。战争的节奏因此不由攻方单独决定。</p>
            <p>山城的选址还要顾及水源与仓储。城址多临近溪流，或凿池蓄水，城内发现的大型蓄水池，说明守军准备的是数月乃至更久的固守；粮仓多置于城内高处，以防火灾与水淹。攻方若不能切断水源、焚毁积储，围城便只能以年月计。</p>
            <p>城破之后的处置，同样遵循城邑的逻辑。唐军每下一城，多收其府库、毁其城防、徙其民户，以城为州，授降附城主以官职而内徙；撤军时又将所得城邑弃守。迁民削弱了地方抵抗的基础，也使故地一时空虚。灭国之后，安东都护府仍须依托旧城设治，却难以把城邑网络整体转化为唐朝的州县。</p>
            <p>唐高宗时期的灭国战，把这种逐城争夺推到极致。唐军先取辽东与半岛北部的枢纽城邑，切断高句丽各部的联系，再南下合围平壤；薛仁贵拔扶余城后，扶余川一带的城邑相继归附。城邑一旦成批倒向唐军，防线便不再是连续的线，而是一段段被抽空的点。</p>
            <p>这也解释了为何隋唐都不能一战定胜负。高句丽没有一座可以被一击而定的单一都城：王城几度迁移，平壤陷落之前，辽东的城邑群仍在抵抗；战争的真正目标是控制城邑网络，而不是歼灭一支野战军。唐太宗受挫于安市，唐高宗则先取百济、再自南北夹击，以多点登陆和长期围困拆解这个网络，前后经营二十余年才见分晓。</p>
            <p>把山城仅仅看作军事工事，会低估它的意义。它是高句丽国家结构的物化：城邑既是贵族的根基，也是王权的凭借，还是战争中最基本的筹码。隋唐征辽之所以旷日持久，固然有气候、粮运与指挥的原因，但更根本的是，它们面对的并不是一个可以一举击碎的中心，而是一张由城邑结成的网。考古调查能揭示城垣、马面与蓄水池的形制，却难以还原守军的编制与补给；文献记载又多出自攻方，守城者的决策往往只能从结果反推。山城研究因此常在两套材料之间来回校正，结论带有相当的推测成分。</p>
        `
    },
    {
        id: "tang-liaodong-logistics",
        title: "唐军征辽的后勤：海运、转输与羁縻兵",
        date: "2026-11-17",
        tags: ["唐与高句丽", "后勤", "军事制度"],
        summary: "唐军征辽受制于距离与季节：辽左早寒，草枯水冻，陆路须经营州、辽西转输，海路自东莱一带渡海，运量受风涛与滩险限制。军粮、资储、器械与马匹的转运成本，加上契丹、奚、靺鞨、突厥降部等羁縻兵的征调与可靠性问题，共同限制了战争规模与持续时间。太宗贞观十九年因粮尽班师，正是这一约束的明证。",
        content: `
            <p>唐军征辽的第一个约束是距离。自幽州出塞，经营州（今辽宁朝阳）东行，渡辽水而后进入辽东，单程已在千里以上；若从河南、山东调集粮秣，转运的路程还要更长。古代陆运的效率极低，民夫与牲畜在途中自身就要消耗掉相当一部分粮食，运抵前线的数量因此远小于起运之数。</p>
            <p>第二个约束是季节。辽东的春季泥泞，辽泽一带尤甚，车马难行；夏季雨水集中，道路时常中断；秋季短暂，霜降之后便草枯水冻。中原军队习惯的作战季节在这里被压缩成几个月，错过窗口，粮道与士气同时吃紧。隋唐两朝的辽东之役，几乎都在与这条时间线赛跑。</p>
            <p>陆路转输以营州为枢纽。粮秣自河北、河南、山东征调，经幽州集中于营州，再沿辽西走廊东运；这条走廊一侧是山，一侧是海，通道狭窄，一旦雨雪便拥堵不堪。唐廷在战前修治道路、囤积粮械，并征发民夫与车辆，运输的组织本身就成为一场动员。粮车、驮马与民夫混杂于道，速度与损耗都难以精确控制。</p>
            <p>转输的重负最终落在河北、山东的民户身上。粮秣的征购、车辆的调发、民夫的口粮与脚钱，层层摊派；战事延长，农时便被耽误。唐廷虽以和籴、租庸调与赏赐调节，仍难以完全避免沿途的逃亡与损耗。后勤的压力，往往先在社会层面显现，然后才传到前线。</p>
            <p>海运提供了另一条路径。贞观十九年，张亮率舟师自东莱渡海，攻取辽东半岛南端的卑沙城，与陆路主力遥相呼应；隋代来护儿也曾自东莱入海，直趋平壤附近；高宗灭百济之役，苏定方自成山渡海，海路更成为主攻方向。海船可以绕开辽西走廊的瓶颈，运量也大于车运，但受风信、滩险与港口条件的限制，登陆之后仍须陆运。</p>
            <p>海路也并非坦途。黄海与渤海的季风、沿岸的礁滩与浅沙，使船队只能择季而行；港口容量有限，卸载之后仍需人畜转运。海船一旦失期，前线便可能出现数日的断粮。唐军在辽东的行动多把海运当作陆路的补充，只有在半岛西岸的战事中，海路才偶尔成为主攻。</p>
            <p>军粮之外，资储与器械的消耗同样可观。数万人的军队日食有定，军粮以粟、米为主，辅以干粮与盐，战马另需草料；攻城所需的抛车、撞车、云梯，以及堆筑土山，要耗费大量木材、铁料与人工，成品笨重，拆运与组装都需时间。唐军有时就地取粮于敌境，但高句丽城邑多坚壁清野，破城之后府库有限，难以长期供养大军。</p>
            <p>羁縻兵是唐军编制中不可忽视的一部分。契丹、奚、靺鞨与突厥降部，或以骑兵从征，或以向导、译语与地方知识见长；唐廷以都督、刺史一类名号，赐物与质子加以约束，蕃将名义上置于唐军将领之下，实际仍分领其众。唐廷对蕃部的控制，多靠册封与赏赐，而非直接的行政管辖，蕃将因此保有较大的自主空间。这种征调扩大了兵源，也把边疆的向背直接带进了战场。</p>
            <p>可靠性始终是问题。蕃兵多为部落征发，纪律与补给自成一系，战事顺利时可用，一旦受挫便容易观望、溃散甚至倒戈；他们与高句丽、靺鞨各部之间又有复杂的利害与恩怨，阵前倒向哪一方，往往取决于首领的利害判断。唐廷因此既要借重蕃骑，又不得不以汉军监临、以赏罚维系，这种张力贯穿整个征辽过程。</p>
            <p>马匹与攻城器械的运输，是后勤中最容易被忽略的难题。战马多自陇右牧监与奚、契丹市易而来，长途驱赶会掉膘，入冬后又易冻毙；挽马与驮畜的损耗，直接决定粮车能走多远。攻城器械则依赖木材与工匠，往往在营地附近采木制造，一旦转移，便只能弃置或拆散重装。这些损耗不会出现在战报里，却会在撤军时集中显现。</p>
            <p>后勤的极限，最终转化为战争规模的极限。兵力越多，粮道越长，战役窗口越短；围城越久，消耗越大，国内征发的民夫也越多。唐太宗贞观十九年之役，攻下辽东十余城后顿于安市，秋深粮尽，只好班师；《资治通鉴》记其理由，谓辽左早寒、草枯水冻，士马难久留，且粮食将尽。今人常把这次撤军概括为粮运不继，其实天时、粮道与士气是同一件事的三个侧面。</p>
            <p>与隋代相比，唐人的调整在于规模与路线。隋炀帝三次征辽，首次即号称百万，民夫转运于道，东莱造船的工匠昼夜浸在水中，后勤先于军队崩溃；唐军则把兵力压到更可控的规模，先经营州与海运两线并进，再以灭百济、南北夹击的方式缩短决战的距离。这不是单纯的战术改良，而是对后勤约束的承认。隋唐之间的这种差别，也解释了为何同样面对坚城，唐军能把战争拖成可承受的多年经营，而隋军在第三次东征之后便再无动员之力。</p>
            <p>高宗朝的灭国战，正是这种承认的结果。唐军先取百济，取得半岛南部的登陆点与前进基地，再自南北两路夹击高句丽；营州与海路的运量经过多年经营，比太宗时更为顺畅，进军时机也选在秋收之后、封冻之前。后勤由此不再只是战役的附随问题，而成为战略设计本身的组成部分。</p>
            <p>因此，理解唐军征辽的胜负，不能只看城下之战的攻守。粮道能延伸多远，海运能在什么季节靠岸，羁縻兵在关键时刻是否可用，马匹与器械能否随军移动，这些看似琐碎的条件，决定了战争能打多大、能打多久。唐与隋的差别，很大程度上就写在这些条件里。</p>
        `
    }
,
    {
        id: "sources-on-tang-goguryeo-war",
        title: "唐丽战争的史料谱系：两《唐书》《通鉴》与《三国史记》",
        date: "2026-11-21",
        tags: ["唐与高句丽", "史料", "史学史"],
        summary: "唐丽战争的传世记载多成于战后，分属中国正史与朝鲜半岛史书两个传统。本文清理两《唐书·东夷传》、《资治通鉴》唐纪与《考异》、《唐会要》《册府元龟》《通典》以及《三国史记》《三国遗事》的史源与编纂意图，并以好太王碑、平百济碑、泉氏墓志等石刻相参，讨论兵力、路线与日期记载分歧的成因，并提出多源对勘、区分叙事与制度的原则。",
        content: `
            <p>讨论唐丽战争，首先遇到的不是史实空缺，而是史料的层累。传世记载几乎全部成于战争结束之后，分属中国正史与朝鲜半岛史书两个书写传统，中间还夹着碑刻、墓志这类第一手材料。若不先清理这一谱系，很容易把不同来源、不同目的的叙述当成同一层面的「事实」。</p>
            <p>中国正史系统以两《唐书》的《东夷传》为核心。《旧唐书》成于后晋，材料经安史之乱与唐末丧乱散佚后重新访求，高丽条保存了不少唐历朝实录与国史的原始痕迹，叙事朴拙而细节丰富。《新唐书》成于北宋，宋祁、欧阳修主持，号称事增于前、文省于旧，本纪与《东夷传》可以互补；但宋人好用春秋笔法，改字、删削与道德判断夹杂其中，读时必须把书法与事实分开。同一条记载，旧书近于档案，新书近于史论，这是两书最基本的差别。</p>
            <p>《资治通鉴》唐纪是另一套系统。司马光以唐实录为骨干，兼采杂史、传记、诏敕，编年排比，使战争进程第一次获得连贯的时间轴。《通鉴考异》逐条说明取舍，哪些取实录、哪些取杂史、哪些两存，等于留下了一份十一世纪的史料批判记录。今天要知道某条记载的来源与可信度，先看《考异》往往比看正文更有用。但司马光的编纂意图是资治，太宗征辽在书中被裁剪成几个决策节点：亲征之议、辽东攻城、安市顿兵、班师悔过。这样的剪裁突出了纳谏与拒谏的对比，却压缩了后勤、气候、地形这些更接近实况的因素。书中「臣光曰」对贞观后期用兵的批评，本身是北宋士大夫对开边政策的反思，不能直接当作唐人的评价。</p>
            <p>制度与类书系统常被忽略。《唐会要》保存诏敕、仪注、羁縻州设置与使节往还的片段；《册府元龟》按事类排比，往往保留了正史删去的奏疏与答诏；《通典》的边防、兵制诸门，则提供了观察唐军编制与军费的口径。这三类材料不适合直接叙述战役，却是讨论制度如何运作的唯一凭据。以安东都护府的置废为例，正史只有寥寥数语，会要与诏敕才能看出羁縻州县的数目、隶属与迁转。</p>
            <p>朝鲜半岛方面，金富轼《三国史记》成书于 1145 年，是高丽仁宗朝官修的正史。它的史源包括中国正史、本国旧记与《高丽古记》一类私记，高句丽部分被编入本纪，体例上模仿《史记》《汉书》。问题也在这里：年代错置时有发生，某些事件被系于明显不可能的年份；兵数往往夸大；对高句丽、百济、新罗三方的褒贬随编纂者的立场摆动。更关键的是，它记七世纪史事时大量转引中国史书，若把它当作独立旁证与两《唐书》对勘，容易陷入循环论证。比较可行的做法，是先辨明某条记载是否见于中国正史，再判断它的独立价值。一然《三国遗事》成书更晚，重佛教传说与地方记忆，价值在宗教、民俗与地名沿革，不在战争过程。</p>
            <p>年代错置的典型，是把广开土王的几次征伐系于其即位之初，又把长寿王迁都平壤的时间提前或推后；高句丽本纪中的在位年数，与他书对照常有数年的出入。这类误差不影响对事件性质的判断，却足以让以年为单位的战役复原失准。</p>
            <p>碑刻与墓志提供了另一条线索。好太王碑立于 414 年，是长寿王为其父广开土王所立，记四世纪末至五世纪初高句丽的征伐，包括对百济、倭与契丹的战事。它完全不涉及七世纪的唐丽战争，其价值在于校正《三国史记》对广开土王年代的编排，并显示高句丽自身的纪功传统。《大唐平百济国碑铭》立于 660 年，苏定方纪功，现存扶余定林寺址，是唐军自身的当场记录，可与《旧唐书·苏定方传》对读。泉男生、泉献诚墓志一九二〇年代出土于洛阳，记泉氏归唐后的仕历与参与平高句丽的过程，能补正史所略的授官、食邑与葬地。冉牟墓志属五世纪高句丽自身的文字材料，墨书长文，对研究其官制与贵族家族有独特价值。</p>
            <p>考古材料也有边界。城址、山城、墓葬的形制可以指示文化归属与防御体系，却不能直接证明某次战役的发生地点；陶器、瓦当的编年精度通常以半个世纪计，用来坐实某一年的事件是危险的。</p>
            <p>各书的差异集中在三处。其一兵力：唐军东征的规模，《通鉴》与两《唐书》所记不一，号称三十万而实际战兵十万上下，是通行说法；高句丽援安市之众，或说十五万，数字带有明显的夸饰成分。其二行军路线：李勣、李道宗、张亮诸部的道里与先后，新旧《唐书》互有出入，需以《通鉴》的编年与《括地志》一类地理书参校。其三日期：安市之役持续的时间，各书记载从数十日到数月不等，背后是对顿兵原因的不同解释，或归咎于天气，或归咎于攻城器械，或归咎于决策迟疑。</p>
            <p>日本方面的《日本书纪》记白江之战与遣唐使，保留了不少唐军动向的侧证，但经过八世纪的编纂加工，人名、官名多有改饰，使用时须与《旧唐书》对读。</p>
            <p>使用这些材料，大致可以立几条原则。多源对勘，以碑刻校史传，以制度材料校叙事材料，以考古材料校地名。区分叙事与制度：纪传中的褒贬语汇、类书中的奏疏、会要中的诏敕，属于不同层次，不能混为一谈。注意史源方向：晚出的书转引早出的书，只能证明早出书的流传，不能增加事实的权重。最后，对数字保持警惕，纪功碑与正史的战果统计都有宣传功能。</p>
            <p>因此，唐丽战争的史实不是某一部书给定的，而是在层累的记载中被反复重建的。史料谱系本身即是研究对象：它告诉我们，七世纪的战争如何被五代北宋的正史、十一世纪的编年与类书、十二世纪的高丽史官分别记忆和利用。</p>
        `,
    },
    {
        id: "goguryeo-remnants-bohai",
        title: "战后高句丽遗民与渤海国的成立",
        date: "2026-11-22",
        tags: ["唐与高句丽", "遗民", "渤海"],
        summary: "668 年高句丽灭亡后，唐廷将王室、贵族与大批民户迁往中原、营州与河南等地，遗民反抗与安东都护府的内迁随之而来。696 年营州之乱给了粟末靺鞨东奔的机会，大祚荣于 698 年建震国，后受唐册封为渤海。以下梳理迁徙、叛乱、羁縻与质子关系，并检讨渤海族属之争及小高句丽、投突厥与投新罗诸支流。",
        content: `
            <p>668 年平壤陷落，高藏被俘，唐朝在辽东设置安东都护府。但亡国并不等于人口的消失。高句丽故地约有七十万户，通行说法如此，分布在山谷、平原与滨海诸城，如何安置这些人，是唐廷此后三十年最棘手的问题之一。</p>
            <p>人口迁徙是第一步。唐廷把高句丽王室、贵族与大量民户迁往中原，一部分安置在营州，一部分徙于河南、陇右诸州；《通鉴》记总章二年徙高丽民三万八千二百户于江淮之南及山南、京西诸州空旷之地，数字未必精确，方向却是清楚的：把可能聚集的旧势力打散，填入唐帝国的人口稀疏区。营州因此成为高句丽遗民、靺鞨与契丹杂居之地，这种杂居既是控制手段，也为三十年后的变乱埋下伏笔。</p>
            <p>贵族的情况不同。泉男生、泉男产等泉氏成员入唐后授官、赐第，子弟入宿卫，墓志记其葬于洛阳北邙，子孙继续在唐为官。这类家族被编入唐的官僚体系，其遗民身份在第二代即淡化，与普通民户的处境相差甚远。</p>
            <p>迁徙的动机不止于安全。高句丽故地经过多年战争，城邑残破，仓储空虚，唐军就地驻守的粮食难以自给；把民户迁入中原，既减轻辽东的供给压力，也为关中与河南补充劳动力。但迁徙本身耗费巨大，沿途的给粮、车牛与吏卒护送，在诏敕中屡有反映。</p>
            <p>遗民的反抗几乎与迁徙同时发生。669 年前后，剑牟岑拥立高藏的外孙安舜，在辽东起事，一度攻陷州县；唐廷遣高侃等讨平，安舜奔新罗，新罗将其安置于南境。起事的规模与持续时间，各书记载不一，但它说明高句丽故地的秩序远未稳定。唐廷随后把高藏流放，又数次调整安东都护府的治所，从平壤内迁辽东故城，再迁新城，控制线一路向北收缩。</p>
            <p>营州之乱是转折。万岁通天元年（696），契丹李尽忠、孙万荣因营州都督赵文翙的侵侮而起兵，攻陷营州，杀赵文翙。唐廷征发大军讨伐，同时征调粟末靺鞨。乞四比羽与乞乞仲象率部东走，唐将李楷固追击，乞四比羽被杀，乞乞仲象死，其子大祚荣收合余众，在天门岭设伏击败追兵。这支队伍渡辽水，据东牟山，于 698 年建立政权，初称震国，或说仍用靺鞨旧号。</p>
            <p>天门岭的地望，或说在今吉林敦化一带，或说在辽宁东部，学界仍有讨论；大祚荣据东牟山建城，一般认为在今吉林敦化敖东城，考古发现与文献可以大致对应，但精确年代仍有争议。</p>
            <p>唐与渤海的关系从一开始就是模糊的。713 年唐遣使册封大祚荣为渤海郡王、忽汗州都督，此后渤海对唐朝贡、遣质子入侍、接受唐历，名义上是羁縻州；但它自有年号、自置百官、自建都城，对唐行藩礼而对内称制。学界常用「外臣内帝」形容这种状态，未必准确，却道出了羁縻体制的弹性。质子与朝贡既是政治臣属的仪式，也是贸易与情报的通道。</p>
            <p>震国之名的来源，或说因地处东方震位而得；渤海本是唐廷所封郡王之号，后来成为国号。名号的变化本身提示我们，渤海的合法性有一部分来自唐的册封，另一部分来自它对靺鞨诸部的统合。</p>
            <p>高句丽遗民在渤海建国中的角色，是争论的焦点。中国学界多主张渤海以粟末靺鞨为主体，吸收高句丽遗民与其它族群；朝鲜半岛学界则强调高句丽遗民的主导作用，把渤海视为高句丽的继承国，并与统一新罗构成「南北国时代」。考古材料两面都能援引：六顶山古墓群的贞惠公主、贞孝公主墓，形制与壁画近唐；龙头山与上京城的布局兼有唐式城制与高句丽山城的因素。但墓葬形制指示的是文化接触，不能直接判定族属，族属还要靠墓志、姓氏与文献互证。</p>
            <p>南北国时代的说法，出自二十世纪朝鲜半岛的史学建构，把统一新罗与渤海并列为高句丽之后的两个政治体。这一框架便于叙述民族史，却预设了渤海的高句丽属性，使用时应当作为史学史的对象，而不是论证的前提。</p>
            <p>渤海与日本通使频繁，其国书自称高丽国王，或径称高句丽，这种自称常被当作继承关系的证据；但国书用语是外交修辞，随对象调整，不宜直接视为族属自认。</p>
            <p>还有几条支流。699 年唐以高藏之子高德武为安东都督，领高句丽余众，后世称「小高句丽」，其地望与存续时间学界仍有讨论，一般认为后来并入渤海。另有部分遗民北投突厥，受默啜可汗安置；一部分南投新罗，被编入新罗的地方编制。这些支流说明遗民并非单一去向，而是随战局与地缘形势分散。</p>
            <p>安东都护府的内迁与唐朝在辽东的控制收缩，是同一过程的两面。都护府从平壤退到辽东，再退到新城，属州数目减少，实际管辖限于点线；武则天时期国力内顾，营州失守后辽西走廊一度中断，直到玄宗朝才逐步恢复。开元年间唐在营州设平卢节度使，辽西的防线重新建立，但已无力深入辽东腹地。渤海国的成立，正是在这个权力真空中完成的。</p>
            <p>因此，把渤海简单说成高句丽的继承国，或简单说成靺鞨人的国家，都是近代民族叙事对古代政治体的投影。更稳妥的说法是：渤海是七世纪末东北族群重组与唐帝国辽东秩序收缩的产物，高句丽遗民在其中扮演了重要但难以量化的角色。遗民史的研究，难点不在材料少，而在材料都被后来的归属之争预先安排了位置。</p>
        `,
    },
    {
        id: "tang-fan-generals-goguryeo",
        title: "蕃将与降众：唐军中的非汉兵力",
        date: "2026-11-23",
        tags: ["唐与高句丽", "蕃将", "军事制度"],
        summary: "唐军征辽的兵力中，突厥、契丹、奚、靺鞨、高句丽与百济的部落兵占了相当比重。这里从羁縻体制、质子宿卫与入朝制度入手，讨论蕃将的双重身份、蕃兵在骑兵、向导与译语方面的作用及其可靠性，并以泉男生、高侃、黑齿常之为例，分析降众安置的三条路径与蕃将忠诚的结构性两难，兼及安史之乱后的格局变化。",
        content: `
            <p>唐军的构成从来不是单一的。从太宗到玄宗，历次征辽的军队中都有突厥、契丹、奚、靺鞨、高句丽与百济的部落兵，统兵者则往往兼有唐官与部落首领两重身份。理解蕃将，关键不在族属，而在制度：他们是被编入帝国军事体系的间接统治者。</p>
            <p>唐初的羁縻体制提供了框架。都护府、都督府之下设羁縻州，以部落首领为都督、刺史，世袭其职，赐姓、授将军号、给俸禄，同时要求朝贡、质子、从征。蕃将因此不是雇佣兵，而是帝国与草原、山地社会之间的中介：他替唐廷动员本部的骑兵，也替本部向唐廷争取赏赐、互市与自治空间。</p>
            <p>赏赐是维持关系的主要手段。绢帛、金银、马匹、宅第、食邑，以及节度使、将军一类官号，构成蕃将的收入与声望来源。唐廷的赏赐有很强的仪式性，一次大规模的颁赐既是酬功，也是向诸部展示帝国的富庶。赏赐一旦短缺或分配不公，部落的离心便随之而来。</p>
            <p>太宗对蕃将的态度常被概括为胡越一家，实际做法却是用其力而防其变。他大量任用蕃将，同时把他们的子弟留在长安，把部落分置在不同区域，并让汉将与之共同统军，形成互相牵制的格局。这种安排的有效性，取决于中央能否持续提供赏赐与威慑。</p>
            <p>质子、宿卫与入朝，是这套体制的关节。部落子弟入长安宿卫，名义上是侍卫，实际上是质子、学生与官员预备队。阿史那社尔、契苾何力、执失思力等人都在宿卫中成长，熟悉唐的宫廷与军制，回国或统兵后成为唐廷最可靠的边将。质子制度的代价是，一旦本部叛乱，这些人的处境立即变得尴尬。</p>
            <p>需要区分蕃将与蕃兵。蕃将是制度中的个人，有官阶、有封爵、有墓志；蕃兵是部落的成员，随首领出征，战后各归本部。史书多记蕃将而少记蕃兵，导致我们高估了个人的作用，低估了部落动员的规模。</p>
            <p>蕃兵与唐军的编制并不重合。府兵、募兵按籍征发，蕃兵则按部落征发，战后各归本部，不入折冲府的簿籍。于是同一支远征军中并存两种动员逻辑：一种以户口为单位，一种以部落为单位。这种并行在战时可以互补，在战后却留下统计与安置的难题，朝廷既不知道蕃兵的确实数目，也难以把他们纳入均田与租庸调的体系。</p>
            <p>蕃兵在征辽中的作用相当具体。骑兵冲击与迂回，是唐军对付高句丽山城体系的重要手段；高句丽降人熟悉山川道路与城邑虚实，常被用作向导与译语；百济降众则在白江口之役中提供了船只与水手。可靠性却是变量：契苾何力在安市之役力战重伤，是忠勇的典型；也有部众临阵观望、掳掠而不受节制的情形。蕃兵的补给多依赖唐廷，军纪则依部落习惯，二者常相冲突。</p>
            <p>译语与向导的作用常被低估。高句丽的山城多据险而建，城与城之间的道路、水源、隐蔽小径，非本地人不能知；唐军几次顿兵，都与道路判断失误有关。降人提供的情报，其价值有时超过一个军的兵力。</p>
            <p>降众的安置有三条路径。其一是羁縻州，就地设置，以首领为刺史；其二是内徙，把部落迁到营州、幽州一带，置于唐的直接控制下；其三是编入军府，散其部落，以个人身份入折冲府。三条路径的效果不同：羁縻保留社会结构，内徙便于监视而增加财政负担，编入军府则加速融合，也削弱部落凝聚力。</p>
            <p>降众编入军府的情形，可以安东都护府下的羁縻州与河南、河北的折冲府为例。前者保留部落组织，后者打散原有结构。同一批降人，往往一部分就地安置，一部分内徙，一部分散入军府，分而治之的意图十分明显。</p>
            <p>个案最能说明问题。泉男生是高句丽莫离支泉盖苏文之子，因内讧于 667 年归唐，授辽东大都督、玄菟郡公，反过来参与攻灭本国，其后又平定泉男建的抵抗；两《唐书》本传与洛阳出土的墓志可以互校，墓志对授官的细节更完整。高侃是高句丽人，入唐后为将，征突厥、平高句丽，官至安东都护，是以夷制夷的样本。黑齿常之是百济人，归唐后屡破吐蕃，最后死于酷吏的诬陷，其命运显示蕃将的军功并不能保证政治安全。</p>
            <p>蕃将的忠诚与边疆治理之间存在结构性两难。唐廷需要蕃将的兵力与地方知识，又惧怕他们坐大，于是用质子、赐姓、联姻、调离本部、分置部落等办法维持平衡。这些办法在帝国强盛时有效，一旦中央权威动摇，蕃将便成为最先脱轨的力量。营州之乱中契丹与靺鞨的倒向，就是这种脆弱性的明证。</p>
            <p>安史之乱后，格局变了。河朔三镇的节度使多有蕃将背景，如李怀仙、李宝臣一类，其军队以部落兵与本地牙兵为核心，形成半独立的地方势力；神策军与禁军中则吸纳了大量蕃兵，成为中央直接掌握的武力。蕃将不再只是边疆的中介，而成为帝国政治内部的力量。</p>
            <p>所谓地方化，指蕃将的后裔逐渐脱离本部，以军功与婚姻嵌入地方社会，最终以节度使的身份割据一方。这个过程在八世纪后半期完成，与唐廷失去对部落的直接控制同步。</p>
            <p>回到唐丽战争，蕃将与降众的意义不止于战场。他们让唐军得以在陌生的山地与河谷作战，也让唐朝的辽东统治始终依赖当地合作者。安东都护府的收缩、遗民的离散、渤海的兴起，都可以从这一角度重新理解。</p>
        `,
    },
    {
        id: "goguryeo-diplomacy-northern-dynasties",
        title: "高句丽的南北外交：从北魏到陈隋",
        date: "2026-11-24",
        tags: ["唐与高句丽", "外交", "南北朝"],
        summary: "五世纪起，高句丽同时向北魏与南朝遣使受封，以两套正统互相制衡。辽东归属、百济求援与好太王碑所记的南征，构成这套外交的现实背景；使节或经幽州陆路，或自东莱渡海。北齐、北周与陈并立时封号层层加码，突厥兴起后东北亚又多一角。隋统一后朝贡收紧，598年的冲突宣告两面外交走到尽头。",
        content: `
            <p>五世纪的高句丽处在双重的承认结构之中。北魏据有中原北方，自居正统；刘宋及齐、梁偏安江左，也以中国自命。两个朝廷互不承认，却都愿意把高句丽纳入自己的册封序列。高句丽的办法是同时遣使，向北魏受辽东郡公、高句丽王，向南朝受征东大将军、高句丽王。史家称之为两面外交，语气带贬义；放回当时，这更像小国的生存常规。</p>
            <p>长寿王在五世纪二十年代迁都平壤，是对外战略的一次重置。旧都国内城偏处鸭绿江中游，离半岛南部的争夺前线太远。迁都后王庭直面百济与新罗，南进意图变得明显；北面的辽东仍须守住，那里既是与中原的缓冲，也是铁矿、马匹与人口的来源。</p>
            <p>好太王碑立于五世纪初，记广开土王的功业，是讨论高句丽南进的第一手材料。碑称其南征百济，取城数十、村数百；又记倭人侵入新罗，高句丽遣步骑五万往救，大破倭军。数字与地名带有夸耀成分，具体年代与里程学界仍有讨论，但南征百济、救援新罗两事的基本轮廓，可与《三国史记》互证。碑是高句丽自立的纪念碑，说明它如何叙述胜利，而非战争的实际规模。</p>
            <p>北魏在五世纪三十年代灭北燕，势力进入辽西，与高句丽直接接壤。此前两者之间还隔着北燕；缓冲消失后，辽西的营州与辽东的襄平一线便成为对峙的前沿。北燕末主冯弘曾逃入高句丽，北魏索之甚急，高句丽先是不遣，后来杀之于北丰。收留亡国之君可得人力与名分，却要承担与强邻交恶的风险，高句丽最终选择了后者。</p>
            <p>北魏对高句丽的册封，通常包括都督辽海诸军事、征东将军、领护东夷中郎将、辽东郡开国公、高句丽王等衔。高句丽王是对政权的承认；领护东夷中郎将把它放进中原管理东夷的序列，名义上代表朝廷抚纳半岛诸国；辽东郡公最敏感，因为辽东正是高句丽实际占据、北魏也从未放弃主张的地方。授予郡公，等于在名义上把辽东保留在中原版图之内，同时承认高句丽对该地的经营。</p>
            <p>南朝的封号走另一条路。刘宋封高句丽王为征东大将军，齐、梁又加以骠骑、车骑一类名号，品秩越给越高，约束却越来越松。南朝距辽东悬远，无力干预半岛事务，它需要的是能在北方牵制北魏的远处盟友；高句丽需要的则是典籍、工匠、贸易渠道，以及可与北魏册封相平衡的名分。双方各取所需，使节往来的次数因此可观。</p>
            <p>百济是这套关系中的第三个变量。五世纪七十年代，高句丽攻破百济的汉城，百济王室被迫南迁，此后长期与高句丽为敌。百济曾遣使北魏，请共伐高句丽，北魏以道路阻远未许，却仍授予百济王号，用意是在南北两翼同时下注，以免高句丽独大。百济则一面结好南朝，一面联合倭国，试图从海上牵制高句丽。</p>
            <p>六世纪中期以后，大陆的分裂变成三块：北齐据关东，北周据关中，陈据江南。高句丽对三者同时遣使，封号层层加码。北齐沿袭北魏旧制，授辽东郡公、高句丽王；北周进爵为辽东王；陈则授以镇东将军一类衔。三个朝廷都无力东顾，封号便成了一种成本极低的承认。名号的通货膨胀，恰好说明册封的实质：它是互相利用的仪式，而非真实的统属。</p>
            <p>突厥在六世纪中期兴起，灭柔然而据漠北，东北亚由此多出一个变量。北齐与北周争相结好突厥，以重金与婚姻换取其不南下；高句丽与突厥之间也有使节往还，双方在牵制中原王朝这一点上存在共同的利害。突厥则在各方之间摇摆，以取财物与战略余地。东北亚由此成为中原两朝、草原汗国与半岛诸国互动的多角结构。</p>
            <p>隋在六世纪末统一南北，朝贡体系随之重整。高句丽遣使入朝，隋授其王为大将军、辽东郡公，名分与北朝旧制相去不远，实际的期望却已不同：隋要求更明确的臣属、更定期的朝贡，以及在辽东问题上的让步。高句丽在名分上不退，在实际控制上也不让，落差逐渐积累。598年，高句丽联合靺鞨进扰辽西，隋文帝遂以三十万之众分道东征，遇雨季与疫病，粮运不继而还。</p>
            <p>把一百多年间的封号排比，可以看出规律。中原王朝从未放弃对辽东的名义主张，因此最高只肯给到郡公，偶尔进爵为王，也只是权宜；高句丽始终接受册封，却从不因册封而交出城邑。册封的价值在于合法性与贸易，对中原王朝则在于维持一个名义上的秩序。双方都清楚这是一笔交易，朝贡可以年年进行，边境的冲突也可以同时发生。</p>
            <p>使节的路线分陆海两途。陆路自平壤北上，经辽东、辽西的营州入幽州，再南下至中原或关中；这条路由中原王朝控制，使节的安全取决于边境形势。海路自辽东半岛南端或大同江口登舟，横渡渤海，于东莱一带上岸，再转赴建康或洛阳。南朝与高句丽的往来多走海路，因为陆路须穿越北魏境内，政治上门槛太高；海路则受季风制约，往返须择其时。</p>
            <p>外交与军事在这里从来不是替代关系。朝贡的年份里，边境的寇掠照旧发生；军事失利之后，谢罪的使节又随即出发。中原王朝也遵循同样的逻辑：一面受贡、封王，一面在营州、幽州集结兵力。598年以后的冲突，正是这种交替逻辑走到尽头的表现：当隋唐的力量足以支撑跨海投送与长期围困时，册封所提供的缓冲便不再有效。</p>
            <p>从北魏到陈隋，高句丽的南北外交维持了将近两个世纪。它依赖的是一个分裂的大陆：只要南北两朝并存，高句丽便可在两边取得承认，以一方制衡另一方。隋的统一终结了这个前提，唐的强盛又把它推向极端。外交的空间随大陆的统一而收缩，这大概是这段历史最清楚的一条线索。</p>
        `,
    },
    {
        id: "tang-naval-goguryeo",
        title: "跨海之师：唐军的水军与登陆作战",
        date: "2026-11-25",
        tags: ["唐与高句丽", "水军", "登陆战"],
        summary: "唐征高句丽的关键一环是跨海投送。来护儿自东莱入海，孤军深入而败；张亮取卑沙城，在辽东半岛南端建立登陆点；苏定方自成山渡海，直取锦江口灭百济；刘仁轨与杜爽在锦江下游确立制海权。船型、季风与滩险约束航路，登陆点的选择与水陆协同的得失，决定灭国战能否成立。唐军前后经营二十余年，海路始终是其中一环。",
        content: `
            <p>唐对高句丽的战争，常被写成陆路攻城的历史：大军出幽州、营州，循辽西走廊东进，顿于辽东城与安市城下。但改变战局的，是跨海投送。水军把兵员、粮秣与攻城器械从山东半岛送到辽东与半岛西海岸，使唐军得以绕过辽东山地，从侧后进入战场。没有这条通道，先灭百济、再南北夹击的方略无从谈起。</p>
            <p>隋代已有先例。大业八年，来护儿率江淮水军自东莱入海，船舰相衔数百里，直抵平壤附近的浿水，破沿岸守军，一度攻入外城。然而纵兵剽掠，队形散乱，高句丽伏兵自城内出击，水军大败；来护儿退泊海口，此后只能在海上游弋。大业九年、十年再举，水军仍自东莱出发，却始终未能与辽东的陆军夹击。孤军深入、缺乏登陆基地、与主力通信断绝，是三次无功的共同原因。水军既退，陆军便失去唯一可以牵制平壤的力量，只能按原定日期向鸭绿水推进。</p>
            <p>贞观十九年，张亮以平壤道行军大总管率水军四万三千、战船五百艘，自莱州渡海，直取辽东半岛南端的卑沙城。卑沙一般比定为今大连金州大黑山上的山城，城依山势，一面临海，控制渤海海峡北口。唐军登陆后攻拔此城，获男女八千口。其意义不在杀伤，而在取得一个可屯粮、候风、整军的港口与桥头堡。</p>
            <p>张亮军的后续并不顺利。此后他北上至建安城下，与太宗的主力相隔数百里，始终未能会师；高句丽军乘其兵少而袭击，张亮一度失措，赖部将力战才稳住营垒。这一年的水陆两路各打各的：陆军在辽东城、安市城一线推进，水军在半岛南端独立作战。协同的困难不在将领的意愿，而在两军之间隔着城邑与山地，消息与命令都要绕行。</p>
            <p>海船的形制与运量是理解这类作战的前提。唐代水军有楼船、蒙冲、斗舰、走舸等名目，内河战船求轻快，海船则求体大底深、能抗风浪。通行说法以为大型海船可载数百人，运粮船则以石计；但船越大，吃水越深，能停靠的港口越少。辽东与半岛西海岸多滩涂与礁石，大船往往须泊于近海，再用小舟转运，登陆速度因此受潮汐与天气支配。</p>
            <p>季风是另一重约束。渤海与黄海冬季多北风，夏季多南风；唐军东征多在春夏出发，秋后作战，入冬前撤返。风信不合，船队只能滞泊，粮秣在等待中消耗。刘仁轨早年督海运，遇风覆船，坐免官，白衣从军，这条记载说明海运的风险是制度性的：它无法像陆路那样按日计算行程。</p>
            <p>显庆五年，苏定方以神丘道行军大总管率水陆之众自成山渡海。成山在今山东荣成，是山东半岛最东端的岬角，自此东渡航路最短。唐军在熊津江口登陆，即今锦江入海处，击破据江口拒守的百济军，随即直趋泗沘城，围而克之，百济义慈王出降。新罗金春秋率陆军自东侧配合，两路日程这次衔接得较好，百济在数月之内灭亡。</p>
            <p>百济既灭，水军的任务从登陆转为封锁与护航。龙朔三年，倭国水军护送百济余部北上，与刘仁轨、杜爽所统唐军在锦江下游的白江口相遇。白江口与熊津江口同处一个河口，是外海船只进入锦江的咽喉。唐军船少而体高，列阵冲击，四战皆捷，焚倭船四百余艘。此役之后，倭国不再大规模介入半岛，百济复国运动失去外援，唐军在半岛西海岸的制海权得以确立。</p>
            <p>登陆点的选择有几条可归纳的条件。其一是河口，熊津江口与白江口都便于船只溯入，避开外海风浪；其二是滩涂与潮差，须能在涨潮时靠岸、退潮时卸货；其三是淡水与薪柴，数万人马屯驻，水源比港口更要紧；其四是与目标城的距离，登陆点若离城太远，部队在行军中就会暴露。辽东半岛南端、锦江口、白江口、大同江口，都是按这几条选中的；其中大同江口直对平壤，是最后围城战中海路运粮的落点。</p>
            <p>水陆协同的关键是补给，而非仅仅是夹击。唐军在辽东的粮运，一自幽州、营州陆运，一自山东半岛海运；海运运量大、成本低，却受风汛与港口限制。总章元年围平壤，海路的运粮与封锁同时进行，城中粮尽，守军才失去坚守的可能。反过来看，水军一旦失期，陆路主力的时间表就被打乱，张亮军与刘仁轨的两次失期，都是这种连锁反应的例子。</p>
            <p>水军将领的出身值得注意。来护儿是江淮人，熟悉水战；张亮起于寒微，长于行政与后勤；苏定方以骑兵起家，却能统率跨海之众；刘仁轨是文吏出身，因海运获罪而从军，最终成为半岛水军主将。唐前期还没有独立的水师军种，水军多由陆军将领临时统率，船只与船夫从沿海州县征发。这种编成灵活，却使专业经验难以积累。</p>
            <p>制海权对灭国战的意义可分三层。战术上，它使唐军能在高句丽防线的侧后登陆，避开辽东山地的正面强攻；战役上，它使先灭百济、再南北夹击的方略成为可能；战略上，它切断了高句丽与百济、倭国之间的海上联系。但制海权不是万能的：水军可运兵粮，却不能深入腹地，也不能替代陆路围攻。海上力量若不与陆路配合，便难以转化为领土控制。</p>
            <p>从隋代的来护儿，到张亮、苏定方、刘仁轨，跨海作战的经验在二十余年间积累起来：登陆点由试探而固定，船队由临时征发而稍具规模，水陆协同由脱节而渐能衔接。唐军最终攻破平壤，海路的运粮与封锁是其中不可省略的一环。这段历史提示，七世纪东亚的战争，胜负往往取决于谁能把兵力与粮食送过那片海。</p>
        `,
    },
    {
        id: "goguryeo-armor-weapons",
        title: "高句丽的甲骑与兵器：壁画与出土物所见",
        date: "2026-11-26",
        tags: ["唐与高句丽", "军事", "考古"],
        summary: "高句丽军事装备研究依赖集安、平壤壁画墓与城址出土物两类材料。壁画显示四至五世纪已有具装骑兵，马铠、兜鍪、札甲形制与中原、鲜卑技术圈相通；出土铁甲片、双镫马具与箭镞则揭示本地工艺与实战面相。作者强调壁画具仪卫与程式化性质，不能当写实照片，甲骑规模亦不宜夸大，须与出土物、文献互证。",
        content: `
            <p>研究高句丽的军事装备，材料大体分两类。一类是集安、平壤一带的壁画墓，出行图与战争图里画着披甲的战马与骑士；另一类是城址、墓葬出土的铁甲片、兜鍪、马具和兵器。前者是墓葬装饰，带观念与礼仪的成分；后者是残损的实物，能提供形制与工艺的细节。两类材料必须合看，单靠哪一类都容易走偏。</p>
            <p>壁画中最显眼的是具装骑兵。集安铠马冢、三室冢等墓的出行队列中，马身覆甲，马头有面帘，颈有鸡颈，胸前当胸，马背与臀后另有甲片，马鞍后常竖起状如扫帚的寄生。这些名目来自中原甲骑具装的研究传统，高句丽图像的基本结构与之一致，说明它处在同一个技术圈内，而不是孤立发展出来的装备。</p>
            <p>骑士也披甲。壁画所见多为头戴兜鍪、身著札甲、肩加筒袖的形象，甲片以横向或纵向排列，用色块与线条示意。画工未必逐片描摹，因此不能凭画面去数甲片、算重量。但甲骑在队列中的位置值得注意：他们常居于行列前端或簇拥主将，带有仪卫与夸示的意味，未必等同于实战编成。</p>
            <p>这些壁画墓的年代多集中在四至五世纪，分布在集安通沟一带与平壤附近。墓葬的规模、壁画的题材与墓主身份相关，出行图越长、甲骑越多，往往意味着墓主地位越高。这一层关系提醒我们，图像首先是身份的表达，其次才是军事的记录，两者不能混为一谈。</p>
            <p>出土物补上了另一面。集安、平壤一带的城址与墓葬中，常见锈结成块的长条形、方形铁甲片，穿孔以皮条或绳索编缀，属于札甲系统。甲片的厚薄不一，边缘有打磨痕迹，说明制作已有分工。复原时按穿孔位置推编缀方式，能得到大致的甲衣形制，但细节仍有推测成分。</p>
            <p>兜鍪的发现同样重要。高句丽遗存中的兜鍪多为半球形顶，附护颊与护颈，有的顶端有插缨或盔形装饰。这些形制与辽东、辽西同时期的遗物有可比之处，但本地制作的痕迹也很明显。盔甲的防护重点在头颈，与甲骑在马上作战的姿态相符。</p>
            <p>马具的发现更能说明问题。鞍桥、镳衔、辔饰、马镫都有出土，高句丽的双镫出现较早，与慕容鲜卑三燕地区的马具关系密切。具装骑兵需要高鞍与双镫来稳定骑手，马具的改良与甲骑的盛行互为条件。这条线索比单看甲片更能揭示装备体系的整体变化。</p>
            <p>兵器以弓箭为核心。壁画与文献都强调高句丽人善射，出土箭镞有柳叶形、三角形等样式，铁矛、环首刀、铁刀亦有发现。弓的实物难以保存，只能从箭镞形制与文献记载推测其性能。箭镞的数量在城址防御遗存中往往最多，说明远程火力是守城的主要手段。</p>
            <p>甲骑的战术价值与局限，需要分开看。具装骑兵长于正面冲击与威慑，但马匹负重高、冲刺距离短，在山地与水田地区难以展开。高句丽的战争以攻城与守城为主，甲骑更多出现在野战与仪仗场合。把它当成决定胜负的兵种，是对壁画图像的过度解读。高句丽的山地与城防体系，决定了甲骑难以成为战场的主角。</p>
            <p>长短兵器的比例，因遗址性质不同而差异很大。墓葬随葬更看重刀剑的标识意义，城址则多见消耗性的箭镞与矛头。这种差别提醒我们，统计兵器比例之前要先问遗址性质，否则很容易把随葬品的象征选择当成军队的实际装备结构。</p>
            <p>冶铁与工艺的来源，是另一个争论点。高句丽境内有铁矿，冶铁遗址与铁渣在城址附近有发现，本地生产应无疑问。但甲片形制、编缀方式与马具样式又显示外来影响。较合理的看法是：本地生产为底，通过战争、朝贡与人口流动持续吸收外来技术，形成混合的工艺传统。</p>
            <p>与中原、鲜卑、三韩的比较，不宜简化为谁影响谁。四至五世纪辽东、辽西的动荡，客观上加速了工匠与技术的流动，甲骑具装在这一时期趋于成熟。高句丽处在农耕与草原的交界，既能吸收中原的甲制，也能获得鲜卑的马具，这种位置本身就是一种资源。</p>
            <p>研究史也影响材料的解读。二十世纪以来，集安与平壤的壁画墓陆续被发现、摹绘与调查，甲骑图像逐渐成为讨论高句丽军事史的核心材料。早期研究多直接以壁画复原军制，后来的学者更强调图像的类型学与年代序列，方法上已趋于谨慎。</p>
            <p>壁画的限度必须说明。墓葬图像是礼仪性、观念性的，出行图与战争图经过程式化处理，甲骑的数量、队列的整齐、铠甲的华丽都可能有夸张。若把壁画当作写实照片，就会高估高句丽军队的装甲化程度，也会忽略图像背后事死如事生的表达意图。</p>
            <p>保存条件构成另一重限制。铁器在酸性土壤中腐蚀严重，出土甲片多为残片，复原难免带推测成分。同一座墓的壁画与随葬品也未必属于同一时期，断代要靠墓葬形制、共出遗物与壁画题材综合判断，误差常以数十年计，不宜把结论说得太死。</p>
            <p>较稳妥的看法是：高句丽在四至五世纪已拥有具装骑兵，甲骑是其军事力量的重要支点，但规模与普及程度不宜夸大；装备体系兼有本地传统与外来影响；壁画图像只有与出土物、文献互证，才能当作史料使用。至于甲骑在野战中的实际比重，现有材料还不足以给出确切数字。</p>
        `,
    },
    {
        id: "tang-liaodong-fortifications",
        title: "唐军在辽东的筑城与驻防",
        date: "2026-11-27",
        tags: ["唐与高句丽", "军事地理", "城防"],
        summary: "唐丽战争的骨架是城与路：辽东城、白岩城、安市城的攻守，背后是转输、季节与驻军结构。唐军善用云梯、抛车、土山，却受辽左早寒与粮道漫长的约束，安市城久攻不下即是明证。灭高句丽后安东都护府一再内迁，说明唐的据点经营多为修缮旧城、以点控线，攻城易而守土难，成本始终受制于后勤与人力。",
        content: `
            <p>唐与高句丽的战争，常被写成几次大战役的串联：贞观十九年亲征、白岩城与安市城的攻坚、乾封年间的金山与扶余城、总章元年平壤陷落。但战争真正的骨架是城与路：哪些城能守住，粮从哪条道来，什么季节可以驻兵。这些问题决定了战役能打多久，也决定了胜利能否转化为统治。</p>
            <p>在唐之前，隋已经在这条路上付出过代价。大业八年以后，隋军数次渡辽，围攻辽东城，兵力远超守军，却因指挥混乱、后勤不继而退。唐初的君臣对这段经验记忆深刻，贞观年间的进军因此在路线、季节与粮运上做了更周密的安排。</p>
            <p>几座城的方位，大致可以确定。辽东城在今辽阳，白岩城在今辽阳以东的燕州城，安市城在今海城一带的山城，卑沙城在今大连金州的大黑山，盖牟城则在沈阳附近。唐军攻取这些城，目的是控制辽河渡口、半岛南端与通往平壤的道路。具体定点仍有争议，但地理格局是清楚的。</p>
            <p>贞观十九年唐太宗亲征，进军路线沿辽东故道：渡辽水，攻辽东城，下白岩城，进至安市城。辽东城是旧有重镇，唐军破城后并未另筑新城，而是修整利用。这一点很重要：唐在辽东的据点经营，多数是接收、修补高句丽与北朝以来的旧城，而非白手起家。</p>
            <p>安市城之战是攻坚的典型。唐军筑土山以逼城，用抛车、撞车、云梯轮番进攻，土山崩压城墙，守军却连夜堵塞缺口。围城数十日不下，辽左早寒，草枯水冻，粮运不继，唐太宗遂班师。这一仗说明，攻城技术的优势并不能自动转化为战略胜利。</p>
            <p>唐军的攻城手段大致有云梯、撞车、抛车、土山、地道几种。抛车抛掷石弹，撞车撞击城门，土山用于居高临下，地道则试图从城下穿入。这些手段在《通典》与兵书中有系统记载，唐军在辽东的使用也见于实录。但手段齐全不等于奏效，关键仍在守军的补给与意志。</p>
            <p>高句丽的山城多依山势筑墙，石砌厚重，城内有水源与仓储，正面强攻代价极高。唐军因此常采取长期围困、断其汲道、分兵略地的办法，攻坚战往往演变为后勤与耐力的较量。山城体系的设计逻辑，本就是以少量兵力拖住大量敌军。</p>
            <p>后勤是更硬的约束。辽东冬季来得早，九月以后野无所掠，粮道漫长。唐军一方面由营州陆路转输，一方面用水军从莱州渡海，直趋平壤或辽东半岛南端。水运成本低但受风信限制，陆运稳定但消耗巨大。贞观年间几次进军都因粮尽而退，原因多在这里。</p>
            <p>水军的组织是另一条线索。贞观年间张亮率舟师自莱州渡海，攻取卑沙城；此后唐廷又下令造大船，以备海运。海路缩短了距离，却受风信与季节限制，船只与人员的损耗也不小。唐在辽东的后勤，实际上是陆海两套系统并用，互为补充。</p>
            <p>营州是唐在东北的枢纽。它既是陆路转输的起点，也是羁縻契丹、奚等部族的据点。唐军出征，常以营州为集结地，粮秣、马匹、民夫由此北上。营州一旦不稳，整个辽东战线的后勤就会动摇，后来营州之乱对东北局势的冲击，正说明这个节点的分量。</p>
            <p>总章元年灭高句丽后，唐设安东都护府，初治平壤，统辖羁縻府州，留兵驻守。都护府之下设都督府、州，以高句丽旧地与部族首领为依托。这是一种低成本的控制方式，但它依赖当地合作者，中央能直接调动的兵力与财力其实有限。</p>
            <p>都护府的治所此后一再内迁，先移辽东故城，再移新城。治所的移动本身就说明：唐在半岛的驻防重心，从直接控制平壤退向守住辽河以东的交通线。这种退守不是某一次决策的结果，而是兵力、财政与半岛局势长期作用的结果。</p>
            <p>驻防的另一面是人力。唐在辽东的常驻兵力有限，多依赖羁縻州部族、降附的高句丽将领与百济故地的府兵。这种以本地人守本地的方式成本较低，但忠诚度随局势波动。罗唐关系恶化后，百济故地与高句丽南境的守御立刻吃紧，正是这种结构的弱点。</p>
            <p>筑城的记载相对零散。唐在辽东大规模新建城池的例子不多，更多是修缮旧城、增设戍堡、控制渡口与山口。这种做法与高句丽的山城体系并不冲突，唐实际上沿用了后者的空间逻辑：以点控线，以城守道。差别在于唐更依赖后方的转输网络。这种做法节省人力，却使唐始终缺乏自己新建的坚固支点。</p>
            <p>战后，高句丽的旧城并没有消失。唐的羁縻府州依托这些城池，渤海兴起后又加以利用。城池是耐久的设施，谁占据辽东，就不得不接手这套既有的空间体系。唐的退缩与渤海的扩张，某种程度上都是在这套体系内重新分配据点。</p>
            <p>季节与气候塑造了战争的节奏。辽左早寒，唐军多在春夏进兵，秋冬之前必须决定退守或撤军。高句丽则习惯于坚壁清野、待敌粮尽。双方对季节的不同利用，使战争呈现出年复一年的拉锯，而不是一次决战定胜负。</p>
            <p>从这个角度看，唐在辽东的筑城与驻防，是一套成本高昂、依赖后勤的体系。它能支撑长期战争，却难以在短期内转化为稳固的统治。安东都护府的内迁，以及后来渤海兴起后唐在辽东的退缩，都提示：城池可以攻取，交通线与人力结构却需要更长的时间经营。</p>
        `,
    },
    {
        id: "baekje-restoration",
        title: "百济复国运动：灭亡之后的三年",
        date: "2026-11-28",
        tags: ["唐与高句丽", "百济", "东亚史"],
        summary: "660 年百济灭亡后，鬼室福信与僧道琛拥立扶余丰，据周留城等据点起兵，并向倭国求援。663 年白江口之战，唐军水师击败倭国与百济联军，复国运动随之瓦解。作者指出，复国失败根源于抵抗分散、缺乏统一后勤；战后百济遗民分入唐、入倭与留居故地，而唐罗对百济故地的安排已埋下双方冲突的种子。",
        content: `
            <p>660 年，唐罗联军攻陷百济都城泗沘，义慈王投降，百济作为国家在形式上灭亡。但战争并未结束。此后的三年里，百济遗民在故地起兵，拥立王室后裔，向倭国求援，与唐罗联军反复争夺城池。这段历史通常被称为百济复国运动。</p>
            <p>灭百济之役由苏定方统率唐军，新罗金庾信率军配合。联军自海陆并进，绕过坚固的防御，直趋都城。百济的抵抗在都城陷落后迅速瓦解，王室与大臣被押送长安。但占领军兵力有限，只能控制主要城池与交通线，广大乡野仍在地方势力手中。</p>
            <p>都城陷落后，义慈王与太子扶余隆被送往长安。唐高宗赦其罪，授官安置，试图以王室的名义安抚百济遗民。后来扶余隆被派回故地任熊津都督，正是这一政策的延续。但王室的号召力在亡国之后已大打折扣，地方势力各怀打算。</p>
            <p>起兵的核心人物是鬼室福信与僧人道琛。他们在周留城一带聚集余众，据守城池，并派人赴倭国迎回作为人质的王子扶余丰。拥立王室后裔，使这场抵抗获得了名分：它不是地方叛乱，而是恢复社稷。这一点对争取民心与倭国援助都很关键。</p>
            <p>扶余丰的归来，是复国运动的关键一步。他长期滞留倭国，回来时带着倭廷的支持与一批随行人员。有了王室的血统，复国军就能以百济的名义号令旧部，也能以国家的身份与倭国交涉。名分在当时的东亚政治中不是虚文，它直接关系到能否获得外援与承认。</p>
            <p>复国军内部并不团结。扶余丰与鬼室福信之间互相猜忌，福信后来被杀，道琛也在此前去世。指挥核心的自相残杀，削弱了复国军的组织能力。外援未至而内衅先起，这在亡国后的抵抗运动中并不罕见，也是其难以持久的原因之一。</p>
            <p>复国军的战略是守住百济南部与沿海据点，等待倭国援军。周留城、任存城等城成为支撑点。唐军方面，刘仁愿、刘仁轨留守百济故地，兵力有限，一度只能困守府城。双方在城与城之间拉锯，谁也无法迅速决胜。</p>
            <p>倭国的介入有其自身的考虑。百济是倭国在半岛最重要的盟友，也是大陆文化输入的中转。百济灭亡意味着倭国在西方的屏障消失，半岛的势力平衡被打破。对倭廷而言，出兵既是履行同盟义务，也是维护自身在区域秩序中的位置。</p>
            <p>倭国的出兵并不顺利。齐明天皇在九州去世，出征计划一度延缓，直到 663 年才大举渡海。这段耽搁给了唐军整顿防务、集结兵力的时间。复国军等待的援军，来得比预期更晚，也更仓促。</p>
            <p>663 年的白江口之战是转折。唐军水师与倭国、百济联军在白江口交战，唐军以战船阵型与火攻取胜，倭军大败。扶余丰脱身逃往高句丽，复国军的指挥核心瓦解。此后唐军分路攻取剩余城池，抵抗逐渐平息。</p>
            <p>白江口之战的意义常被放大为东亚格局的转折。就战役本身而言，它确实摧毁了倭国在半岛的投送能力，也使百济复国失去外援。但复国运动失败的根本原因，还在于百济故地的抵抗始终是分散的城池据守，缺乏统一的兵力与稳定的后勤。</p>
            <p>白江口之后，百济故地仍有城池坚守。任存城等地的抵抗持续了一段时间，唐军以招降与进攻并用，才逐步平定。这些残余据点说明，复国运动虽有指挥核心，其基础却是分散的地方势力，核心瓦解后仍能各自为战。</p>
            <p>战后唐在百济故地设熊津都督府，以扶余隆为都督，试图通过百济王室后裔来安抚遗民。这种安排与安东都护府的做法相似：以本地首领为名义长官，唐军驻扎要地。但扶余隆的号召力有限，地方势力并不都服从，实际控制仍靠军队维持。</p>
            <p>唐罗联军内部的分工也值得注意。灭百济时，新罗军负责助攻与向导，唐军承担主力攻坚。战后唐以百济故地归自己管辖，新罗则获得了实际的土地与人口。这种安排埋下了罗唐矛盾的种子，数年后双方即兵戎相见。</p>
            <p>复国失败后，百济遗民的去向大致有三。一部分被迁入唐内地，一部分随倭军退回日本列岛，还有一部分留居故地，后来成为统一新罗的编户。也有不少人入唐为将，如黑齿常之，先降唐，后在唐与吐蕃、突厥的战争中立功。他们的去向，也影响了此后半岛与日本列岛的人口构成。</p>
            <p>百济复国与后来高句丽遗民的抵抗，有相似之处：都依托旧城，都试图借外援，也都因内部不协而失败。差别在于百济有王室后裔可供拥立，名分较为集中；高句丽灭亡后则缺乏这样的象征人物，抵抗更为零散。把两者并看，可以看出灭国之后抵抗运动的共同条件：名分、外援、据点与内部团结，缺一不可。</p>
            <p>史料方面，白江口之战的主要记载来自《日本书纪》，细节丰富但立场鲜明，带有为倭廷讳饰与夸大唐军规模的倾向。《旧唐书》《新唐书》《三国史记》的记载较简，可与之互校。使用时要注意各书的关注点不同，不能把单一叙述当作全景。</p>
            <p>三年的复国运动，最终没有改变半岛的政治地图。但它揭示了灭国战争之后的一般难题：占其都城易，服其人心难；拥立一个王室后裔，就足以让占领者在数年内不得安宁。唐在百济故地的折冲，与其在高句丽故地的经验，其实是同一类问题。</p>
        `,
    },
    {
        id: "silla-unification-cost",
        title: "统一新罗的代价：战争、户口与地方秩序",
        date: "2026-11-29",
        tags: ["唐与高句丽", "新罗", "社会史"],
        summary: "新罗借唐之力灭百济、高句丽，又在 670 年代与唐交战，完成半岛大部分的统一。作者把视线从疆域转向代价：战争造成人口损耗与迁徙，军功集团需要安置，百济、高句丽故地的地方豪族被纳入州郡县的双层结构，而骨品制并未随疆域扩大而改造。这些结构性问题在九世纪的地方动乱中显现，统一的账单远比传统叙述复杂。",
        content: `
            <p>新罗借助唐的力量，先后灭百济与高句丽，又在 670 年代与唐交战，最终控制大同江以南的半岛大部分。传统叙述把这称为统一，并视为新罗历史的顶点。但若把视线从疆域转向人口与制度，统一的过程更像一次代价高昂的重组。</p>
            <p>战争的过程本身就很漫长。660 年灭百济，668 年灭高句丽，此后新罗与唐为争夺百济故地和高句丽南境又打了数年，直到 676 年唐军后撤，战线才大致稳定在大同江一线。这十余年间，半岛大部分地区都处于动员状态。</p>
            <p>罗唐战争的具体进程，记载有限。670 年前后双方在百济故地发生冲突，675 年买肖城一战新罗取胜，676 年唐军后撤，安东都护府内迁。战线的移动说明，新罗的目标不是与唐全面决裂，而是把既得的地盘固定下来。双方最终以大同江为界，形成长期并存的格局。</p>
            <p>首先是人口的损耗。长期战争、灭国后的迁徙与抵抗，使半岛人口大幅流动。唐将大量百济、高句丽人口迁入内地，新罗则接收故地的土地与部分人口。劳动力、兵源与纳税人的重新分配，比疆域的划定更深刻地改变了社会。</p>
            <p>户口数字在《三国史记》地理志中有所保存，但多属后一时期的统计，不能直接等同于七世纪的情况。学者利用这些数字估算统一新罗的编制规模，往往要结合州郡设置、贡赋记载与考古材料，结论差异不小。数字看似精确，背后的统计口径却常不清楚。任何以户口数推断国力的人口史研究，都要先做史料批判。</p>
            <p>其次是军功集团的安置。统一战争中立功的将领与地方势力，需要在新的秩序中获得位置。新罗以爵位、食邑、州郡官职来酬功，但官职有限，赏赐又不能无限扩张。军功集团与旧贵族之间的张力，成为统一后政治的一个长期问题。</p>
            <p>花郎集团在统一战争中作用显著，战后却难以安置。他们既是军事精英，也是贵族子弟的网络，与骨品秩序相互缠绕。战争结束后的论功与编制，反而加剧了贵族内部的竞争。军功与门第，成了两套并不总是重合的评价标准。新罗的军制因此带有浓厚的贵族色彩，中央常备军始终有限。</p>
            <p>第三是地方豪族的整合。百济、高句丽故地原有自己的城主、村主与地方势力，新罗将其纳入州郡县体系，设置都督、太守，同时保留部分地方首领的地位。这种双层结构在初期有效，但随着时间推移，地方势力重新坐大，中央的控制力随之减弱。</p>
            <p>对新罗而言，百济故地的经营是统一后的第一道考题。这里原有自己的贵族与官僚，新罗既要利用他们，又要防止其坐大。设置州郡、迁徙人口、屯田驻军，都是常见手段。整合是否成功，取决于中央能否持续提供资源与威慑。</p>
            <p>骨品制是理解新罗政治的钥匙。真骨与六头品构成统治核心，王位多在真骨内部传递，重要官职按骨品限定。统一扩大了国家的规模，却没有相应改造这套身份秩序。结果是：可任官的人口基数没有随疆域同步扩大，人才的吸纳受到限制。</p>
            <p>王权与贵族的紧张贯穿统一新罗的中后期。国王试图借助佛教、律令与新的官僚机构强化权力，贵族则以骨品与门第相抗衡。王位继承的频繁变动、宫廷政变的增多，都是这种结构性紧张的表现，不能简单归因于某几个君主的性格。</p>
            <p>地方秩序的另一面是交通与行政成本。疆域扩大后，从首都庆州到半岛北部的路程遥远，文书往返、军队调动、赋税转运都变得更昂贵。新罗设置五京、九州，试图以多点支撑的方式管理，但边缘地区的实际控制仍然依赖地方首领的合作。统一后的行政效率，并不必然高于统一之前。</p>
            <p>赋税与户籍是制度能力的直接体现。统一新罗沿用租庸调式的赋役，以村主、城主负责征收，户籍与田籍的编制依赖地方合作。疆域扩大后，边远地区的户籍往往不实，中央的财政汲取因此受限。制度的纸面规定与实际执行之间，差距不小。</p>
            <p>九世纪的动乱，其远因多可追溯到这里。地方豪族与商人势力成长，中央却因骨品限制与财政困难难以吸纳；张保皋在清海镇经营海上贸易，即是地方力量脱离中央掌控的例子。822 年金宪昌之乱，更是王权与贵族矛盾的一次爆发。</p>
            <p>此后地方势力割据，后百济与后高句丽（泰封）相继建立，半岛进入后三国时代。这一过程常被写成王朝更替，但更准确地说，是中央无法整合地方力量的必然结果。统一新罗的制度能力，始终没有跟上它扩张后的疆域规模。</p>
            <p>评价统一，需要区分不同层面。就疆域与政治整合而言，新罗确实完成了一次前所未有的统一；就制度与社会的代价而言，战争损耗、军功安置、地方豪族的再起与骨品制的僵化，都是统一的账单。把这些说成进步的必然代价，反而遮蔽了具体的选择。区分这两个层面，比笼统的褒贬更有解释力。</p>
            <p>更公允的说法或许是：统一新罗获得了一个更大的国家，却没有同步获得与之匹配的制度能力。它靠战争立国，靠身份秩序维持统治，最终也被这两者所困。九世纪的地方动乱与后三国的出现，并不是突如其来的衰败，而是长期结构性问题的显现。</p>
        `,
    },
    {
        id: "goguryeo-buddhism",
        title: "高句丽的佛教与国家：寺院、僧侣与王权",
        date: "2026-11-30",
        tags: ["唐与高句丽", "佛教", "制度"],
        summary: "佛教于 372 年由前秦传入高句丽，走的是使者送经、国王接纳的国家通道，因而自始与王权绑定。寺院多建于都城附近，佛教为王权提供超越血缘的正当性，却与山神、始祖祭祀并存而非取代。僧侣兼具外交与情报角色，道琳的故事虽属传奇，仍反映时人想象。与百济、新罗相比，高句丽佛教与王权结合早而制度化程度较浅。",
        content: `
            <p>佛教传入高句丽，通行说法是 372 年：前秦苻坚遣使送佛像与经文，小兽林王接纳。此后数十年，寺院建立，僧侣活动见于记载。这个时间点与百济、新罗相比略早，半岛三国的佛教化由此展开，而高句丽是先行者。传入的具体年代与人物，学界仍有讨论，但 372 年之说最为通行。</p>
            <p>前秦在当时是北方最强大的政权，也是佛教传播的重要推手。苻坚礼敬道安，支持译经，向外派遣使者时往往附带佛像与经典。对高句丽而言，接受这套礼物，既是文化上的选择，也是外交上的姿态：它表明自己愿意纳入中原王朝主导的文化秩序。</p>
            <p>佛教在高句丽的初传，没有留下激烈的排佛记载。这与新罗形成对比：新罗在六世纪初仍有异次顿殉教的传说，说明接受过程伴随冲突。高句丽的顺利，可能与王权的主动推动有关，也可能与史料保存的偶然性有关，不宜简单归因于民族性格。</p>
            <p>小兽林王之后，故国壤王于 392 年下教崇信佛法，佛教从王室个人的信奉转为国家的政策。这一转变很关键：国王以诏令的方式要求臣民信佛，意味着佛教开始进入国家礼仪与地方治理，而不只是宫廷中的外来信仰。</p>
            <p>寺院随之建立。据《三国史记》，小兽林王时期已建省门寺、伊弗寺，此后平壤等地陆续有寺院。寺院是佛教的制度载体：它有僧团、戒律、田产与日常仪式，能持续存在并自我复制。没有寺院，佛教就只是零散的信仰，无法形成稳定的组织。</p>
            <p>王室对佛教的扶持，有具体的政治功能。五至六世纪的高句丽，王权需要在中原王朝、地方贵族与部落传统之间确立自身的正当性。佛教提供了一套超越血缘与地方神祇的宇宙秩序，王可以作为护法者出现，这与以王为祭祀中心的旧传统并不完全相同。</p>
            <p>但旧传统并未消失。高句丽的建国神话、山神崇拜、始祖祭祀仍在国家礼仪中占据位置。佛教与地方信仰的关系，更接近并存与叠合，而不是取代。寺院建在山城附近、王室同时祭祀山川，这类现象提示我们：宗教政策往往是加法，不是减法。</p>
            <p>僧侣的角色不限于宗教。在对外交往中，僧人是少数能跨越语言与政权边界的人群。他们随使团往来，传递消息，也参与文化的输入。高句丽僧慧慈赴倭，即是这类流动的例子。僧侣的外交功能，在当时的东亚是一个普遍现象，不独高句丽为然。</p>
            <p>僧侣还承担讲经与教育的职能。寺院是当时少数能提供识字、诵经与义理训练的场所。贵族子弟在此学习，僧侣由此进入上层网络。宗教机构与文化再生产结合在一起，这是佛教能长期立足的原因之一。</p>
            <p>关于僧侣从事情报活动的记载，最著名的是道琳。据《三国史记》，渊盖苏文派道琳入新罗，假意出家，为新罗王室所信，后来引导新罗修筑城池、消耗国力。这个故事带有明显的传奇色彩，是否属实难以确证，但它反映了时人对僧侣跨界活动的想象。</p>
            <p>寺院的经济基础也值得注意。寺院拥有田产、奴婢与依附人口，这些来源包括王室赐予、贵族施舍与信众捐赠。寺院经济一旦成形，便成为国家财政之外的另一套资源网络。它既能支持宗教活动，也可能与国家的赋役征收发生冲突。</p>
            <p>王室寺院还承担国家仪式。为国祈福、超度阵亡者、祈求丰年，这些法会由王室主导，僧侣执行。宗教仪式把王权、僧团与民众连接起来，也为寺院带来了布施与土地。政治与宗教的交换，在这里是具体的、日常的。</p>
            <p>佛教艺术留下了较可靠的物证。高句丽寺院遗址中出土的瓦当、佛像、莲花纹砖，说明其建筑规模与装饰水平。佛像的样式带有北朝风格，与中原的造像系统相通。这些物件比文献更能说明佛教在实际生活中的存在方式。</p>
            <p>与百济比较，两者都与中原王朝保持密切的佛教往来，但百济与南朝的交涉更多，其佛教艺术受南朝影响较明显。百济还把佛教与工艺传往倭国，僧昙征相传带去造纸与墨的技法。高句丽的佛教则更多与北朝系统相连。</p>
            <p>与新罗比较，差别在制度化的深度。新罗佛教起步较晚，却在六至七世纪迅速发展，与国家体制的结合更深，花郎与佛教的关系、王室对寺院的直接控制都更明显。高句丽的特点，是佛教与王权的结合较早，但制度化的程度似不如新罗。</p>
            <p>佛教之外，儒学与本土信仰同样存在于高句丽的国家生活中。史载高句丽设太学，教授五经，官僚的培养依赖儒学经典。佛教提供宇宙论与仪式，儒学提供治术与伦理，两者并行不悖。把高句丽描述为单纯崇佛的国家，会漏掉这层制度现实。</p>
            <p>灭国之后，高句丽佛教的脉络并未断绝。部分僧侣入唐，部分留在故地，后来融入渤海与统一新罗的佛教体系。这说明宗教的传播并不以政权为边界，国家的灭亡可以终止一个政治体，却难以终止一套已经扎根的信仰与仪式。</p>
            <p>总体而言，高句丽的佛教是国家主导下的宗教输入，寺院、僧侣与王权构成了一个互相支撑的结构。它没有取代地方信仰，也没有发展出独立于国家的教会组织。评价它的历史位置，与其说高句丽是一个佛教国家，不如说佛教是王权用来整合与表达自身的一种资源。</p>
        `,
    },
    {
        id: "tang-goguryeo-diplomacy",
        title: "唐与高句丽的交涉：诏书、表文与礼仪",
        date: "2026-12-01",
        tags: ["唐与高句丽", "外交", "史料"],
        summary: "唐丽之间近三十年的诏书与表文往来，表面是礼仪交锋，实质是两种秩序观的碰撞。唐以汉四郡旧地为据，要求拆长城、还人口、停攻新罗；高句丽以数百年据有为据，只在谢罪与献方物上周旋。册封、质子与和亲的缺席，说明唐把它放在郡县旧地而非对等外国的位置，交涉因此没有妥协空间。",
        content: `
            <p>唐与高句丽之间并非一开始就兵戎相见。从武德年间到贞观末年，双方维持了将近三十年的使节往来，诏书、表文、朝贡与册封构成一套固定的交涉语言。战争爆发之前，这套语言已经使用了很久，也已经失效了很久。要理解战争，先要理解这套语言为什么承载不了双方的分歧，以及双方各自想用它换取什么。</p>
            <p>武德七年（624），唐高祖册封高句丽王建武为辽东郡王、高句丽王，同时册封百济王扶余璋为带方郡王、新罗王金真平为乐浪郡王。三个王号都取自汉四郡的旧名：辽东、带方、乐浪。这不是随手挑的吉利字眼，而是把三国放回一套郡县记忆里，暗示它们的土地曾经是中原王朝的郡县。高句丽接受册封，却从不接受这层暗示。唐初天下未定，高祖对高句丽以安抚为主，甚至去书劝它与百济、新罗和解。</p>
            <p>高句丽在国内自称太王，王号、年号与官僚体系都按独立政权的规格设置。对唐的表文用藩臣的辞令，内容却坚持自己对辽东与汉江流域的利益。这种表里不一并非欺骗，而是两种秩序观并存的结果：高句丽需要唐的册封来获得贸易与合法性，却不愿因此承认自己是唐的郡县。</p>
            <p>贞观五年（631）发生了一件小事，后果却不小。唐遣长孙师到辽东收瘗隋末阵亡将士的骸骨，毁掉高句丽所立的京观。这是礼仪性的动作，在高句丽看来却是示威。同年，高句丽开始修筑辽东长城，东北自扶余城，西南至海，绵延千余里。此后双方的表文照旧往来，边境的工事却一天比一天厚。</p>
            <p>贞观十六年（642），渊盖苏文杀荣留王，立宝藏王，专擅国政。唐太宗先遣使责问，继而以弑君与侵新罗为罪名，于贞观十八年（644）下诏亲征。诏书列举的罪状里，弑君排在前面，侵新罗排在后面，但真正触动唐的是新罗的求援与高句丽对唐调解的拒绝。礼法语言包裹的是具体的利益冲突。</p>
            <p>高句丽的回应方式很值得注意。它不正面驳斥唐的礼法指控，而是在谢罪与献方物上周旋；645年唐军班师之后，它照旧遣使入唐，表文恭顺，实质要求一条不让。表文里的顺从与边境上的备战并行不悖。唐要的是实质性让步，高句丽给的是礼仪性姿态，双方都清楚对方在做什么。</p>
            <p>贞观十九年（645），唐军攻下辽东城、白岩城，却在安市城下受阻。城主坚守，唐军筑土山、造冲车，昼夜攻打数月不下。辽左早寒，草枯水冻，粮运不继，太宗只得班师。这场亲征没有达到目的，却让唐看清了高句丽山城防御的韧性，也为高宗时期改用长期消耗的战法埋下伏笔。</p>
            <p>唐的要求后来具体化为三条：拆毁辽东长城，归还在隋末战争中被俘的中国人，停止对新罗的进攻。这三条高句丽都无法接受。长城是其防御体系的骨干，人口是其劳动力与兵源，新罗是它在半岛上必须压制的对手。要求本身没有给对方留下谈判空间。</p>
            <p>唐与高句丽之间没有和亲，质子宿卫也不成规模。这与唐和突厥、吐谷浑、吐蕃的关系形成对照。和亲意味着承认对方是可以婚配的对等政权，质子则意味着对方是可以信任的藩属。唐对高句丽两者都不用，说明它在制度上把高句丽放在郡县旧地的位置，而不是对等的外国。高句丽也从不主动求亲，它要的是唐承认现状。</p>
            <p>双方争执的核心是辽东旧地。唐的依据是汉魏晋的辽东、玄菟、乐浪诸郡，以及隋炀帝三次征辽留下的政治遗产；高句丽的依据是数百年来的实际据有，以及朱蒙自扶余南奔的起源叙事所包含的对扶余故地的权利。两种历史叙事都自成体系，无法互相说服。交涉越往后，越变成各说各话：唐谈的是旧疆，高句丽谈的是现居。唐的君臣在诏书里反复强调辽东旧地，高句丽的表文则只称本国境土，措辞的差异本身就是立场。</p>
            <p>册封的实际效力也有限。和平时期，册封是对现状的确认，附带贸易与使节往来的便利；冲突时期，册封又成了唐宣战的依据，因为受册者理论上负有藩臣义务。高句丽接受前者，拒绝后者。同一套制度，双方各取所需，分歧迟早要摊开。</p>
            <p>高宗时期，交涉与军事交替使用。唐先于660年灭百济，切断高句丽与倭的联系；666年渊盖苏文死，诸子内讧，泉男生降唐，唐由此获得熟悉高句丽内情与地形的向导。交涉到这时已不再重要，因为唐找到了从内部瓦解对手的机会。668年平壤陷落，宝藏王被俘，二十余年的文书往来以这种方式收场。</p>
            <p>史料立场影响我们对交涉的复原。两《唐书》的记载本于唐的国史与实录，倾向于把唐的军事行动写成吊民伐罪；《资治通鉴》采摭实录与杂史，编年清楚，却保留了司马光的秩序关切；《三国史记》以高句丽为本位，对同一事件的起因与责任有不同安排。同一份表文，在不同史书里可能被节录成完全不同的语气。</p>
            <p>交涉的失败不在于辞令不够恭敬，而在于礼仪秩序要求单方面的臣服，实质利益却要求双方妥协。唐要的是一个可预期的东部秩序，高句丽要的是生存空间与半岛优势。这两样东西在当时的条件下无法同时满足，战争于是成了唯一的出路。二十余年的使节往来，最终没能换来一纸可以执行的约定。</p>
        `,
    },
    {
        id: "khitan-goguryeo",
        title: "契丹与高句丽：草原与半岛之间",
        date: "2026-12-02",
        tags: ["唐与高句丽", "契丹", "北方民族"],
        summary: "契丹夹在突厥、高句丽与唐之间，羁縻与朝贡都只是权宜，依附强者才是常态。696年营州之乱因赵文翙的苛待与饥荒而起，李尽忠、孙万荣据营州称汗，唐军两败，最终靠奚人与突厥默啜的夹击才平定。乱后营州失守、靺鞨东走建渤海，东北人群重组，契丹终成另一个秩序中心。唐的东北秩序也从此改观。",
        content: `
            <p>契丹在隋唐之际并不是一支统一的草原力量。它活动于西拉木伦河与老哈河流域，南接营州，东邻高句丽，西面与奚、室韦相接，北面则受突厥的压制。这样的位置决定了它很难长期只归属一方，摆动才是常态。</p>
            <p>唐初契丹以大贺氏八部为核心。贞观二年（628），首领摩会率部来降；贞观二十二年（648），窟哥率众内属，唐置松漠都督府，以窟哥为都督，赐姓李氏。羁縻统治的实际内容并不深：首领世袭，唐派长史参佐，契丹内部事务仍由部落自理，对突厥的贡奉也没有断。唐要的是辽西通道的安全，契丹要的是册封带来的互市与赏赐。</p>
            <p>契丹的内部结构也决定了它的对外选择。八部各有大人，平时分散游牧，遇战事才推举首领；联盟的强弱取决于能否从外部获得赏赐与战利品。唐的册封、突厥的征调、高句丽的拉拢，争取的都是这些部落大人的向背，而不是一个统一的契丹国。正因如此，契丹的归附与反叛往往同时发生在不同部落之间。</p>
            <p>高句丽与契丹的关系比一般人想象的更早。高句丽强盛时势力西达辽西，契丹一些部落曾在它的影响之下，《三国史记》高句丽本纪中也留有与契丹相关的边事记载。双方是邻国，有时是宗主与属部，有时是劫掠的对手，关系随力量对比而变化，很难用固定的同盟或敌对来概括。</p>
            <p>真正改变格局的是突厥。永淳元年（682）以后，后突厥复兴，默啜可汗一度控制漠北与契丹，唐的松漠都督府名存实亡。契丹在唐与突厥之间来回，谁是强者就依附谁。唐也习惯了这种摇摆，只要契丹不联合高句丽切断辽西通道，就仍然给它册封与互市。</p>
            <p>万岁通天元年（696），营州都督赵文翙刚愎自用，契丹饥荒，他不肯赈济，又把契丹酋长当作奴仆使唤。松漠都督李尽忠与归诚州刺史孙万荣起兵，杀赵文翙，占据营州。李尽忠自称无上可汗，这是契丹第一次公开称汗。营州是唐控制东北的枢纽，失守意味着唐在辽西的整个体系出现了缺口。</p>
            <p>武周最初低估了对手。曹仁师、张玄遇等二十八将率军进讨，在黄獐谷中伏，全军覆没，张玄遇被俘。次年王孝杰、苏宏晖率十七万兵再战，于东硖石谷大败，王孝杰坠崖而死。唐军两次惨败，说明契丹在本地作战时的机动优势，也说明武周在东北的兵力与后勤都不足以速胜。</p>
            <p>奚人在其中的角色不可忽略。奚与契丹语言习俗相近，居饶乐都督府故地，与契丹时合时分。营州之乱初起时奚人附从契丹，后来倒向唐，从侧翼夹击，直接导致孙万荣的溃败。唐在辽西的一贯做法，是让契丹与奚互相牵制；任何一方坐大，都意味着这套平衡失效。</p>
            <p>起兵的第三年就失败了，原因不在唐军一路。李尽忠病死，孙万荣先胜后败；奚人倒向唐，从侧翼袭击契丹；突厥默啜应武周之请，突袭契丹后方，掠走人口与畜产，并因此向武周索得六州降户、谷种与铁器。三面受敌之下，孙万荣为其奴所杀。契丹的这次起事，败给了它一贯依赖的地缘位置。</p>
            <p>营州之乱的连锁反应比契丹本身的成败更重要。营州陷落，唐在东北的据点动摇；靺鞨首领乞四比羽与乞乞仲象率众东走，大祚荣在天门岭击败追兵，于圣历元年（698）建立渤海。高句丽遗民也卷入这股流动，东北的人群结构因此重新排列。一场契丹的饥荒，最后改写了三个政权的边界。</p>
            <p>营州之乱后，契丹并未从此与唐决裂。697年以后，残余部众重新归附，唐恢复松漠都督府的建制；开元年间契丹再次反叛，唐与契丹在辽西反复交战。安禄山任范阳、平卢节度使时，屡次侵掠契丹以邀功，双方的关系在羁縻与劫掠之间来回。所谓叛服无常，其实是这种结构下的常态。</p>
            <p>契丹与高句丽遗民的关系，在灭亡前后都很密切。高句丽故地与契丹的活动区域相邻，营州一带长期杂居着契丹、奚、靺鞨与高句丽人。唐迁走高句丽上层之后，留居者中有不少被契丹与靺鞨吸纳。后来的营州杂胡，就是这种杂居的产物，其成分包括契丹、奚、室韦与高句丽遗民。</p>
            <p>安禄山的例子可以说明这种人群重组的后果。安禄山本人出自营州杂胡，其军中多有契丹、奚与高句丽遗民的后裔。营州之乱后唐在东北的控制松弛，边军地方化，这些人口成为边镇兵力的来源，也成为安史之乱的社会基础之一。东北的人口流动，最终以另一种方式回到了唐的政治中心。此后契丹的贵族也学会了用册封与和亲与中原打交道，这套语言他们并不陌生。</p>
            <p>长时段看，契丹从唐的羁縻对象变成了另一个秩序中心。916年耶律阿保机建国，926年灭渤海，十世纪末以后辽与高丽多次交战，1019年龟州之战后双方关系才稳定下来。当年在唐、突厥、高句丽之间摆动的部落，最终把半岛北部纳入自己的册封体系。历史没有让契丹停留在配角的位置。</p>
            <p>把契丹写成高句丽的盟友或唐的叛臣，都简化了它的处境。它的选择取决于三方力量对比与眼前的生计，而不是固定的忠诚。营州之乱的意义，也不在于契丹能否立国，而在于它暴露了唐的东北秩序在羁縻与失控之间的脆弱。</p>
        `,
    },
    {
        id: "goguryeo-migrations",
        title: "高句丽人口的流散：入唐、入突厥、入渤海",
        date: "2026-12-03",
        tags: ["唐与高句丽", "遗民", "人口史"],
        summary: "668年高句丽灭亡后，唐分层处置其人口：王族与富户迁入江淮、山南，降将编入唐军，贫弱者留守安东。泉男生、高仙芝家族在唐获得新位置，部分遗民北投突厥、东入渤海，留居者渐入新罗。流散持续数十年，故地换了主人，东北的人群结构也由此重塑。唐的羁縻安排与遗民的再流动互为因果。",
        content: `
            <p>668年高句丽灭亡，如何处置故地的人口，是唐必须立即回答的问题。唐的答案不是单一的屠杀或迁徙，而是分层安置：王族与贵族迁入内地，平民部分留居，降将编入唐军，边缘人口则流向突厥与靺鞨。理解这个分层，才能理解灭亡之后东北的人口格局。</p>
            <p>行政安排先于人口安排。唐分高句丽故地为九都督府、四十二州、一百县，置安东都护府于平壤，以薛仁贵为检校安东都护，统兵二万。这是羁縻式的间接统治，名义上保留地方首领，实际上由唐军支撑。《旧唐书》称高句丽旧有一百七十六城、六十九万七千户，这个数字未必精确，但可看出其人口规模。</p>
            <p>灭亡的过程本身也影响人口的去向。666年渊盖苏文死后，诸子内讧，泉男生据国内城降唐；唐以李勣为辽东道行军大总管，水陆并进，668年围攻平壤月余，宝藏王出降，渊男建被俘。战事拖了一年多，平壤一带的人口在围城与饥馑中损耗不小，这使唐接收到的并不是一个完整的社会。</p>
            <p>大规模迁徙发生在总章二年（669）。据《资治通鉴》，唐迁高句丽民三万八千二百户于江淮以南及山南、京西诸州空旷之地，留其贫弱者使守安东。户口数字出自册籍，可能有隐漏，但量级可以相信。迁徙的目的很清楚：把贵族与富户迁离故地，削除复国的社会基础，同时以移民填补唐内地因战乱而空虚的州县。</p>
            <p>唐还征用高句丽降卒充实边军。安东都护府统兵二万，其中相当一部分是就地征发的降人；此后唐在西北与吐蕃、在辽西与契丹作战，也调用过蕃兵。对唐而言，遗民既是需要防范的对象，也是可以使用的兵力资源，这两重定位一直并存。</p>
            <p>迁民的生活并不好过。江淮、山南的空旷之地并非熟田，外来户要重新开垦；高句丽人的语言、习俗与当地不同，融入需要几代人。唐代文献里偶尔还能看到高句丽后裔的踪迹，墓志中也出现过自称辽东人或高丽人的家族，但到唐中后期，他们作为群体已经很难辨认。</p>
            <p>入唐的精英走的是另一条路。泉男生降唐，官至右卫大将军，其子泉献诚在唐为将；高仙芝的父亲高舍鸡本是高句丽人，从军河西，累官至四镇十将，高仙芝随父至安西，后来官至安西四镇节度使。这些家族在唐的军事体系里获得了新的位置，其子弟也按唐的制度受教育、任官。唐的官僚体系对这些降人家族并不排斥，军功与语言能力是他们上升的主要资本。</p>
            <p>王族的处置最能说明唐的顾虑。仪凤二年（677），唐授高藏辽东州都督、朝鲜王，让他回到安东统领高句丽余众；不久高藏因谋叛被召还，流配邛州。唐需要一个人来安抚旧众，又不放心这个人真有号召力。这种矛盾贯穿了整个安置政策：既要用旧主，又要防止旧主成为复国的旗帜。</p>
            <p>投突厥是另一条去向。默啜可汗强盛时，部分高句丽遗民北走；突厥也曾向唐索要降户，唐一度遣还。这条线索的记载零散，规模难以估计，但可以确定的是，突厥把高句丽遗民当作人口资源与对唐施压的筹码。北走的路线大致经辽西或漠南，与契丹、奚的流动方向交错。</p>
            <p>入渤海的方向更为重要。大祚荣建国时，其众以粟末靺鞨为主，兼有高句丽遗民，《旧唐书》说高丽余烬稍稍归之。渤海的地方制度、城址形制与高句丽有继承关系，但渤海的主体是靺鞨，不能把两者等同。高句丽遗民在渤海是重要的组成部分，不是全部；把渤海说成高句丽的复国，是后世的附会。</p>
            <p>营州一带是另一个汇聚点。这里原本就居住着不少高句丽人，灭亡前后又有降户被安置到这一带，与契丹、奚、靺鞨杂居；696年营州之乱爆发，这批人又被卷入东走的队伍，随大祚荣进入渤海。营州因此既是唐的安置地，也是遗民再次流动的中转站。</p>
            <p>留居故地者的命运随唐的进退而变。安东都护府在仪凤年间内迁，唐在大同江以南的控制收缩，新罗逐渐占据汉江流域与半岛中部；留居的高句丽人有的入新罗，有的成为渤海、契丹与唐边军的人口来源。故地并未空荒，只是换了主人。新罗的户口与地方制度，也因此吸收了高句丽旧地的成分。</p>
            <p>研究这段历史要区分确证与推测。户口数字、迁徙地点、降将官职有明确记载；投突厥、入靺鞨的规模则多为零散线索，不能量化。高仙芝家族的族属有记载，但其母系与更早的世系并不清楚，使用时不宜过度引申。墓志材料能补充正史，但墓志的郡望与族属书写本身也有攀附的成分。</p>
            <p>渤海对高句丽的继承是有限的。渤海沿用了一些高句丽的城址与地方建置，王室也与高句丽遗民通婚，但其统治核心是靺鞨诸部，官方记忆另有一套。把渤海视为高句丽的延续，会掩盖靺鞨在此过程中的主导作用；反过来完全否认联系，也不符合城址与制度的证据。</p>
            <p>高句丽人口的流散不是一次性的，而是持续数十年的过程。它把半岛北部的人口带向唐、突厥、渤海三个方向，改变了东北的人群结构，也让高句丽作为政治实体消失之后，其文化因素在渤海与唐的边地继续存在。流散的方向、规模与速度，取决于唐的军事进退与突厥、契丹、靺鞨的兴衰，而不是遗民自己的选择。</p>
        `,
    },
    {
        id: "tang-east-asia-order",
        title: "唐初的东亚秩序：礼仪、册封与利益",
        date: "2026-12-04",
        tags: ["唐与高句丽", "国际关系", "制度"],
        summary: "唐初东亚秩序以册封、羁縻府州、质子宿卫与朝贡为骨架，礼仪与利益在其中交错。高句丽、百济、新罗、倭各有用法，唐的调停与征伐受实力、后勤与季节约束。把它看成单向支配会失掉真相：这是一套可谈判的制度语言，稳定取决于利益交换，礼仪只是外壳。它的边界始终由军力与后勤画定。",
        content: `
            <p>唐初的东亚秩序常被概括为册封与朝贡体系。这个概括不算错，但容易把它想象成一台单向运转的支配机器。实际运作中，册封是双方都需要的一套制度语言，唐用它组织秩序，邻国用它换取利益。谁更需要谁，往往因时因地而不同。</p>
            <p>册封的内容很具体：授予郡王、都督、刺史的官爵，派遣持节册命使，颁给印绶，附带回赐。受册者得到三样东西：对内的合法性，对外的保护承诺，以及使节往来带来的贸易渠道。唐得到的则是边境安定、名义上的臣服与可动员的兵力。册封的文书与仪式都要存档，成为日后交涉的依据。</p>
            <p>这套制度并非唐的独创。册封与朝贡的做法在汉魏已经存在，唐把它系统化，配上羁縻府州与都护府，形成可以复制的模板。模板的核心不是礼仪本身，而是把军事保护、贸易许可与政治名分打包在一起，让对方在一次册封里同时得到几样东西。</p>
            <p>羁縻府州是这套秩序的骨架。松漠都督府安置契丹，饶乐都督府安置奚，安东都护府统辖高句丽故地。首领世袭，不输赋税，唐派长史、司马参佐。这是一种低成本的控制：不改变地方社会，只在其上加一层名义与联络。它的弱点也在这里：一旦唐的军力衰退，这层名义就薄得像纸。</p>
            <p>质子宿卫是另一根支柱。新罗的金春秋与金法敏都曾入唐，百济的扶余隆也在唐宿卫，高句丽则较少。质子既是人质，也是学习唐制、结交权贵的机会。不少人回国后成为推行唐制的核心人物，金春秋回国后推动新罗的改革与扩张，就是最明显的例子。这是册封体系最实在的长期效果。</p>
            <p>朝贡的经济面常被忽略。朝贡是官方贸易的形式，回赐的价值往往高于贡物；马匹、皮毛、药材换回丝帛、瓷器与书籍。使团的人数、路线、停留时间都有规定，违反规定就会引起纠纷。礼仪与生意在同一套程序里完成，贡物的清单同时也是市场的清单。</p>
            <p>秩序的维系靠的是频繁的使节往返。唐每年要接待数十个使团，鸿胪寺负责接待与翻译，礼部主客司掌管蕃国朝贡，使者的名籍、贡物与行程都要登记。这套行政机器成本不低，唐之所以愿意承担，是因为它用较少的驻军换来了边境的可预期性。</p>
            <p>天可汗是这套秩序的政治称号。贞观四年（630）灭东突厥后，四夷君长请上尊号，唐太宗接受。它不是正式制度，效力取决于唐的军事实力；实力衰退时，这个称号很快就被遗忘。把它当成制度性的霸权，会高估它的约束力，也会低估周边政权的自主性。</p>
            <p>与突厥的关系是另一面镜子。唐初曾向突厥称臣纳贡，贞观四年灭东突厥后才转为册封者；后突厥复兴以后，唐又不得不以和亲、互市与岁赐换取边境安宁。同一套秩序语言，在强弱易位时会呈现完全不同的面貌，使用者也会随之改变说法。</p>
            <p>各国在这套秩序里的位置不同。高句丽是辽东郡王，自视海东大国，接受册封但不接受调停；百济是带方郡王，联倭抗新罗；新罗是乐浪郡王，借唐之力扩张，并在660年以后迅速兼并百济故地；倭国未受册封，却持续遣使，白江口之战后转而整顿内政。同一套册封，四家各有用法，有的用它求保护，有的用它求时间。</p>
            <p>百济故地的处置更能说明秩序的边界。660年唐灭百济，设熊津都督府，以扶余隆为都督；新罗则以助战之功兼并百济故地，唐罗之间由盟友转为对手。676年前后，唐军在新罗的攻势下后撤，安东都护府内迁。秩序的边界，最终由军力与后勤画定。</p>
            <p>礼仪与利益的错位是这套秩序的常态。礼仪要求藩属接受调停、停止攻伐；利益却要求边境安定、贸易畅通。当高句丽拒绝停止攻新罗，唐面临的选择是降低礼仪要求还是动用武力。唐选择了后者，因为降低要求等于承认秩序失效。645年亲征的决策，就是在这套逻辑里做出来的。调停失败之后，唐的诏书往往先回顾旧恩，再宣告征讨，修辞的次序也有讲究。</p>
            <p>因此不能把它简化为中华中心主义的单向支配。册封往往应对方的请求而发，对方也利用唐的册封对付邻国；唐的军事行动受后勤、季节与国内政治的约束，不能随心所欲。辽左早寒，草枯水冻，士马难以久留，太宗在安市城下班师，原因之一就是补给线太长。</p>
            <p>东亚同时存在多个秩序中心。突厥有自己的可汗体系，吐蕃有自己的赞普秩序，高句丽也有以大王为中心的天下想象。唐的秩序是其中最有力量的一环，但不是唯一的一环。把东亚史写成唐的单方面扩张，会漏掉这些平行的结构，也会看不清小政权在大国之间的腾挪空间。</p>
            <p>倭国的位置也值得单独一提。唐初倭国未入册封体系，却持续派遣使团，学习律令与佛法；663年白江口之战后，倭国转而整顿内政，完善律令体制，701年再派遣唐使。它对唐秩序的态度是学习而不臣服，这与半岛三国的处境不同。</p>
            <p>唐初的东亚秩序是一套可谈判的制度语言，而不是一台单向的支配机器。它的稳定取决于实力对比与利益交换，礼仪只是外壳。当外壳与利益脱节，战争就会取代交涉，高句丽问题正是最清楚的例子。礼仪一旦失去力量的支撑，就只剩下文字。</p>
        `,
    },
    {
        id: "historiography-goguryeo-modern",
        title: "近代史学中的高句丽：民族叙事与考古",
        date: "2026-12-05",
        tags: ["唐与高句丽", "史学史", "考古"],
        summary: "高句丽研究有民族叙事与考古实证两条线索。好太王碑1877年发现于集安，把研究从文献转述推向原始记录；此后日本满鲜史、朝韩的民族叙事与中国边疆史观各自展开，2002年东北工程引发争议。考古提供年代、形制与交流的证据，归属却是政治与历史叙事的建构。把两者分开，才谈得上真正的讨论。",
        content: `
            <p>高句丽研究在二十世纪形成两条线索：一条是民族主义的叙事，关心起源、领土与归属；一条是考古学的实证，关心城址、墓葬、碑刻与器物的年代和形制。两条线索常常纠缠在一起，很难完全分开。看清这一点，才能理解为什么同一批材料会得出不同的结论。</p>
            <p>近代研究的起点是好太王碑。此碑于1877年在集安被发现，碑文一千七百余字，记广开土王的功业与守墓烟户。早期拓本流传不一，释读与辨伪的争论持续了很久。一方石碑把高句丽史从文献的转述变成了同时代的原始记录，这是方法上的转折。此后的研究，都要先面对碑文的残缺与异读。</p>
            <p>碑文的流出也影响了研究格局。十九世纪末，日本军方与学界相继派人到集安拓碑，拓本流入东京与京都，引发最早的公开讨论；中国学者的调查稍晚，二十世纪上半叶的集安踏查留下了城址与墓葬的早期记录。资料流向哪里，解释权就倾向哪里，这是早期高句丽研究的一个特点。</p>
            <p>日本殖民时期的满鲜史研究，带有明显的扩张意图，调查机构与军政部门关系密切。但同一批调查也留下了严格的城址测量、墓葬编号与拓本资料，至今仍可使用。评价这段学术史，需要把动机与成果分开看，既不能洗白，也不能一概抹掉。学术史的责任，是把可用的材料与不可取的立场分别交代清楚。</p>
            <p>战后朝鲜把高句丽放在民族古代史的核心位置。平壤自长寿王十五年（427）迁都以后一直是高句丽的后期都城，城址、宫殿与王陵都在今平壤一带，这为朝鲜的叙事提供了实物依据。其叙述强调高句丽的独立与反侵略，把唐的征伐写成外来入侵。考古工作也围绕平壤与大同江流域展开。</p>
            <p>朝鲜的叙事还有一层更早的依托。近代朝鲜民族史学把檀君朝鲜、扶余、高句丽串成一条连续的谱系，以此论证民族的古老与独立；高句丽在这条谱系中处于承上启下的位置。这套谱系是近代建构的产物，但它对公众记忆的影响，远比具体的考证更深。</p>
            <p>韩国的叙事以三国时代为框架，高句丽与百济、新罗并列，同属古代国家。广开土王在教科书与公众记忆中是开疆拓土的君主，好太王碑因此具有象征意义。这种叙事与朝鲜的叙事同源，但在国家定位与历史连续性上有差别，对高句丽与渤海关系的处理也不相同。</p>
            <p>中国学界把高句丽视为东北古代的少数民族政权，强调其扶余族源、与中原王朝的册封关系，以及城址与墓葬主要分布于今中国境内。这套叙述把高句丽纳入中国历史的边疆脉络，与朝鲜半岛的叙事形成竞争。争论的焦点，往往不在事实层面，而在归属的标准。</p>
            <p>中国的边疆史研究有更长的传统。清代学者已注意到东北的古城与碑刻，民国时期的中日学者在集安、桓仁做过调查；1950年代以后，文物部门对国内城、丸都山城与壁画墓进行了系统清理。这条线索强调实地踏查与器物比对，与民族叙事保持了一定距离，但其问题意识仍受边疆治理的影响。</p>
            <p>东北工程是这场竞争的集中表现。它于2002年启动，全称是东北边疆历史与现状系列研究工程，由学术机构组织，涉及高句丽、渤海等课题。韩国学界对此提出强烈抗议，双方的分歧从学术讨论扩展到公共舆论，甚至影响到双边关系。这里只陈述背景，不判断谁对谁错。</p>
            <p>争议也推动了研究。为了回应质疑，各国学者更系统地整理城址、墓葬与碑刻，出版报告与图录；好太王碑的拓本比对、壁画墓的分期、山城的防御结构，都在争论中获得推进。政治的压力并不只带来扭曲，也带来了资料的公开与方法的细化。</p>
            <p>考古的进展是实在的。集安的国内城、丸都山城、太王陵、将军坟与壁画墓群，桓仁的五女山城，平壤的安鹤宫、大城山城与东明王陵，构成了高句丽城市与墓葬的序列；2004年集安与桓仁的高句丽王城、王陵及贵族墓葬列入世界遗产。城址的防御体系、壁画的主题与墓制的变化，都可以作类型学的比较。</p>
            <p>争议集中在解释而非材料。好太王碑中辛卯年条的读法、倭军介入半岛南部的性质、广开土王巡狩所至的范围，都因碑文残损与释读差异而有不同结论。同一块碑可以支撑不同的叙事，这说明材料本身不自动给出归属。碑文是证据，读法却是判断。</p>
            <p>如今的讨论开始转向更具体的题目：高句丽的国家形态是中央集权还是贵族联合，五部与地方城邑的关系如何，佛教与王权结合到什么程度，墓葬壁画中的外来因素如何分辨。这些问题不直接回答归属，却能让人看清高句丽作为一个政权的实际运作，也把争论从口号拉回材料。</p>
            <p>还有一个常被混淆的概念：高句丽与王氏高丽不是一回事。高句丽存在于公元前一世纪至668年，王氏高丽建于918年，二者族源与政权都不同。朝鲜王朝以高丽继承高句丽之名，后世的民族叙事又把这层名义当成史实，公众讨论中的许多误解由此而来。把两个政权混为一谈，任何讨论都无法进行。</p>
            <p>考古材料不会自动解决归属问题。它提供年代、形制与交流的证据，归属则是政治与历史叙事的建构。学术能做的，是把两者分开：先确定发现了什么，再讨论这些发现能被谁的故事使用。这个次序一旦颠倒，研究就变成了表态。</p>
        `,
    },
    {
        id: "campaign-season-climate",
        title: "出征的季节：唐丽战争与气候条件",
        date: "2026-12-15",
        tags: ["唐与高句丽", "气候", "军事"],
        summary: "唐丽战争的作战窗口，由辽河封冻、河北山东的农时与渤海风信共同划定。本文从贞观十九年班师诏的「辽左早寒，草枯水冻」入手，考察气候如何压缩远征时间、牵动海运与粮运，并说明气候只是约束条件，胜负仍取决于攻坚与政治。文章也提醒，气候重建的尺度是区域与十年，与编年记载中的某一天并不重合。",
        content: `
            <p>贞观十九年（645）九月，唐太宗在安市城下已停了六十余日，最终下诏班师。史书把班师的理由记得很短：</p>
            <blockquote>辽左早寒，草枯水冻，士马难久留，且粮食将尽。</blockquote>
            <p>这句话常被当作唐军受挫的解释，其实更像一份时间表。四个短句各有分量：早寒是天气，草枯水冻是给养，士马难留是体力与士气，粮食将尽是后勤。四者同时到限，军队就待不住了，撤退于是成了唯一可行的选择；而窗口有多长，也就由这四件事共同划定。辽河流域的物候与中原不同。九月已有霜，十月河冰初合，草木枯黄之后，战马缺少可食的青草，辎重车队在泥冻交替的路面上损耗陡增。对一支以骑兵与府兵步卒为主、依赖就地补给的大军来说，冬季不是能不能打的问题，而是能不能待的问题。</p>
            <p>因此唐军的出兵节奏被压得很紧。贞观十八年秋冬，唐廷已开始造船、征粮、调兵；十九年春太宗自洛阳北上，四月渡辽水，五月克辽东城，六月进围安市，九月班师。从渡河到撤退，前后不足五个月。这个窗口并非唐人独创，隋大业年间三次征辽也大致遵循同一节奏，只是隋军规模更大、后勤更脆弱。</p>
            <p>春耕与征发的冲突是另一重约束。造船、运粮、养马都要民力，而征发期恰好与春耕、夏耘重叠。河北、山东是主要的兵源与粮运区，民夫一旦离田，当年的收成就要打折扣；收成打折，下一年的军粮就紧张。唐廷并非不知道这一点，班师理由里粮食将尽四字，既是前线实况，也与后方的转运能力有关。贞观十八年唐廷在洪、饶、江三州造船数百艘以运军粮，船厂设在江南，木材与工匠的征调又反过来占用农时，粮未至而民已疲。</p>
            <p>海运看起来绕开了陆路的拥堵。张亮的舟师自莱州渡海，先取辽东半岛南端的卑沙城，再沿海岸北上。海路省去辽西走廊的转运，但帆船依赖风信：渤海海峡的风向随季节转换，顺风数日可至，逆风则旬月滞留，风暴还可能整船覆没。海运因此不是稳定的替代方案，而是与陆路并行的、受天气支配的第二条通道。</p>
            <p>更麻烦的是，海运与陆军的会合很难精确。舟师抵达的时间取决于风，陆军的进度取决于攻城，两者一旦错位，海上运来的粮食就要在港口堆积，或者干脆随船折返。史书对这类协调失败记录很少，因为编年体只记某日克某城，不记某批粮船在何处等了多久。</p>
            <p>冻馁与疫病是窗口关闭后的直接后果。班师途中，士卒在雨雪里行走，马匹大批倒毙，伤病者掉队。正史对这些损耗有零星的数字，但数字多经史臣整齐化，不能直接当作统计。可以确认的是，唐太宗回朝后对辽东战殁者做了祭奠与抚恤，这说明损失已经大到需要公开处理的程度。</p>
            <p>这里需要一种机制上的解释，而不只是天冷所以撤军。唐军的补给线从幽州、营州向辽东延伸，粮秣靠人力与畜力转运，转运效率随距离递减；攻城又必须集中兵力于城下，无法分兵护粮。于是时间越长，前线越依赖后方，后方越依赖农时，农时又越不能拖。气候只是把这个链条的末端提前切断。</p>
            <p>把气候当作原因则过头了。贞观十九年的真正问题包括：安市城久攻不下，土山工程反复，前线指挥意见不一，以及高句丽采取坚壁清野、避免野战的策略。若这些环节顺利，唐军本可在九月前结束战役；若这些环节失败，即使天气温和，大军也无法在辽东过冬。气候是约束条件，不是决定因素。</p>
            <p>史料本身也有层次。辽左早寒是当时人的体感与政治语言，班师诏把它写成天时不利，既属实情，也为决策留了体面。编年史家照抄诏书，后世读者便容易把气候当成唯一解释。至于早寒究竟比常年早多少，史书没有温度记录，无法量化。</p>
            <p>现代的气候重建可以提供背景，但不能与史书简单对应。树轮、冰芯、湖沼沉积给出的是一年年均温或季风强度的曲线，尺度是区域与十年；史书给出的是一次战役里的某一天。两者之间隔着一层无法消除的不确定性，把某次班师精确归因于某年气候异常，方法上并不成立。</p>
            <p>贞观二十一年、二十二年的偏师骚扰也受同一窗口支配。唐军不再动员主力，而是以水陆小股部队反复攻其城栅、虏其人民，得手即退；这种打法与其说是战略，不如说是把作战压缩在气候允许的几个月里，用低成本维持压力。高句丽则利用唐军撤退后的季节修城积谷，双方都在跟时间表打交道。</p>
            <p>总章元年（668）的灭国之战提供了一个对照。唐军这次也在春夏进军，也在秋冬前结束，但胜负不同。原因不在天气变好，而在高句丽内部：渊盖苏文死后诸子争权，泉男生降唐，唐军得以自内部瓦解防御。窗口是常量，政治条件是变量。</p>
            <p>所以，关于季节的这个题目，答案并不浪漫。唐丽战争的时间表由三样东西共同划定：辽河的封冻与解冻，河北山东的农时，渤海的风信。三者叠加，把大规模远征压缩成每年几个月的窗口。谁能在窗口内解决战斗，谁就掌握主动；谁把战争拖到窗口之外，谁就得先撤。</p>
            <p>在这个意义上，气候史能做的不是替战役找借口，而是把为什么是这个时候问清楚。唐太宗的班师诏留下的，是一份关于后勤、农时与季节的坦白；它没有说的是，那些本可以在窗口内解决的问题，为什么没有解决。</p>
        `,
    },
    {
        id: "goguryeo-five-departments",
        title: "高句丽的五部与地方统治",
        date: "2026-12-14",
        tags: ["高句丽", "制度", "五部"],
        summary: "五部常被画成五个整齐的方位行政区，实际更像王畿内以族属与居地为基础的贵族集团。本文梳理五部名称、褥萨等官号与城村关系，讨论王权与贵族的张力，并对照唐的羁縻府州与安东都护府，指出唐的府州只是授号，未能替换地方权力，细节仍有讨论，读材料要分清名称、官号与运作三层。",
        content: `
            <p>高句丽的五部常被描述成一套整齐的行政区划：内部、东部、南部、西部、北部，各有方位、族属与首领。但把五部当作五个省来理解，会掩盖它实际运作的方式。五部更像是王畿之内以族属与居地为基础的贵族集团，它们的名字在不同史料里并不完全一致，方位对应也有出入。</p>
            <p>常见说法是：内部为桂娄部，即王族所在；东部为顺奴部，南部为灌奴部，西部为涓奴部，北部为绝奴部。这一组对应主要依据《三国史记》与后世整理，但《周书》《隋书》的记载并不逐条吻合，学界对哪一部在哪个方位、五部是否一开始就有，仍有讨论。稳妥的说法是：五部是王权核心区的贵族分组，而非全境统一的行政层级。</p>
            <p>五部之上是王，五部之下是城与村。高句丽的统治节点是城：山谷间筑城，城居要害，周围散布村落。城主领城，掌兵、掌粮、掌讼；村则依城而存，向城纳赋、出兵。城的大小不等，大城屯兵多，小城仅容数十户，城主之下有分管村落的人员与部曲，层层相属。这种城村结构与中原的县乡里不同，前者以军事据点为中心，后者以户籍与田土为中心。</p>
            <p>官号系统也随时代变化。较早的记载如《三国志·东夷传》列出相加、对卢、沛者、古雏加、主簿、优台丞、使者、皁衣、先人等名目，尊卑有序；《周书》《隋书》则记十二等，自大对卢、太大兄、大兄、小兄以下，至褥萨、翳属、仙人。两套名单之间有延续，也有重组，不能简单叠加成一张职官表。</p>
            <p>褥萨是其中最关键的一个。通行说法认为褥萨是地方城主之号，相当于统辖一城或数城的地方长官；处闾、可逻达则见于较晚的记载，职掌与层级仍有讨论。有学者把处闾比作酋长、可逻达比作城主，也有学者认为它们是不同时期对同类职位的异称。史料不足，任何精确的对应都要打折扣。</p>
            <p>王权与五部贵族之间存在持续的张力。《三国志》记高句丽无牢狱，有罪，诸加评议便杀之，没入妻子为奴婢，这条材料说明重罪由诸加共同议定，王不能独断。诸加即各部贵族首领。评议的范围当不止杀人；立君、战和一类大事，大概也要先取得诸加的认可，五部贵族因此在最高决策上有惯例性的发言权。五部因此不只是行政区，更是王权必须协商的对象。</p>
            <p>这种结构在王位继承上留下痕迹。高句丽的继承既有父子相继，也有兄终弟及，王后族属与母族势力常常决定结果。五部贵族拥立谁，往往取决于谁能给他们更多空间。王权强时，五部被编入官僚序列；王权弱时，五部贵族便以评议之名分割权力。</p>
            <p>与唐的羁縻府州对照，差异很清楚。唐在突厥、契丹、奚故地先后设羁縻府州，以酋长为都督、刺史，世袭其职，贡赋不入户部，本质上是把原有权力纳入唐朝的官号体系而保留其运作。高句丽的五部城结构也是类似的东西：权力在地方，官号在中枢。</p>
            <p>总章元年（668）唐灭高句丽后，据《新唐书·高丽传》以其地置九都督府、四十二州、一百县，又在平壤设安东都护府。这套建制看起来是郡县化的完成，实际运作却依赖高句丽原有的城主与酋长：唐授其首领以都督、刺史之号，让他们继续领城领民。制度的形式变了，权力的质地没有立刻变。</p>
            <p>安东都护府的迁治说明了这一点。都护府初治平壤，此后因高句丽遗民反抗与新罗北进，先迁辽东故城，再迁新城，控制范围逐步内缩。若九府四十二州真能如内地州县那样运转，都护府不必一再后撤。羁縻建制的脆弱，正在于它把地方权力留在原地，却没有能力替换它。</p>
            <p>人口处置是另一个变量。唐廷把大批高句丽人迁往内地，又留用部分首领于辽东，迁徙与留任并行，使原有的城村网络被打散。五部的贵族若离开本族居地，就失去部曲与租赋；留在原地的首领则要面对唐的官号与新罗的挤压。权力结构在两头同时松动。</p>
            <p>史料批判在这里尤其重要。《三国史记》成书于十二世纪，金富轼采中国正史与高句丽旧记，早期五部叙事带有始祖分封的建构痕迹：把后来形成的贵族分组追述为建国之初的制度，是常见的做法。《周书》《隋书》出自唐初史臣之手，多据使节见闻与旧闻，条目整齐，未必反映实态。</p>
            <p>因此，读五部材料要区分三个层次：一是名称与方位的对应，二是官号的层级与职掌，三是城村之间的实际关系。第一层史料互有出入，第二层只有名单而无职掌说明，第三层几乎全靠间接推断。把三层混为一谈，就会得到一个过于整齐的高句丽。而这种整齐，恰恰是史料整理与后世追述最容易造成的效果。</p>
            <p>比较可行的理解是：高句丽是一个以王畿五部贵族为核心、以城为节点的军事行政联合体。王通过官号与婚姻网络笼络五部，五部通过评议与拥立参与最高权力；地方以城主治民，城主之上是部，部之上是王。这套结构弹性很大，也因此难以被中央集权取代。高句丽没有留下成文的地方行政法典，我们只能从唐人的观察与后世的追述中拼出轮廓。</p>
            <p>唐灭高句丽后设置的府州，试图把这套结构翻译成唐朝的官制语言。翻译在名义上完成了，在实地上却长期停留在授号层面。五部与城村的故事，最终不是被制度消灭，而是被人口迁徙、战争与新罗的北进慢慢稀释。</p>
        `,
    },
    {
        id: "tang-allied-cavalry",
        title: "唐军中的蕃骑：突厥、契丹与奚的参战",
        date: "2026-12-13",
        tags: ["唐代", "蕃兵", "军事"],
        summary: "贞观十九年渡辽的唐军里有契丹、奚的骑兵与突厥降户，他们既是野战机动的主力，也是最易哗变的一环。本文从羁縻征发、蕃将笼络、赏赐军纪与战后安置入手，分析以夷制夷的成本与风险，指出唐廷以婚姻与官爵购买忠诚，而忠诚的价格随局势浮动，正史于部众数目、编制与补给则语焉不详。",
        content: `
            <p>贞观十九年（645）唐军渡辽水时，军中不只有府兵与募兵。契丹、奚的骑兵，突厥降户的部落兵，以及以蕃将身份统率的精锐，都出现在辽东战场上。他们不是配角：在野战与追击中，蕃骑的速度与机动往往决定战果；但在攻城与长期驻屯中，他们也是最容易出问题的一环。</p>
            <p>征发的制度基础是羁縻体制。唐在契丹、奚故地先后设松漠、饶乐都督府，在突厥降众处先后设定襄、云中都督府，以酋长为都督、刺史，世袭其职。羁縻府州不编户、不输租，代价是听候征发：朝廷有事，可调其兵马从征。府州的数目在不同时期增减不定，说明这套安排随部落的降叛而伸缩。</p>
            <p>这种征发不是无条件的。酋长从军，带的是本部人马，粮秣往往自备一部分，战利品则是重要报酬。唐廷给的赏赐包括绢帛、金银、官爵与蕃将身份；对部落而言，从征既是义务，也是获取物资与政治承认的机会。双方各有计算，不是单纯的效忠。唐廷有时以绢帛折抵粮赐，有时直接以战利品分赏，账目并不清楚，争议也由此而生。</p>
            <p>蕃将在唐军中的地位不低。契苾何力曾率部从征辽东，在攻白岩城时被槊刺伤，太宗亲自过问伤势；阿史那社尔尚衡阳长公主，是驸马都尉，同样以蕃将身份位至大将军。唐廷用婚姻、官爵与赐姓把蕃将纳入核心，这既是笼络，也是把他们的部落兵间接纳入指挥链。出征时蕃骑常被编为别部，与汉兵分营而处，既便于指挥，也便于监视。</p>
            <p>但蕃将忠诚不等于蕃兵可靠。部落兵的组织以血缘与地缘为单位，号令通过酋长传达，语言、习俗与唐军不同；赏罚标准也不一致：唐军以军法约束，部落兵以掠获为利。战事顺利时，这种差异被战利品掩盖；战事不利时，它就变成逃亡与哗变的起点。</p>
            <p>军纪问题是常态性的。蕃骑长于野战，短于守城；攻城时他们不愿承受高伤亡，掠获时又容易失控。唐军在辽东多次申明不得掳掠，但这类禁令往往在班师前后才被强调，说明执行并不容易。正史对这些细节记载零散，且多从唐将视角书写。</p>
            <p>更结构性的风险在后方。蕃兵征发越多，边境的守备越空。贞观十九年唐军主力东调，北边的薛延陀乘机南下，唐廷不得不分兵应对。这不是偶然：羁縻体制下的以夷制夷，前提是周边势力彼此牵制；一旦某部坐大，征发就变成给对手让路。唐廷后来在营州、幽州一线增置军镇，正是对这种风险的回应。</p>
            <p>逃亡与叛降的记载不多，但并非没有。高句丽方面也懂得招诱唐军中的蕃兵，以官爵与财物为饵。对部落兵来说，阵前倒戈的成本很低，因为他们的家眷与财产多在本部，不在唐境内。唐廷对此的办法是扣留人质、分散编制、以蕃将统蕃兵，效果有限；有时还要把部落迁离故地，以切断其与家眷的联系。</p>
            <p>战后安置是另一道难题。从征的部落兵返回本部，唐廷要给赏、给粮、给名义；归附的降众则要被安置在边境州府，编入羁縻或军镇。安置得好，蕃兵成为下一场战争的资源；安置得不好，就是新的边患。唐前期在突厥降户上的反复，正是这种循环。</p>
            <p>灭高句丽之后，唐廷面对的是更大规模的安置问题：高句丽遗民、靺鞨部众、新罗北进的势力，都要在辽东与朝鲜半岛北部重新排布。蕃兵在这时已不是主角，但羁縻的逻辑仍在延续：授酋长以官号，让其领本部，换取名义上的臣属。</p>
            <p>从成本角度看，以夷制夷确实便宜。府兵远征要动员自耕农，误农时、耗粮秣、动辄数年；蕃骑自带马匹与部分给养，机动性强，适合奔袭与追击，征发只需一纸诏书与一份赏格。唐前期能在西域与辽东同时用兵，靠的正是这种外包式的兵力结构。</p>
            <p>但便宜有便宜的风险。蕃兵的战斗力与政治可靠性不成正比：能打的部落往往也最有议价能力，赏赐不足就消极，赏赐过度则坐大。唐廷在蕃将身上投入婚姻与官爵，本质上是在购买忠诚，而忠诚的价格随局势浮动。</p>
            <p>指挥链上的摩擦也不可忽视。唐军以行军大总管统诸军，下辖总管、折冲，号令层层下达；部落兵则听命于自己的酋长，酋长再听命于唐将。中间多出一层，战机稍纵即逝时，这一层就可能变成延误。唐廷用蕃将统蕃兵，正是为了压缩这一层，但蕃将本身也有部落利益。</p>
            <p>史料批判需要克制。正史对蕃兵的记载集中在蕃将个人的忠勇故事，对部众数量、编制、补给、伤亡几乎没有系统记录；蕃兵十万之类的数字多为夸饰，不能当作统计。墓志与吐鲁番文书能补一些个案，但这些材料的时空范围与本役并不重合，难以还原整体。</p>
            <p>还有一层制度上的错位：蕃兵从征，名义上是助战，实际常被当作前驱与斥候，承担伤亡最高的任务；唐军主力则在关键时刻投入。这种用法在战报里被写成蕃兵奋勇，在部落记忆里未必相同。我们只有唐人的书写，听不到另一边的说法。</p>
            <p>所以，蕃骑既不是蛮族雇佣兵的浪漫想象，也不是纯粹的负担。他们是羁縻体制的产物：制度上被征发，经济上被收买，军事上被依赖，政治上被防范。唐丽战争的胜负，很大程度上取决于这套安排能否在远征的压力下维持住，而这又取决于绢帛、官爵与威慑力能否同时到位。</p>
        `,
    },
    {
        id: "liaodong-city-645",
        title: "辽东城之战：贞观十九年的第一场硬仗",
        date: "2026-12-12",
        tags: ["唐与高句丽", "攻坚", "贞观"],
        summary: "贞观十九年五月，唐军兵临辽东城下，这是整场战役的第一场硬仗。本文复原李勣与李道宗的部署、土山冲车与火攻的工序，分析风向、工期与补给如何决定成败，并与安市城对照，说明唐军攻坚的技术上限，以及诸书对同一战斗记载的差异，守军一侧则几无材料，只能从唐军叙述反推攻城细节。",
        content: `
            <p>贞观十九年（645）五月，唐军兵临辽东城下。这座城即汉晋辽东郡治襄平的故地，高句丽据之为西境重镇，城垣临辽水而筑，是唐军北进必须拔除的第一颗硬钉子。此前的盖牟城只算前哨，辽东城才是真正的考验；城破之后，唐军才真正进入高句丽的腹地。</p>
            <p>部署是两路并进。李勣为辽东道行军大总管，率主力自幽州出柳城；江夏王李道宗为副，领骑兵先行。太宗本人随后自洛阳北上，统筹全局。攻城之前，高句丽曾派步骑四万来援，李道宗以四千骑逆击，众寡悬殊，李勣率军合击，才将援军击退。这一战的细节在《通鉴》里只有数行，却决定了此后攻城的节奏，也说明唐军的野战优势需要集中才能兑现。</p>
            <p>攻城的办法是当时通行的整套工序：填壕、筑土山、造冲车、架抛车、树云梯。土山用来压制城头，冲车用来撞门，抛车用来发石，云梯用来登城。这些手段并不新鲜，难点在于工期与伤亡：土山要堆到高于城墙，冲车要推到门洞，每一步都在守军的箭石之下。唐军的工兵由民夫与府兵混编，昼夜轮替，火把与鼓声不断，守军则以擂石与热油回应。</p>
            <p>火攻是转折点。据《资治通鉴》，攻城时南风急，唐军派锐卒登冲竿，纵火焚城西南楼，火延烧城中，屋宇皆尽，守军阵脚大乱，唐军乘势登城。风向在这里不是修饰，而是胜负条件：南风助火向城内蔓延，若风反向，烧的就是唐军自己的攻城器械。《通鉴》记此事只寥寥数语，具体如何纵火、火势怎样蔓延，今天已无法复原。</p>
            <p>城破之后，唐廷以其地置辽州，安抚降众，收其府库。处置方式与白岩城不同：白岩城是守将请降，唐军受降；辽东城是力战而克，处置更偏向军事管制。这种差别说明唐廷在招降与威慑之间按情形取舍，并非一味宽大或一味残酷。受降与强攻的差别也影响此后各城的抉择：守军知道力尽则屠，请降则生。</p>
            <p>伤亡与补给是这场胜仗的隐形成本。攻城数日，唐军死伤不小，抛石与撞车的器械损耗也大；更关键的是粮运，唐军自幽州、营州转运，粮车在辽西走廊上排队，攻城的节奏必须与粮到的节奏配合。城破之后，唐军没有停留太久，因为下一座城在等着。城下缴获的粮秣不足以支撑长期驻守，这也是唐军不能就地过冬的原因之一。</p>
            <p>与安市城的对比最能说明唐军攻坚的技术上限。安市城同样是石筑山城，守军同样坚壁不出。唐军仍用土山、冲车，围攻六十余日不下；土山一度崩塌，守军乘机夺取，唐军反攻无效，成了整场战役的转折。同样的技术，用在不同的地形与守志上，结果完全不同。</p>
            <p>技术上限在哪里？一是缺乏持续压制的重型火力，抛车能发石，但无法像后世的配重抛石机那样稳定摧毁城墙；二是土山工程耗时且脆弱，一场雨或一次崩塌就能让数日之功归零；三是守军可以修补，唐军却难以封锁修补所需的材料与人力。攻城因此变成消耗竞赛，而唐军的补给线更长。唐军曾试图以抛车集中轰击一处城墙，但石弹供应与器械维护都跟不上。</p>
            <p>另一个上限是指挥。辽东城下，李勣与李道宗的配合还算顺畅；安市城下，诸将意见分歧，太宗的亲自督战反而增加了决策层级。攻城需要统一而快速的决断，唐军的制度在野战中运转良好，在长期攻坚中却容易迟疑。这种迟疑在野战中还能靠将领的临机决断弥补，在城下却直接变成工期。</p>
            <p>城中的抵抗也值得一说。高句丽守军并非只靠城墙，他们在城头备有擂石与热油，在城门内侧设障，在城墙被火焚后仍能分区抵抗。唐军登城之后，巷战仍持续了一段时间。正史用「城遂溃」三字概括，实际过程恐怕要复杂得多。</p>
            <p>史料差异需要注意。《旧唐书》本纪对辽东城之战只记结果，列传稍详；《新唐书》删繁就简；《资治通鉴》采《太宗实录》与国史，细节最丰富，也最有润色痕迹。火攻的时间、谁先登城、斩获数字，各书并不完全一致。</p>
            <p>这些差异不能简单归为谁抄错了。实录由史臣在皇帝生前编纂，战场叙述难免突出太宗的角色；《通鉴》为编年叙事，需要把不同来源的记载排进同一天，难免有拼接。读这场战役，最好把各书并列，看哪些细节是共有的，哪些只出现在一处。</p>
            <p>还有一个容易被忽略的层面：高句丽方面的记载几乎不存。我们看到的攻城过程，全是从唐军视角写出的；守军的部署、伤亡、补给、士气，只能从唐军的描述里反推。这种单向视角会让唐军的技术显得更有效，也会让守军的抵抗显得更被动。高句丽的史料多毁于战火，现存记载又经朝鲜王朝史家整理，追述的成分很重。</p>
            <p>辽东城的攻克，为唐军打开了通往辽东腹地的道路，但并没有改变战争的走向。此后白岩城虽降，安市城却久攻不下，唐军最终在九月班师。一座城的胜利，掩盖不了整场战役在时间与补给上的失败。</p>
            <p>回到这场战斗本身：它是一场按当时标准打得相当漂亮的攻坚，火攻、土山、冲车都用到了，风向也站在唐军一边。但它同样暴露了唐军的上限，攻城依赖天气、工期与补给，任何一环出错，胜利就会变成僵持。安市城就是那个出错的地方。</p>
        `,
    },
    {
        id: "goguryeo-royal-succession",
        title: "高句丽的王位继承与婚姻网络",
        date: "2026-12-11",
        tags: ["高句丽", "王权", "婚姻"],
        summary: "高句丽七百余年二十八王，父子相继与兄终弟及并存，继承始终没有定为一尊。本文讨论王后族属、母族势力与五部拥立如何左右王位，追踪泉氏专权与唐的介入，并检讨《三国史记》与《好太王碑》各自能看到什么，认为继承规则的不确定正是政治动荡的结构性来源，也为唐的介入留出缝隙。",
        content: `
            <p>高句丽七百余年，二十八王，继承方式却始终没有定为一尊。父子相继是常态，兄终弟及也不罕见，叔侄、旁系入继的例子同样存在。把这种多样性称为制度，其实高估了它的确定性；更准确的说法是，高句丽有一套继承的惯例，但没有一套能约束所有人的规则。</p>
            <p>早期的王系已经显出这种弹性。琉璃王之后，大武神王、闵中王、慕本王之间的更替，既有父子，也有兄弟与叔侄；太祖王以旁系入继，在位九十余年，说明血缘远近并不是唯一标准，贵族拥立与个人实力同样重要。这些记载来自《三国史记》，年代与世系都有后人整理的痕迹；该书把早期诸王的在位年数拉得很长，与现代学者据金石材料所作的推算并不一致。</p>
            <p>兄终弟及的好处是避免幼主，坏处是旁系子孙越积越多，每一次更替都可能引发争夺。故国川王无子，弟山上王继位；山上王之后又回到父子相继。这种交替不是设计，而是各方势力博弈的结果：有强势王子时，父死子继；没有强势王子时，贵族就从兄弟或侄子中另选。</p>
            <p>王后的族属是另一条线索。高句丽王室与五部贵族通婚，王后多出自有实力的家族；母族强，幼主就可能被拥立，再由母族与舅氏掌权。史料对王后的记载零散，往往只记娶某部之女，不记其家族后续，因此很难复原完整的婚姻网络。可以确认的是，王后出身往往与某一部的兴衰同步，母族强则王后显，母族弱则记载也简。</p>
            <p>泉氏的崛起是这套逻辑的极端案例。渊盖苏文（姓渊，亦作泉）出身权贵，其父渊太祚曾为高句丽重臣。荣留王末年，渊盖苏文发动政变，杀荣留王，另立宝藏王，自任莫离支，专断国政。这不是继承，而是权臣以拥立之名接管王权。政变之后，高句丽的对唐政策转趋强硬，双方在边境上的摩擦随之增多。</p>
            <p>莫离支不是王号，却比王号更有实权。渊盖苏文掌军政、外交与人事，宝藏王成为名义上的君主。唐太宗征辽的诏书里，把弑君与专权并列为出师理由，这说明在高句丽的政治语境里，谁坐在王位上，与谁真正掌权，是两件事。</p>
            <p>唐的介入因此不只是边境冲突。唐廷曾册封荣留王为辽东郡王、高丽王，渊盖苏文弑君之后，唐不承认新政权的合法性；同时高句丽与百济联合攻新罗，新罗向唐求救，唐廷遂以救新罗、讨弑君为名亲征。继承问题在这里变成了国际问题。</p>
            <p>渊盖苏文死后，继承问题再次爆发。其长子泉男生与弟泉男建、泉男产争权，男生被排挤，遂降唐，引唐军进攻平壤。总章元年（668）高句丽灭亡，直接导火索不是唐军的强大，而是泉氏内部的继承分裂。王位继承的不确定，最终以亡国收场。唐军入平壤后，宝藏王被俘，泉男建被擒，泉氏的政治投资彻底失败。</p>
            <p>这里有一个机制值得说明：继承规则越不确定，权力交接的成本越高。每一次王位更替，贵族都要重新站队，站错队的家族可能被清洗；为了避免被清洗，家族又会提前布局，扶持自己的候选人。结果是，继承不只是王族内部的事，而是整个贵族网络的重组。重组往往伴随清洗，清洗又制造新的不满，循环因此难以终止。</p>
            <p>婚姻网络在这种重组中起黏合作用。王室与五部通婚，把外戚变成利益相关方；权臣与王室联姻，又把拥立变成家族投资。高句丽的婚姻不是私事，而是政治联盟的公开形式。只是史料留下的婚姻记录太少，我们能看到结果，看不到谈判过程。</p>
            <p>王位争夺还常伴随都城与地方势力的角力。高句丽的都城几度迁移，王畿与地方城主的利益并不一致；拥立者往往来自某一地域集团，新王即位后又要安抚其他集团。继承因此不只是家族问题，也是地域政治的再平衡。谁能控制都城，谁就控制了王的起居与诏令，这也是拥立者争夺的焦点。</p>
            <p>《三国史记》的叙事倾向需要警惕。金富轼以儒家正统观念编纂，对篡位者、暴君多所贬抑，对合理的继承人则多加褒扬；他笔下的继承顺序因此显得比实际更有秩序。早期王系的年代，与《好太王碑》等金石材料对照，也存在不能完全吻合之处。</p>
            <p>《好太王碑》提供了另一类证据。碑文记广开土王的功业与世系，是第一手的王权宣告，但它同样经过刻意的修辞：碑要证明王的合法性，不会记录争夺的细节。把它与《三国史记》并读，可以校正年代，却不能指望它还原政治过程。</p>
            <p>出土材料还能补一点制度细节。高句丽的城址、碑刻与墓葬显示，王陵的分布与都城变迁相关，王权的仪式空间随政治中心移动；但这些材料不直接记载继承规则，只能作为背景。把它们当作继承法的证据，是过度解读。</p>
            <p>因此，兄终弟及与父子相继并存这句话，最好理解为一种描述，而不是一条规则。高句丽没有固定的继承法，继承的结果取决于王子是否成年、母族是否强势、贵族是否分裂、外部是否有强敌。规则的不确定，正是政治动荡的结构性来源。</p>
            <p>从这个角度看，唐灭高句丽并不是一场单纯的军事胜利。唐军利用了泉氏内乱，而内乱的根源在于继承制度无法约束权臣；权臣之所以能存在，又因为王权需要贵族支持。这个循环在高句丽延续了数百年，最终在七世纪六十年代走到了尽头。</p>
        `,
    },
    {
        id: "expedition-finance",
        title: "征辽的钱粮：隋唐如何供养远征军",
        date: "2026-12-10",
        tags: ["唐与高句丽", "财政", "后勤"],
        summary: "隋唐两代征辽，后勤的差别决定了战争的形态。隋靠仓储与运河做一次性总动员，粮道从涿郡铺到辽东，民夫征发误了农时，也点燃了隋末民变；唐以租庸调为底，辅以和籴、河北转输、江南造船与就地补给，把战争摊到二十多年。军费数字多不可信，但粮道的距离与损耗是硬的：财政能力不决定战争为何发生，却决定它能打多久。",
        content: `
            <p>大业八年正月，涿郡城南的旷野上，粮车与兵车挤在一处。据《隋书·食货志》，发往辽东的民夫与士卒填咽于道，昼夜不绝。这一年隋炀帝第一次征高句丽，史称动员一百一十三万三千八百人，号二百万，真正渡过辽水的战兵约三十万。数字未必可靠，但粮道的规模可以从另一个方向印证：从涿郡到辽东城，直线距离不下千里，运一石粮到前线，路上消耗的往往不止一石。</p>
            <p>隋能支撑这样一场远征，靠的是两样东西：仓廪与运河。开皇年间置黎阳仓、河阳仓、常平仓、广通仓，大业初又筑洛口仓、回洛仓，仓城周围数十里，储粟以千万石计。大业四年（608）开永济渠，引沁水南通黄河、北达涿郡，把河北与中原的粮产连到北方集结地。运河与仓储把征集变成调运，这是隋与北朝诸政权最大的不同。</p>
            <p>但调运不等于送达。陆路转运的损耗极高：车运粮草，路上人吃马喂，走上一千里，到前线往往只剩一小部分；牛车日行不过数十里，遇到雨雪还要耽搁。隋的办法是层层转输：民夫自备车牛，从州县送到下一个仓，再由下一段民夫接运。每一段都征发一次，每一段都误一次农时。大业七年（611）为准备征辽，发民夫运米，积于泸河、怀远二镇，车牛往者皆不返，士卒死亡过半。</p>
            <p>代价落在河北、山东的编户身上。征发不分贫富，有牛车的出牛车，没有的出力；粮食要自备，路上要吃，到了仓还要交足额。耕稼失时，田畴多荒，接着是饥馑。大业七年王薄在长白山起兵，作《无向辽东浪死歌》，窦建德、高士达等相继而起。征辽的粮道，同时也是隋末民变的动员线。</p>
            <p>唐太宗贞观十九年（645）再征辽东，规模小得多。渡辽兵力约十万，加上运输民夫，总数远不及隋。更重要的是时间：三月出兵，九月班师，前后不过半年，避开了辽左最冷的季节。这不是偶然的节制，而是对隋亡教训的直接回应——唐初君臣反复讨论隋以役民而亡，征辽的动员因此被压在一个可以承受的范围内。</p>
            <p>唐前期的财政基础是租庸调。租纳粟，调纳绢绵，庸以绢代役，每丁每年役二十日，不役则纳绢三尺。这套制度的设计是把人力与粮帛都固定下来，便于中央编户征发。但租庸调提供的是常规收入，远征需要的是额外支出：造船、买马、赏赐、运输。缺口靠和籴、靠地方仓储、靠临时加税来填。</p>
            <p>和籴是政府出钱向民间买粮，本意是平抑粮价、充实边储。玄宗朝在关中、河东、河北大规模推行和籴，幽州、平卢的军粮有相当部分来自和籴。它的好处是不必加赋，坏处是需要现钱，而且钱从哪来仍是问题。唐前期铸钱有限，绢帛兼作货币，和籴常常变成以绢折粮，实际负担仍落在农户身上。</p>
            <p>河北道是征辽的转运枢纽。幽州（今北京）是前线总后方，营州（今朝阳）是前进基地，从幽州到营州，再从营州到辽东城，粮道分作两段。贞观十八年（644）预作准备，太宗命将作大匠阎立德等诣洪、饶、江三州，造船四百艘以载军粮，江南的船与粮沿海路北上，进入莱州、幽州，再转陆路。海运省了陆路的消耗，但受季风与海岸线限制，只能作为补充。</p>
            <p>就地补给是唐军的另一条路。攻下辽东城后，唐军获得城中储粮；此后几座城相继投降，也带来粮储。高句丽在辽东经营多年，城仓往往有积粟，攻下一城，等于接手一个粮站。但这条路依赖攻坚成功，一旦顿兵坚城之下，粮道就成了软肋。贞观十九年安市城久攻不下，唐军粮食将尽，又逢辽左早寒，草枯水冻，只能班师。</p>
            <p>后勤的极限直接决定了战争的长度。隋三次征辽，每次都在半年内结束，不是因为打完了，而是因为粮尽、民困、后方生变。唐把战争拉长到二十余年：贞观十九年一次，二十一年、二十二年再出师，高宗永徽、显庆、乾封年间继续用兵，直到总章元年（668）灭高句丽。每一次出兵规模都不大，靠的是间歇与积累，而不是一次性的总动员。</p>
            <p>高宗乾封、总章年间灭高句丽的战役，后勤又换了一种打法。李勣率军自辽东道进，庞同善、契苾何力分道，唐军先在辽东城、新城一带站稳，再向南推进；粮运仍靠营州与辽东城仓，海运则从莱州、东莱入海，支援水军。仗打了两年，靠的是前几十年在辽东积累的据点与仓储，而不是一次临时拼凑的转运。</p>
            <p>军费数字的可信度需要打折扣。《隋书》记第一次征辽总一百一十三万三千八百，号二百万，这个数字把民夫、运输人员与战兵混在一起，且明显有夸饰。唐代的军费更没有系统账目，我们只能从造船数量、转运距离、赏赐记载里间接推算。史料留下的是决策者的说法，不是财政报表。</p>
            <p>所以，隋唐征辽的差别，不只是兵力多少，而是财政模式不同。隋用一次性总动员，把仓储与运河的积蓄在两年内烧完，换来的是民变与崩溃；唐用常规财政加局部动员，把战争摊到二十多年，用时间换空间。财政能力不是战争的原因，但它划定了战争的可能长度——这一点，在辽东的粮道上看得最清楚。</p>
        `,
    },
    {
        id: "tang-maps-guides",
        title: "向导与地图：唐军如何认识辽东",
        date: "2026-12-09",
        tags: ["唐与高句丽", "情报", "地理"],
        summary: "唐军对辽东的地理知识，来自隋代旧档、使节目见、蕃族向导与斥候，而非系统地图。泉男生降唐后指点城邑兵力，是高宗灭高句丽的关键情报；太宗亲征仍靠指授方略，诏令滞后于前线。安市城下的判断失误说明：知道多少不等于能决断多少。本文兼及《通鉴》叙事为太宗回护的可能，把信息优势放回它的限度里。",
        content: `
            <p>贞观十九年（645）春，唐军渡过辽水，进入辽东。唐人对这片地方的了解，大多来自书本与前朝的行军记录，而不是亲身的踏勘。太宗在行军途中登高观望、询问山川的记载，散见于《资治通鉴》与两《唐书》，细节未必可靠，却点出一个实际问题：唐军对辽东的山川道路，了解得相当有限。</p>
            <p>唐人的知识，一部分来自隋代的旧档。隋炀帝三次征辽，留下大量行军记录、驿道里程与城池位置；唐初修《隋书》，也整理过这些材料。另一部分来自使节与俘虏。武德、贞观年间，唐与高句丽互遣使者，使者带回的路程与见闻被记入官方文书；战争俘获的高句丽人，也会被问及道路与城防。这些知识零散、滞后，却是唐军出发时能依靠的全部。</p>
            <p>情报是双向的。高句丽方面对唐军的了解，一部分来自隋末流入辽东的汉人，一部分来自使节与商旅。唐军出动多少、走哪条路，高句丽往往能在边境就得到消息。贞观十九年唐军一到辽东，高句丽即收缩兵力、坚壁清野，反应之快说明他们并非全然被动。信息不对称从来不是单方面的，唐军有向导，高句丽也有耳目；差别在于唐军要把零散消息拼成作战图，高句丽只需守住自己熟悉的地形。</p>
            <p>更实用的是蕃族向导。唐在东北的盟友与属部——契丹、奚、靺鞨——长期与高句丽接触，熟悉辽东山地的路径。贞观十八年（644），太宗诏营州都督张俭等发幽、营二都督兵及契丹、奚、靺鞨先击辽东，这批前锋既是兵力，也是耳目。他们知道哪条河谷可以行军，哪个山口有水源，哪一种天气会让山路断绝。</p>
            <p>高宗乾封年间，向导的作用更直接。乾封元年（666）泉盖苏文死，其子泉男生、泉男建、泉男产争权，男生被逐，据国内城，遣子泉献诚入唐求救。唐以契苾何力、庞同善、高侃等接应，泉男生遂为唐军向导，指点高句丽的城邑与兵力部署。这是唐灭高句丽过程中最关键的情报来源之一：不是地图，而是一个熟悉内情的人。</p>
            <p>斥候是常规手段。唐军行军，前后左右都派探马，遇山则登高瞭望，遇水则探深浅。斥候带回的是即时情报：前方有无伏兵、桥梁是否可渡、村落是否坚壁。这类情报零碎，但更新快，弥补了地图的滞后。唐代边军还有捉生的做法，即小股出击擒俘，从俘虏口中问出敌情；一次成功的捉生，往往比十张旧图有用。</p>
            <p>地图在唐代是行政工具，不是作战工具。兵部职方郎中掌天下地图，每岁受诸州图经，用于户籍、贡赋与驿道。这些图经详细到州县方位与道里，却很少标注战场地形。真正用于行军的地图，多是临时绘制的行军图或道里图，由随军书记根据向导口述与斥候回报拼凑，精度有限。唐军所谓指授方略，依据的常常是这种拼凑出来的地理。</p>
            <p>太宗亲征，仍要指授方略。他在幽州、在辽东前线，不断给李勣、李道宗、张俭等将领下诏，规定进军路线与攻击次序。这些指示的依据，是旧档、向导与斥候的混合。问题在于，前线的情况变化很快，而诏令传到前线需要时间。将领们常常要在遵旨与应变之间选择，安市城下的犹豫就与此有关。</p>
            <p>高句丽方面则占有地利。他们熟悉每一道山梁与每一条河谷，知道唐军的粮道必经何处，于是坚壁清野，把人口与粮食撤入山城。唐军攻下一座空城，得到的往往不是粮储，而是废墟。这种不对称不是地图能弥补的：地图可以标出城的位置，却标不出城的意志与仓廪的虚实。坚壁清野还让向导失去了作用：向导知道城在哪里，却不知道人去了哪里。</p>
            <p>安市城是最常被提起的失误。贞观十九年六月，唐军进至安市城下，城主坚守，唐军筑土山、造冲车，攻了数月不下。太宗判断安市城险固，仍决定强攻，结果土山崩塌，守军夺占土山，唐军反而失去制高点。九月，因辽左早寒、草枯水冻、粮食将尽，全军班师。这个判断的错误，一半在情报，一半在决策。</p>
            <p>唐代对辽东地理的系统整理，要等到战后。德宗贞元年间，宰相贾耽绘《海内华夷图》，撰《古今郡国县道四夷述》，把边疆地理纳入一个可检索的框架。贾耽的依据包括使节见闻、边将报告与旧图，比太宗时的零散知识系统得多。但这部书成于八世纪末，距离贞观征辽已一百多年；它说明地理知识会积累，也说明战时的唐军等不及这种积累。</p>
            <p>《资治通鉴》的记载需要谨慎对待。司马光编此书时，主要依据《旧唐书》《新唐书》与《唐会要》，而这两《唐书》的太宗征辽部分，又多采自国史与实录，带有为太宗回护的倾向。太宗指授方略的细节，可能是事后整理的美化；安市城之败，也可能被归因于天时而非判断。史料能证明唐军确实缺粮、确实退兵，但不能证明太宗的每一次指示都经过充分侦察。</p>
            <p>信息优势并不自动等于决策优势。唐军有向导、有斥候、有旧档，仍会在安市城下判断失误；高句丽没有系统地图，却凭地利与坚壁清野拖住了唐军。真正决定胜负的，不只是知道多少，而是能否把知道的东西及时变成决断。在这个意义上，向导与地图是条件，不是答案。</p>
        `,
    },
    {
        id: "goguryeo-wooden-tablets",
        title: "木简与城民：高句丽社会的出土文书",
        date: "2026-12-08",
        tags: ["高句丽", "出土文献", "社会"],
        summary: "集安与平壤出土的高句丽木简，多为残断的标签、簿籍与文书残件，数量有限而释读困难。其中的城民、谷仓、官号记录，显示高句丽有以城为单位的户籍、仓储与文书行政，可与《三国史记》互证，却不能替代编年叙事。本文讨论木简能证明什么、不能证明什么，以及废弃堆积造成的样本偏差。",
        content: `
            <p>高句丽的木简，多半是残片。它们在集安国内城、平壤大城山城一带的废弃堆积里被发现，长短不一，墨迹褪色，许多只剩下几个字。研究者要先把它们按字体、木质与出土层位分组，再逐字释读，最后才谈得上文书二字。这个过程本身就说明：出土文书能补文献之缺，但补得很有限。</p>
            <p>出土地点集中在两处。一处是集安，高句丽的早期都城国内城与丸都山城所在；一处是平壤，公元427年长寿王迁都之后的政治中心。两地的木简数量都不算多，已刊布的数量有限，年代多集中在五至七世纪。这个分布与高句丽的国家形态吻合：都城与山城是行政与仓储的中心，文书也集中在那里。</p>
            <p>木简的形制也透露信息。高句丽木简多为松木或桦木削成，长度不一，有的顶端穿孔，显然用于系挂；有的两面书写，说明材料并不宽裕。与中原简牍相比，高句丽木简的尺寸更随意，少见统一的编联方式，这既可能是地方行政的习惯，也可能是出土样本太少造成的错觉。</p>
            <p>木简的内容大致分三类。一类是标签，写人名、物品名与数量，系在器物或粮袋上；一类是簿籍残片，记录谷物出入、人员名册；还有一类是文书残件，有日期、官号与命令的痕迹。三类之中，簿籍最能说明问题：它意味着高句丽有按数量、按人头记账的习惯，而不只是口头征发。</p>
            <p>城民是木简释读中出现的一个关键词。高句丽的城不只是军事据点，也是编户的聚落；城民依附于城，承担租赋与劳役，战时守城，平时耕作。木简里的城民名单、口数、谷物配给，指向一种以城为单位的户籍管理。这与《三国史记》所记的城与谷仓可以对上，但木简提供了更具体的操作层面。</p>
            <p>谷仓是另一个关键词。高句丽在山城与平原城设置仓廪，储存粟、豆、盐等物。木简中有谷物出入的记录，标注日期、数量与经手人，形式与中原的仓廪簿籍相似。这说明高句丽的粮食管理不是随意的，而有簿记、有验收、有责任人的制度。屯田的产出、赋税的征收、军粮的调拨，都要经过这些仓。</p>
            <p>赋税记录则更零碎。木简里可以看到按户或按口征收的谷物、布帛，偶尔有调、租之类的字样。但木简残断，很难还原完整的税率与征收周期。研究者能说的是：高句丽的赋役以实物为主，谷物与布帛并重，征收单位是城与村，而不是单纯的个人。这一点与中原王朝的租调制度有相似之处，也有高句丽自己的特点。</p>
            <p>文书行政的痕迹还体现在官号上。木简中出现的褥萨、处闾、可逻达等名号，与《周书·高丽传》《隋书·高丽传》所记的官制可以对应。五部的名称——上部、前部、中部、下部、后部——也在木简与碑刻中出现。这说明高句丽的中央官号与地方城守之间有文书往来，命令通过木简传递，而不是只靠使者口传。</p>
            <p>释读的争议不少。木简残断，同一字形可能释为两个不同的字；墨迹褪色，笔画的有无会改变词义；出土层位若被扰动，年代判断也会失准。更麻烦的是，高句丽木简的书写者用的是汉字，但语法与词汇可能带有高句丽语的特点，释读时容易套用中原文书的格式。这些争议不是枝节，它们直接影响到城民是自由民还是依附民这类判断。</p>
            <p>木简之外，高句丽还留下碑刻与壁画题记。好太王碑、中原高句丽碑、牟头娄墓志，都是文字材料；壁画墓里的墨书题记，记墓主姓名、官职与年代。把这些材料与木简放在一起，才能看出高句丽的书写文化有多厚：碑用于纪功，墓志用于记人，木简用于记账。三种材料的功能不同，可靠程度也不同——碑刻意在传世，木简意在实用，后者更接近日常，却也更残缺。</p>
            <p>与《三国史记》互证，是木简研究的主要目标之一。《三国史记》成书于高丽仁宗二十三年（1145），金富轼等编，高句丽部分主要依据《旧三国史》与中原史书，叙事集中在王位、战争与灾异，对社会经济几乎不着墨。木简恰好补上这一块：它让我们看到城的编户、仓的簿籍、官的文书。但互证有界限：木简是碎片，不能像编年史那样提供连续的时间线；《三国史记》是后世编纂，带有金富轼的取舍。两者只能互相参证，不能互相替代。</p>
            <p>考古材料补文献之缺，最有力的地方在于日常。文献记的是王命与战事，木简记的是谁领了多少谷、哪一天入了仓、哪个人名下有几口人。这些日常记录让高句丽社会从武勇的刻板印象里走出来，显出行政、仓储与户籍的一面。但也要注意：木简多出土于废弃堆积，能保存下来的往往是废弃的、残缺的文书，完整的簿籍极少。样本偏差是这类研究绕不开的问题。研究者只能按出土单位做小范围的统计，不敢轻易外推。</p>
            <p>所以，木简的价值不在于证明某个结论，而在于提供一种新的证据类型。它让高句丽的历史不再只依赖中原史书的他者叙述，也不只依赖后世的《三国史记》。当然，这种证据类型有它的限度：数量少、残断多、释读难。研究者能做的，是在限度之内尽量谨慎地推断，而不是把碎片拼成完整的故事。</p>
        `,
    },
    {
        id: "japan-after-663",
        title: "白江口之后：日本律令国家的防御转向",
        date: "2026-12-07",
        tags: ["日本史", "白江口", "律令"],
        summary: "663年白江口战败后，天智朝在九州筑水城、大野城、基肄城，置防人与烽，同时加速律令编纂、造庚午年籍、迁都近江。防御工程借百济遗民的技术，学习唐制与戒备唐军并行。《日本书纪》成书于半世纪后，把应急举措写成圣君决策。本文辨析制度事实与叙事建构，说明战败如何被转化为国家建设的动力。",
        content: `
            <p>663年八月，白江口（今韩国锦江入海口）的海面上，倭国与百济的船队排列迎战，唐罗联军以火攻破之。据《日本书纪》卷二十七，倭军战船四百余艘被焚，烟焰涨天。这一战，倭国损失了远征百济的主力，也失去了在朝鲜半岛南部的立足点。消息传回列岛，朝廷的反应不是立即复仇，而是修城、置防、编籍。</p>
            <p>恐慌有具体的理由。唐罗联军在灭百济之后，兵锋可能转向日本本土；九州是最近的门户，博多湾是可能的登陆点。天智天皇（当时称中大兄皇子，668年正式即位）在战后数年里，把防卫重心放在筑紫。这不是后世的想象，《日本书纪》天智纪里连续几年记下筑城、置防人、置烽的举措，节奏紧凑得像是战时动员。当时的朝廷没有常备军，防卫只能靠临时征发与筑城，这也决定了各项举措的仓促。</p>
            <p>天智三年（664），置筑紫防人及烽。防人是从东国征发的戍卒，轮流驻守九州沿岸，三年一替；烽是烽火台，沿博多湾与玄界滩布置，遇警则举烽。防人制度后来被《大宝律令》吸收，成为律令国家军事组织的一部分。它的负担很重：戍卒要自备粮食与武器，长途跋涉到九州，许多人一去不返。《万叶集》里的防人歌，唱的就是这种离别。</p>
            <p>水城的修筑年代，通常定在天智三、四年间（664—665），其性质是一道土垒与水渠。这道防线在大宰府北面，把博多湾与内陆隔开，敌船若溯湾而上，会被水城挡住。它不是一座城，而是一道防线；没有城墙与敌楼，只有土堤、水门与驻兵的营地。这种设计说明日本方面的判断：威胁来自海路，防御的重点是登陆点，而不是内陆纵深。</p>
            <p>天智四年（665），筑大野城与基肄城。两城都在筑紫一带的山上，用石块垒砌，形制与朝鲜半岛的山城相似，学界称为朝鲜式山城。大野城在大宰府背后的四王寺山，基肄城在基山，两城互为犄角，控制通往内陆的通道。同一时期还筑了椽城、长门城，防线从筑紫延伸到本州西端。这是一套完整的防御体系，不是零散的要塞。</p>
            <p>筑城的技术来自百济遗民。663年之后，大批百济贵族、官吏、工匠渡海到日本，其中不少人参与了大野城与基肄城的规划。朝鲜式山城的砌石方法、城门的形制、山城的选址原则，都随这些人传入。日本方面不仅接纳了他们，还给了他们位阶与领地。战败者的技术，成了应对威胁的资本。</p>
            <p>天智六年（667），天智天皇迁都近江大津宫，离开飞鸟，把政治中心北移。迁都的原因有各种解释，防卫与重建是其中之一；近江靠近畿内与北陆，便于控制东国的兵力与物资，也远离难波、飞鸟这些与旧豪族关系太深的地方。迁都不只是搬家，它重新安排了朝廷与地方的关系。</p>
            <p>天智九年（670），造庚午年籍。这是日本最早的全国性户籍，按户记录人名、年龄与田宅。律令国家的统治建立在户籍、计帐与班田之上；没有户籍，就无法按口授田、按户征调。天智朝在战后七年内造籍，说明朝廷把掌握人口当作防御与重建的基础。同年，天智朝还推进了近江令的编纂——通说认为有二十二卷，但原本不传，内容只能从后世的《大宝律令》与《弘仁格式》间接推测；也有学者怀疑《近江令》是否真实存在，认为它是后世为追溯律令源流而构造的。</p>
            <p>这套防御体系并没有经过实战检验。唐军没有进攻日本本土，九州诸城在后来的历史里多半闲置，防人制度却延续下来，成为律令国家的负担。这说明防御转向的意义不只在军事：它把九州纳入中央的直接控制，把地方豪族编入戍卒与补给体系，为律令国家的地方行政铺了路。换句话说，防唐是手段，集权是结果；军事上的被动，反过来推动了中央对地方的控制。</p>
            <p>对唐的态度是双重的。一方面，日本继续派遣遣唐使，学习律令、佛教与都城制度；另一方面，九州防线始终没有撤除。天智朝与唐有使节往来，唐使也曾到日本；但遣唐使的派遣在天智朝一度中断，直到大宝二年（702）粟田真人使唐才恢复。学习与戒备并存，不是矛盾，而是小国面对大国的常态：知识要学，门户要守。</p>
            <p>《日本书纪》的叙事需要打折扣。此书成于养老四年（720），由舍人亲王等编，编纂的起点在天武朝，距离白江口之战已半个世纪。书中对白江口之战的记载，强调倭军的英勇与不利而非惨败，对天智朝的防御举措则写得条理分明，像是为圣君立传。研究者因此要区分两层：天智朝确实修了城、置了防人，这是制度事实；《日本书纪》把这些举措串成一条英明决策的线索，则是叙事建构。</p>
            <p>战败如何转化为制度建设的动力？白江口之战是一个清楚的案例。军事上的失败暴露了日本在情报、组织与技术上的差距；朝廷的回应不是闭关，而是修城、置防、编籍、立法，把一时的危机变成长期的制度。当然，不能把一切都归因于这一战：律令编纂有更长的脉络，遣唐使的恢复也有自己的节奏。但663年确实是一个转折点，它让防御从临时措施变成了国家工程，也让日本第一次以律令国家的姿态面对大陆。</p>
        `,
    },
    {
        id: "goguryeo-textbooks",
        title: "教科书里的高句丽：四国叙事的差异",
        date: "2026-12-06",
        tags: ["高句丽", "史学史", "教育"],
        summary: "高句丽在四国教科书里位置不同：中国置于边疆史与统一叙事，朝鲜与韩国置于三国与民族谱系，日本置于东亚互动。归属、好太王碑与东北工程是争议焦点，各方史料依据与盲区并存。本文并置四种叙述的前提，区分可检验的史料问题与超出史料的政治判断，不做站队，只说明教育如何塑造集体记忆。",
        content: `
            <p>同一段历史，在四国教科书里被放在不同的章节。中国教科书把高句丽放进隋唐时期的边疆民族；朝鲜教科书把它放进三国时代；韩国教科书把它放进古代国家的成长；日本教科书则把它放进东亚国际关系的叙述里。位置的差异不只是编排习惯，它决定了学生第一次接触高句丽时，看到的是一个边疆政权、一个民族国家的前身，还是一个区域互动中的角色。</p>
            <p>中国教科书的框架是边疆史。高句丽被描述为活动于中国东北的古代民族政权，与中原王朝有臣属、朝贡与战争的关系；唐灭高句丽，被放在统一多民族国家的形成过程中讲述。这个框架的依据，一是高句丽故地在今中国东北，二是中原史书对高句丽的记载，三是高句丽与中原王朝的封贡关系。教科书的语言通常克制，强调民族交融而不是征服。</p>
            <p>朝鲜教科书的框架是三国。高句丽与百济、新罗并列为朝鲜半岛的三个古代国家，上承檀君朝鲜，下接统一新罗。高句丽的建国传说——朱蒙自夫余南迁、于卒本川立国——被当作朝鲜民族起源叙事的一部分。教科书强调高句丽的独立性、军事力量与领土扩张，好太王碑是常用的史料。在这个框架里，高句丽不是边疆政权，而是朝鲜历史的正面主角之一。</p>
            <p>韩国教科书的框架与此相近，但更强调领土与民族。高句丽被描述为三国中最强盛的国家，其势力范围包括今朝鲜半岛北部与中国东北的一部分；教科书中会出现高句丽与隋唐的战争，强调高句丽击退隋军、抵御唐军。对东北工程的争议，韩国教科书与民间叙事都有反应，认为中国方面把高句丽纳入中国史，是对韩国古代史的吸收。这种表述带有情绪，但它是理解争议的关键。</p>
            <p>日本教科书的处理最简略。高句丽通常出现在倭与朝鲜半岛的章节里，与百济、新罗并列，重点在白江口之战与遣唐使。日本教材不太讨论高句丽的归属，也不把高句丽当作日本史的一部分；它关心的是倭国如何介入半岛事务、如何从失败中学习。这种外部视角使日本教材较少卷入归属争议，但也使高句丽的社会与文化很少被展开。</p>
            <p>值得注意的是，四国教科书都不是铁板一块。中国的教材版本之间、韩国的国定与检定教材之间、日本的历史教科书之间，对高句丽的篇幅与措辞都有差异。教科书审查制度、编写者的学术背景、甚至课时安排，都会影响叙述。把某国教科书当成一个统一的声音，本身就简化了问题。</p>
            <p>争议的焦点是归属。中国学者多认为高句丽是中国东北古代民族政权，理由包括故地、封贡关系与中原史书的记载；朝鲜与韩国学者多认为高句丽是朝鲜古代国家，理由包括建国传说、语言与文化的关联、以及高句丽在半岛政治中的角色。这不是一个能靠单一史料解决的问题：同一份《三国史记》，可以被读成朝鲜史书，也可以被读成汉文史书的地方版本。学界的分歧，往往在政权与民族、领土与文化之间来回。</p>
            <p>好太王碑是争议的集中点。碑立于414年，在今吉林集安，记载广开土王的功业、守墓人烟户与禁令。碑文中有关于倭的记录，中日韩学者对相关字句的释读与解释不同：有的读作倭军侵入半岛，有的读作倭与高句丽在半岛的拉锯。碑文本身是高句丽人立的，立场自然是高句丽的；它能证明高句丽的自我叙述，却不能单独证明领土归属。把碑文当作领土证据，是常见的误用。</p>
            <p>东北工程把学术争议推到了公共领域。2002年中国社会科学院启动东北边疆历史与现状系列研究工程，其中涉及高句丽历史的研究，引发韩国学界与民间的强烈反应，双方都有过外交层面的交涉。工程本身是学术项目，但它的选题、表述与传播，被放在了民族叙事的框架里解读。这件事说明：高句丽研究不只是书斋里的问题，它牵动国家认同与教科书编写。</p>
            <p>教育如何塑造集体记忆？教科书是国家审定的，它的叙述受课程标准、审查制度与政治气候影响。一个学生在教科书里第一次读到高句丽，得到的不是一个中立的古代政权，而是一个被放进本国历史脉络的角色。这个角色会沉淀为记忆，影响他日后对相关争议的直觉反应。四国教科书的差异，因此不只是学术差异，也是记忆政治的差异。</p>
            <p>学术与政治的边界在哪里？一方面，历史研究无法完全脱离研究者的立场与所在国的学术传统；另一方面，史料、考古与文献学有相对客观的标准，可以约束过度解释。好太王碑的字句、木简的释读、城址的发掘，都是可以检验的；归属判断则往往超出史料能直接支持的范围。承认这一点，不是相对主义，而是把可检验的部分与不可检验的部分分开。</p>
            <p>所以，读四国教科书，最该注意的不是谁对谁错，而是每种叙述的前提。中国教科书的前提是边疆与统一，朝鲜与韩国教科书的前提是民族与连续，日本教科书的前提是区域互动。这些前提各有史料支撑，也各有盲区。把它们并置起来读，比选一个立场更难，也更有用。高句丽的历史不会因为教科书而改变，但教科书会改变人们看待它的方式。</p>
        `,
    },
    {
        id: "tang-army-organization",
        title: "唐军的编制与行军：折冲府、行军大总管与六军",
        date: "2026-12-25",
        tags: ["唐丽战争", "军事制度", "行军"],
        summary: "贞观十八年冬，幽州城南按团旅队火列队的府兵，引出折冲府的编制、自备资装与关内调兵的距离；再论行军大总管属临时统兵、六军是后世追加的标签，并以安市之战的临时编组与粮运驿传，说明这支军队能走远却难以久战：胜负往往取决于粮车而非阵列，这一点，诏令里从不明写，史书也语焉不详。",
        content: `
            <p>贞观十八年十一月，幽州城南的旷野上，来自河北道各州的府兵正按团、旅、队、火逐级列队。名籍上写着他们的折冲府名、本人年岁与所备弓矢；队正清点火长报上的数目，再向旅帅复命。这一幕没有留下图像，但《新唐书·兵志》对府兵编制的规定，与《资治通鉴》对征辽前集结的记载，可以互相拼合。</p>
            <p>折冲府是贞观十年由统军府改来的名称。上府千二百人，中府千人，下府八百人，这是通行说法；长官为折冲都尉，副为果毅都尉。府下按团、旅、队、火编成，二百人为团，百人为旅，五十人为队，十人为火，各有校尉、旅帅、队正、火长。这套数字整齐得近乎理想，实际员额常有缺额，边境与内地的充实程度也不一样。府兵三年一拣点，拣中之后军名注籍，州县不能随意勾除。</p>
            <p>府兵出自均田农民，二十岁入役、六十免役是常见表述。他们自备资装：弓一、矢三十、胡禄、横刀、砺石、毡帽、行縢，以及麦饭九斗、米二斗。国家给的是身份与勋赏的可能，不是全部给养。征辽路途数千里，这点口粮远远不够，行军途中必须靠转输与就地补给，这从一开始就决定了战役的时间窗口。</p>
            <p>折冲府的分布，决定了调兵的距离。唐前期府兵集中于关内道，拱卫京师，河北道、河东道的府数相对有限。征辽的集结地在幽州、营州，关中的兵要东行千余里才能到位。所谓内重外轻，在制度上是安全设计，在战役上却是后勤负担：兵越多，路上的消耗越大，到达前线的日期也越难齐一。</p>
            <p>贞观十八年的征发并不只靠府兵。诏书除发幽、营等州兵外，还征契丹、奚、靺鞨等蕃兵，并在山东、河北募人。府兵役期本有定限，远征却往往经年，于是募与蕃填补了府兵留下的缺口。军队的构成因此是叠合的：有编制的府兵、临时募集的骁勇、羁縻州县的蕃部，还有高句丽降众。</p>
            <p>指挥层级上，太宗以辽东道行军大总管授李勣，平壤道行军大总管授张亮，一陆一海。大总管之下有副总管、行军总管，再下是府与州的统兵官。行军大总管不是常设官职，而是因战事临时而设，战罢即撤。这种设计使皇帝可以把兵权切成几块，交给彼此不相统属的几个人，最后由自己在中军裁断；代价是诸路之间的协同，只能靠诏令与主帅的私谊。</p>
            <p>所谓六军需要辨析。贞观诏令中的六军多是对天子之师的泛称，其语源可以追到《周礼》王六军的旧说；北衙左右羽林、龙武、神武六军定型要晚到玄宗朝。把征辽军队直接称为六军，是把后来的制度投射回太宗朝。真正起作用的是行军总管、府、团、队这条线，以及皇帝身边的中军与亲兵。</p>
            <p>粮料是编制的另一半。征辽的补给线从河北道、河南道向幽州、营州集中，再分陆运与海运两路：陆路出榆关，海路自莱州渡海趋平壤。转输用民夫、车牛，沿途置驿、置烽。军队的推进速度因此不取决于战马，而取决于粮车；粮车不到，再精锐的骑兵也只能停下。</p>
            <p>进军的路线也可以复原。陆路自幽州东北行，经营州，渡辽水，攻辽东城，再南下安市；海路自莱州渡海，张亮舟师沿海北上，攻沙卑城，牵制高句丽南境，却始终未能与陆路会师。两路之间隔着辽东的山地与河流，难以互相支援。分进是为了牵制，也埋下了协同不足的隐患。</p>
            <p>驿传与符契把分散的部队连成一体。发兵有鱼符、木契，行军有驿马、烽候；诏令从长安到幽州，再传到前线各营，靠的是这套信息系统。安市城下太宗能逐日调度诸军，正因这套系统尚能运转；而一旦粮尽、天寒，系统再灵也变不出粮食。</p>
            <p>编组的实际样态，可以从一次战斗反推。安市城东南之战，高延寿、高惠真率高句丽、靺鞨兵十五万来援，唐军以李勣率步骑一万五千列阵于西岭，长孙无忌率精兵一万一千出北山为奇兵，太宗自率步骑四千登北山。这不是府兵整齐的团旅队形，而是按任务临时编成的步、骑、奇正数支，各支的兵力与任务都由主帅当场指定。</p>
            <p>还有一个常被忽略的层面：行军途中的编组不止于战斗序列。宿营有营规，行军有行列，渡河有次序，辎重有护军。这些细节在正史中几乎不载，只能从兵书与律令的零碎条文推想；《太白阴经》成书稍晚，所记营阵、鼓角、赏罚仍可反映行军的一般做法。制度的骨架清楚，血肉模糊。</p>
            <p>史料在这里显出缺口。《新唐书·兵志》成于北宋，采唐国史与《唐会要》，对府兵兵散于府、将归于朝的描述带有理想化色彩；《资治通鉴》讲战役，讲的是调兵数字；两者之间，府兵实际缺额多少、募兵占几成、蕃兵如何统属，都没有系统记录。吐鲁番出土的卫士名籍能补西北一隅，墓志里从征辽左的记载能证明某人去过，却不能证明他在哪一府、哪一队。</p>
            <p>回到问题本身：折冲府提供的是可核验的名籍与训练，行军大总管提供的是临时的统一指挥，六军则是后世追加的标签。三者叠在一起，才是征辽军队的实际形态，一个靠文书、粮车与驿马维系起来的临时共同体，而不是一台整齐的机器。</p>
        `,
    },
    {
        id: "soldier-life-expedition",
        title: "征人的日常：军书、家书与徭役",
        date: "2026-12-24",
        tags: ["唐丽战争", "士兵", "社会史"],
        summary: "一名府兵的行囊里装着九斗麦饭、二斗米和一张弓，点兵文书决定他何时离家。文章由此串起征发、转输、口粮、伤病与徭役，比较正史、墓志、家书与诗歌的立场与缺口，指出士兵经验在史料中只剩轮廓；末段回到行囊的重量，追问国家的承诺与农家的付出是否对等，而墓志只肯记住体面的那一面。",
        content: `
            <p>贞观十九年春天，幽州以北的驿道上，一队府兵正把行囊捆上车。行囊里有弓、矢、横刀、砺石，还有九斗麦饭、二斗米，这是《新唐书·兵志》开列的府兵自备之物。名籍上记着他们的籍贯、年岁与体貌特征，以防冒名。军书一到，这些农家的壮劳力就要离开田地，走向数千里外的辽东。</p>
            <p>征发的第一步是点兵。府兵按名籍征调，点验时核对体貌，冒名相代要受罚。地方官府先造差科簿，把丁口、资产、应役名目登记在册，再按折冲府的配额发遣；军府与州县之间还有往复文书，写明发遣几人、限几日到府，逾期按律科罪。被点中的人到府集中，验资装、验马匹，按团、旅、队、火编队。军书是冷的，但它决定了一个家庭来年的收成。</p>
            <p>行装之外还有赍与裹。府兵自备的粮只够路上若干日，其后靠州县仓廪与转输。河北道沿途设置顿与驿，民夫车牛被征发来运粮。被征的不只是兵，还有牛、车、草料与做饭的人。战争的成本，一半落在没有出现在战报里的人身上。</p>
            <p>口粮的账可以粗算。一兵日食米二升是通行说法，万人一日即二百石，数万人经年，所需以十万石计。这个数字不必精确，方向是清楚的：军队越大，能走的时间越短。太宗在安市城下退兵，理由之一正是粮食将尽与辽左早寒。运输的损耗同样惊人：牛车日行不过数十里，粮在途中被人吃、被雨淋、被鼠耗，运到前线只剩一部分，所以前线的存粮永远比账面上的少。</p>
            <p>道路与日程同样限制着人。负粮携械的步卒日行数十里，遇雨雪、渡河、修桥还要减半；从幽州到辽水，再围辽东城、南下安市，几个月就过去了。从春末渡辽到深秋班师，士兵在野外过了整整一个夏天，衣甲霉烂、水源不洁是常事。他们对战争的感受，首先不是敌阵，而是脚上的茧、肩上的粮袋和不断重复的扎营。</p>
            <p>伤病是日常的另一面。军中设有医工，但药材与休整条件有限；冻伤、疫病、坠马、箭伤，在正史里往往只留下士卒多死四个字。阵亡者的处理，有收葬、有祭奠；太宗为征辽阵亡者作《伤辽东战亡》，防身岂乏智，殉命有余忠，是皇帝对死者的一次公开表态。诗里还有凿门初奉律、仗战始临戎一句，写的是出征的程序，不是个人的悲伤。</p>
            <p>家书是更稀缺的材料。吐鲁番、敦煌文书里有戍卒家书，但多属西北；征辽前线的家书几乎没有留存。我们能看到的多是墓志：某君从征辽左，某君辽东道行军，卒于军、归葬乡里。墓志由家人请人撰写，写的是家族希望后人记住的样子，卒地与死因常被含糊处理。</p>
            <p>诗歌提供第三种视角，但它是文人的视角。太宗《辽城望月》写驻跸俯九都，停观妖氛灭，是胜利者的观望；中唐王建《辽东行》写辽东万里辽水曲，古戍无城复无屋，是后人的想象。《全唐诗》里征辽题材不多，能确定的更少，多数是后人拟作或泛写边塞。征人自己的声音，几乎只能从军中歌谣的零星记载与墓志的套语里推测。</p>
            <p>徭役的链条比军队更长。运粮的民夫、修桥的工匠、养马的厩户、织军布的织户，都被卷入。唐制丁男岁役二十日，不服役者输庸；远征转输往往远超二十日，那点庸绢抵不了这份差。贞观十八年发河北诸州的诏令之下，是无数没有名字的差役。他们不在征人的名籍里，却在同一场战争里消耗，而且往往比士兵更早倒下。</p>
            <p>一个具体的人可以说明可见度的限度。薛仁贵从征辽东，白衣陷阵，太宗赐马二匹、绢四十匹，擢游击将军，这是《旧唐书》本传的记载，因为他是成功者。同一场战斗中阵亡的数十百人，名字散落在墓志与地方祠庙里，正史不载。他后来成为名将，所以那一战被反复书写；同一支部队里没有后来的人，就只剩一行数字。</p>
            <p>墓志的写法本身就是一种史料。志文常称其人以功授勋、以劳得官，却很少写他欠下的债、荒废的田、等不到他回来的家人。家族请人撰志，是为了在乡里与官府的记忆里占据一个体面的位置。读墓志，要读出它想掩盖什么，也要读出它不得不提到什么。</p>
            <p>史料批判在这里必须说清楚。正史的征人是统计单位，不是经验主体；数字来自主帅战报，倾向于少报损失、多报斩获；墓志是家族叙事，倾向夸功与隐痛；诗歌是文人建构，未必亲历。《资治通鉴》记征辽，常用士卒死者甚众、人马多死一类笼统语，这既是史臣的节省，也是材料的限度。三者互证，只能得到一个轮廓：征发、行装、转输、伤病、思乡、归葬。轮廓之内，具体感受仍不可还原。</p>
            <p>还有一层制度性的残酷。府兵本有役期，远征却常延期；勋赏可以改变身份，但名额有限；逃亡要受军法惩处，而逃亡的原因往往不是怯懦，是家里无人耕种、路费耗尽。军书与家书之间，隔着的正是这个制度缝隙。</p>
            <p>回到那些行囊。九斗麦饭、二斗米、一张弓、三十支箭，是一个农民对国家能拿出的全部，也是国家对他承诺的全部。征辽的胜负写在《资治通鉴》的年份里，而这些行囊的重量，写在无数没有留下名字的日常里。</p>
        `,
    },
    {
        id: "mohe-allies-goguryeo",
        title: "靺鞨与高句丽：战争中的北方同盟",
        date: "2026-12-23",
        tags: ["唐丽战争", "靺鞨", "同盟"],
        summary: "安市城下，高句丽援军里的靺鞨人战后被与高句丽俘虏分开处置。文章由此辨析靺鞨七部与高句丽的役属关系，说明唐以羁縻名号与物资招抚、高句丽以征发与赏赐维系，同盟的脆弱源于间接统治与酋长在两条依附线之间的计算；并提醒读者，把靺鞨当作统一的行为体，是讨论同盟时最常见的陷阱。",
        content: `
            <p>贞观十九年六月，安市城东南的山谷里，唐军斥候报告：高句丽援军到了，队伍里有大量靺鞨人。高延寿、高惠真率十五万兵来救安市，靺鞨是其中重要一部。这一战唐军大破之，斩首二万余级；战后对靺鞨俘虏与高句丽俘虏的处理并不相同，这个差别是理解两国关系的入口。</p>
            <p>靺鞨不是单一的政治体。《旧唐书·靺鞨传》记其凡为数十部，各有酋长，其中粟末、白山、伯咄、安车骨、拂涅、号室、黑水七部较著，这是通行说法。《新唐书》又列思慕、郡利、窟说等部名，诸书互有出入，说明中原对靺鞨的了解本就零碎。居地南接高句丽、北抵黑龙江流域，分布广，向心力弱。所谓靺鞨与高句丽同盟，严格说是高句丽对部分靺鞨部落的役属与征发。</p>
            <p>役属的方式，一是军事征发，二是婚姻与质子，三是赏赐与官职。高句丽强盛时，粟末、白山等部臣附于它，战时出兵、平时朝贡。这种关系不是对等的同盟，而是中心与边缘的依附；边缘部族保留自己的酋长与部众，只在战时被点名出征，战后仍回故地。高句丽有时还在其居地筑城置戍，以守通道，这类据点既是控制，也是摩擦的来源。</p>
            <p>高句丽为什么需要靺鞨？兵源与缓冲。高句丽人口有限，长期与隋唐对抗，兵力紧张；靺鞨居其北境，既能补充骑兵与步兵，又能作为对唐、对契丹的缓冲。靺鞨兵熟悉山地与河流，适合在辽东的复杂地形中作战，这是府兵与募兵不易替代的。对靺鞨酋长而言，追随高句丽可以获得战利品与地位，但也要承担伤亡与得罪唐的风险。</p>
            <p>这种从征并非始于唐丽战争。隋大业年间征辽东，史书里也有高句丽征发靺鞨从军的记载，唐人也把靺鞨视为高句丽的附从。可见双方的关系有几十年的积累，靠的是一次次出兵与赏赐维系，而不是一纸盟约；盟约可以撕毁，习惯却会延续，也说明依附关系有相当的惯性；这种惯性，比一纸文书更难对付。</p>
            <p>唐的对策是招抚与分化。贞观十八年，营州都督张俭发契丹、奚、靺鞨兵以讨高句丽；唐以羁縻州府安置归附的蕃部，赐酋长官职、帛物，开放互市。这不是单纯的军事联盟，而是一套以名号与物资换取兵源与情报的制度。羁縻州府的长官多由酋长世袭，唐只给名号与印信，不派流官，也不收赋税；这是一种廉价的盟约，便宜，也脆弱。</p>
            <p>安市城下的差别对待，正是这套制度的一次展示。据《资治通鉴》，唐军战后对高句丽俘虏择其酋长授官内迁，余者放还；对靺鞨俘虏则处置严厉，通行说法为坑杀三千余人。差别不是出于种族好恶，而是政治计算：高句丽是可以纳入羁縻体系的对手，靺鞨则是要威慑与争取的边缘力量。</p>
            <p>威慑的效果是双向的。一方面，靺鞨诸部看到依附高句丽的代价；另一方面，唐的残酷也会让边族在归附时更加犹豫。唐军在战后把两类俘虏分开处置，本身就是在向诸部发信号：站错队有代价，归附有赏。史料只记唐军的处置，不记靺鞨的反应，这一层只能从后续的朝贡与叛附中间接推测。</p>
            <p>战争后期，靺鞨的向背更明显。唐灭高句丽后，粟末靺鞨首领大祚荣率部东走，后来建渤海国；黑水靺鞨则与唐通使，唐置黑水都督府，事在开元年间。这些发展说明：高句丽一倒，靺鞨不再需要选边，转而直接面对唐。渤海国的建立，把粟末靺鞨从部落联盟带向国家，也说明靺鞨并非只能做别人的附庸。</p>
            <p>同盟的脆弱，根源在结构。高句丽对靺鞨的控制是间接的，靠酋长个人效忠，不靠官僚与郡县；一旦战局不利或赏赐不继，依附就会松动。唐的招抚同样间接，靠名号与物资，不能真正统辖其部众。两边都在借兵，而不是统兵。高句丽能给的是战利品与庇护，唐能给的是名号与互市；两种好处都不足以买断一个部落的忠诚。</p>
            <p>这也解释了为什么安市城下会有靺鞨。他们不是被高句丽的官制编入的部队，而是酋长带出来的部众；酋长一死或一降，队伍就可能散掉。对唐军而言，击溃这部分人，等于击溃高句丽北面的一个支点；对靺鞨而言，站错队的代价由整个部落承担。</p>
            <p>史料批判：我们关于靺鞨的知识，几乎全部来自中原视角。《旧唐书·靺鞨传》只有数百字，大半记朝贡与征伐，对内部世系、习俗的记载远不如高句丽传详细；《三国史记》记高句丽与靺鞨的关系，也多是战争与朝贡的片段。靺鞨自己的文字材料没有留下。</p>
            <p>还有一个陷阱：把靺鞨当成一个统一的行为体。实际上七部各有利益，有的附高句丽，有的通唐，有的两属。安市城下的靺鞨，可能只是其中若干部；战后被处置的，也未必代表全部。用靺鞨作主语讨论同盟，容易掩盖这种分裂。从唐的角度看，靺鞨是可以争取的蕃；从靺鞨的角度看，唐与高句丽都是需要应付的强邻。</p>
            <p>回到安市城下的那个山谷。靺鞨人站在那里，不是因为与高句丽有共同的民族目标，而是因为他们的酋长在两条依附线之间做了选择。同盟的牢固程度，取决于下一次赏赐与下一场胜负，这是北方政治的一般逻辑，也是唐丽战争中常被忽略的一条线。</p>
        `,
    },
    {
        id: "goguryeo-noble-politics",
        title: "大对卢与贵族政治：高句丽权力结构的内侧",
        date: "2026-12-22",
        tags: ["唐丽战争", "高句丽", "政治史"],
        summary: "《旧唐书》记大对卢三年一代，交替之日或勒兵相攻。文章由此分析五部贵族与王权的张力：任期制只定任期而未定仲裁，莫离支靠个人压服诸家，泉氏兄弟内斗遂成亡国导火索；并检讨中原文献与《三国史记》的层层改写，收束于那个始终没有仲裁者的交接机制，看它如何耗尽一个政权的余地。",
        content: `
            <p>《旧唐书·东夷传》记高句丽官制，最高者号大对卢，比一品，总知国事，三年一代，若称职者不拘年限。交替之日，或不相祗服，皆勒兵相攻，胜者为之。短短数句，把一个国家的权力交接写成了一场武装竞赛。这段材料，是进入高句丽政治内侧最直接的门。</p>
            <p>高句丽的官阶凡十二等：大对卢、太大兄、大兄、小兄、意俟奢、乌拙、太大使者、大使者、小使者、褥奢、翳属、仙人。大对卢总知国事，其余分掌内外。这套名号带有浓厚的部族色彩，与唐的三省六部不是一回事；它更像诸大家族在同一屋檐下的排序，位次即权力。《三国志》记高句丽有相加、对卢、沛者等名号，与《旧唐书》的十二等并不完全对应，官制在数百年间显然有过变化。</p>
            <p>五部的格局是这套排序的基础。高句丽有涓奴、绝奴、顺奴、灌奴、桂娄五部，皆贵人之族；《三国志》记其本以涓奴部为王，后来桂娄部代之。王权出自一部，其余诸部各有部曲与私兵。大对卢由诸家推举或竞争产生，任期三年，称职可留，这既是对强者的承认，也是对强者的限制：没有任何一家可以永久独占。桂娄部代涓奴部而为王，本身就是一个家族轮替的故事，说明王位并非固定在一家。</p>
            <p>三年一代的制度含义，要放在这个背景里看。它是任期，不是世袭；是诸家轮替的约定，不是王权的任命。称职者不拘年限一句，又给强者留了延长的话口；而谁说称职，实际上把判断权交给了诸家。制度的弹性很大，弹性来自诸家实力的对比，而不是条文本身。</p>
            <p>勒兵相攻则说明限制的边界。交接之日若不相服，就诉诸武力，胜者为之。这不是制度的失败，而是制度的一部分：当中央没有压倒诸家的常备力量时，权力交接只能以武力为最后仲裁。王权在其中扮演的是平衡者，而非主宰者。</p>
            <p>莫离支的出现打破了这种平衡。贞观十六年，泉盖苏文杀荣留王，立宝藏王，自为莫离支，专国政。莫离支位在大对卢之上，是盖苏文为自己设置的位置；他靠的是政变、私兵与威慑，而不是诸家的推举。制度性的三年一代，在他这里被个人权力取代。莫离支之名如何解释，仍有争论；能确定的只是它位高权重，凌驾于十二等之上。</p>
            <p>泉氏专权的结构，是家族私兵加王室姻亲。盖苏文出身高句丽大族，以莫离支统内外，诸家被压服而未被消灭；一旦他死去，压服的力量消失，诸家立刻重新竞争。这种权力形态依赖个人，不依赖制度，因此无法平稳传递。泉氏之外，高句丽还有众多加级贵族，他们掌握部曲，平时不显，危机时能迅速集结。</p>
            <p>兄弟内斗正是这种结构的必然结果。乾封元年，盖苏文死，长子男生代为莫离支，旋为弟男建、男产所逐，男生奔唐。唐以男生为向导，总章元年灭高句丽。一个国家的灭亡，直接导火索是继承危机，而继承危机源于权力没有制度化的传递方式，也没有可以服众的仲裁者。</p>
            <p>机制分析可以更进一层。大对卢的三年一代本是为了防止专权，但它只规定了任期，没有规定交接的程序与仲裁者；莫离支本是为了专权，但它只依赖个人，没有建立继承规则。两种设计都缺少谁来裁决的一环，于是每一次交接都变成武力测试，也是一次对诸家实力的重新测量。</p>
            <p>王权的位置因此很尴尬。高句丽王名义上是最高统治者，实际上要在大族之间维持平衡；他既不能没有强臣，又不能容忍强臣。荣留王被杀，宝藏王被立为傀儡，说明王权在泉氏面前已无还手之力。战争爆发时，高句丽的决策层是分裂的，唐军看到的不是一个统一的对手，而是一个正在内耗的政权。</p>
            <p>史料批判必须谨慎。《旧唐书》这段关于大对卢的记载，很可能来自唐使、降人或传闻，对三年一代的制度化程度有夸大；《三国史记》成书于高丽王朝，金富轼用中原官制的语汇改写高句丽旧事，未必保存原貌；把高句丽记成一个小中华，官制、礼制都按中原框架排列，这种框架本身就是一层改写。高句丽自身的金石材料，如好太王碑、牟头娄墓志，记的是王权与征伐，不记大对卢交替的细节；好太王碑立于五世纪初，距盖苏文已两百年，不能直接说明七世纪的政治。</p>
            <p>另一个缺口是勒兵相攻的频率。这条材料只描述了制度允许的极端情形，没有告诉我们实际发生过几次。若把它当成常态，高句丽早就自我瓦解；若把它当成例外，又无法解释泉氏政变为何能成功。合理的理解是：它是制度预留的出口，平时不用，危机时启用。</p>
            <p>还有一层容易被忽略：泉氏之泉，或作渊，旧说以为避唐高祖讳而改。若此说成立，则唐人所记的高句丽权臣姓氏已经过一道改写，我们连他的名字都隔着长安的避讳制度。这类细节提醒我们，材料的每一个字都带着来源的痕迹。</p>
            <p>回到那段引文。三年一代、勒兵相攻，写的不是高句丽人的好斗，而是一个没有常备官僚军队的国家，如何在诸家之间分配最高权力。唐丽战争的胜负，最后取决于这个分配机制能否在外部压力下继续运转，而它没有。</p>
        `,
    },
    {
        id: "tang-military-law",
        title: "军法与赏功：唐律中的行军条款",
        date: "2026-12-21",
        tags: ["唐丽战争", "军法", "唐律"],
        summary: "《唐律疏议·擅兴律》规定守城弃去者斩。文章由此梳理失期、逃亡、冒名与掠夺等条款，说明军法以刑罚替代议价、以勋赏维持士气，再以安市赐帛、俘获分配与张亮之诛为例，辨析法典文本与行军实践之间的落差；军法的效力，最终仍取决于粮车、天气与朝廷的政治计算，条文本身并不能决定。",
        content: `
            <p>《唐律疏议》卷十六《擅兴律》里有一条：主将守城，为贼所攻，不固守而弃去，及守备不设，为贼所掩覆者，斩。条文简短，没有余地。征辽的将军们读到的就是这样的句子，它把守变成了一种不可退让的义务。</p>
            <p>行军相关的条款不止这一条。征人已定而违限不赴，按日计罪，笞、杖递加；临军征讨而巧诈避役，处绞；冒名相代，徒二年；逃亡，罪更重。条文细密，说明冒名与逃亡都是常见问题，不是偶发的例外。《捕亡律》对逃亡的征人另有追捕与连坐的规定，军法的手伸到士兵家门以内。这些条文共同指向一个目标：保证名籍上的人按时出现在队伍里。</p>
            <p>为什么用刑罚而不是市场？因为府兵制的成本由国家以均田与勋赏支付，兵役是义务，不是契约。义务一旦可以议价，整个征发体系就会松动。律文的重，正是为了省去议价的麻烦，它用恐惧替代了交易。府兵的名籍与均田的户籍捆在一起，人跑了，田就荒了，所以逃兵不仅是军事问题，也是财政问题。</p>
            <p>但军法不只是惩罚。唐律与军令的另一半是赏功：战功授勋，勋官十二转，上柱国以下各有等级；赐帛、赐物、升官、给复。勋官不是实职，却可以免课役、荫子孙，对农家子弟的吸引力正在于此。赏与罚是一套杠杆的两端，国家用它把怕死与求赏同时装进士兵的心里。</p>
            <p>征辽提供了具体的例子。安市城下，薛仁贵白衣陷阵，太宗赐马二匹、绢四十匹，擢游击将军、云泉府果毅，一个普通士兵因一次冲锋进入军官序列。云泉府果毅是实职，薛仁贵从白身到军官，只用了这一战；赏格的力量，在这样的人身上最清楚。同一场战役，被斩的首领、被处置的俘虏、被赐帛的将士，都在同一套赏罚语言里被记录。</p>
            <p>俘获分配是另一条线索。唐军战胜后，马、牛、甲仗、人口都要登记、分配；一部分上献，一部分分赐将士。据《资治通鉴》，安市之战唐军获马五万匹、牛五万头、铁甲万领，这些数字纵有夸饰，也说明战利品分配是一套有账可查的程序，而不是就地哄抢。分配之外还有先登、斩将的专项赏格，斩将者往往越级授官，这是用少数人的暴富刺激多数人的冒险。</p>
            <p>军法的执行，却远不如律文整齐。临阵斩将需要皇帝或主帅的授权；便宜从事给了前线一定的裁量；赦免、戴罪立功、政治考量，都会改变条文的结果。贞观十九年，唐军围攻安市久不下，太宗一度议班师，诸将请继续；这类决策不载于律，却决定战役的结局。张亮率舟师征辽，后来因他事被诛，说明军法之外还有政治法。主帅在军中的威权，来自符节与诏书，也来自他对赏罚的独占；一旦这种独占被朝廷收回，军法就变成了政治清算的工具。</p>
            <p>军令与律文之间还有一层空隙。律是常法，军令是战时特别法，前者稳定，后者随主帅而定。军令多已散佚，只能从《通典》《唐会要》与兵书的引文里拼出片段：禁止擅入民家、禁止掠取财物、规定行列与更鼓。这些条文对付的，是军队自己。</p>
            <p>史料批判在这里很关键。《唐律疏议》是永徽四年颁行的法典，它反映的是立法者的设计，不等于行军的实践；疏文常引军令，可见律与令互相支撑，只是令的全文没有留下来；战报由主帅上奏，倾向于夸大斩获、隐去损失；墓志则只记受赏，不记受罚。三者相加，能证明有这套制度，不能证明每次都这样执行。</p>
            <p>还有一个层面：军法也保护士兵。征人违限有罪，但主将不得随意杀士卒；掠夺民财有禁；伤病者有抚恤；阵亡者有收葬与祭奠。律文在把士兵当作工具的同时，也给了他们一点点可援引的权利。这点权利在战时是否有效，是另一个问题。</p>
            <p>赏功的通货膨胀也值得注意。勋官越授越多，实际待遇下降；赐帛的数量在战报里动辄数十匹，到了士兵手里可能只是几匹。制度的激励效果，随时间递减。征辽后期，募兵的比例上升，正说明单纯依靠义务与勋赏已经不够。募兵的赏格是现钱的、可预期的，府兵的勋赏是延迟的、不确定的；两者并用，正说明朝廷已经明白单靠义务撑不住这支军队。</p>
            <p>于是军法与募兵形成一种互补。义务兵靠律文驱赶，募兵靠赏格吸引；前者成本低而士气弱，后者士气高而花费大。征辽的军队里两者并存，军法要同时管住这两种人，难度可想而知。这种互补并不稳定：募兵多了，军费上升；义务兵多了，逃亡增加。军法的条文再密，也只能在两者之间维持一个暂时的平衡。</p>
            <p>回到那条斩首的条文。它写的不是残忍，而是一个帝国对守土的最低要求：城在，将必须在；城失，将不能活。军法与赏功合起来，是唐军能在数千里外维持秩序的原因之一，也是它无法长久维持的原因之一，因为秩序靠的是恐惧与有限的好处，而不是士兵对战争的认同。</p>
            <p>征辽的胜负，最后落在粮车、天气与高句丽的内斗上；军法只是保证这支军队在崩溃之前还能站着。读《唐律疏议》的这些条款，读到的不是战争的荣耀，而是一个国家如何用文字把数十万人固定在行列里。</p>
        `,
    },
    {
        id: "wounded-medicine-expedition",
        title: "伤病与救护：远征军中的医疗",
        date: "2026-12-20",
        tags: ["唐丽战争", "医疗", "后勤"],
        summary: "从贞观十九年撤军路上的伤员写起，梳理箭伤、冻伤与疫病在远征中的分布，考察随军医工、药材供应与后送据点的实际条件，说明运输能力如何限定救护的上限，指出医疗组织对攻城与撤退节奏的反向约束，并辨明太宗亲为契苾何力敷药一类记载的叙事性质：它能证明仁君形象被生产与传抄，不能证明普通士卒所得的医疗水平。",
        content: `
            <p>贞观十九年十月，唐军从安市城下撤围。诏书给出的理由是辽左早寒、草枯水冻、粮食将尽；从辽东城到辽水这段路上，辎重车里躺着攻城中被石块砸断肋骨的人、被箭穿透小腿的人，也有人走着走着就倒在道旁。史书用「早寒」与「粮尽」解释这次撤退，对车上那些人几乎没有交代，仿佛撤退只是一次行军方向的改变。</p>
            <p>远征军面对的伤病并不神秘。攻城时最致命的是箭与石：高丽人守城，弓弩自上而下，唐军仰攻，头盔护不住面颈，铠甲遮不住小腿；云梯上的士兵一旦被推落，摔伤往往比箭伤更重。行军时则是足疾与冻伤，辽东的秋天来得早，涉水之后鞋袜不干，脚趾发黑的情形在寒地行军里并不少见。营地里的痢疾与疟疾另算一类，水源与拥挤的营垒是现成的传播条件。</p>
            <p>唐代医书对这些并不陌生。《千金要方》《外台秘要》都收有金疮、折伤、冻疮与痢疾的方子，处理箭伤要先出镞、再敷药、必要时烙灼止血；被石砸伤的要先辨有没有内出血，再决定能不能搬动。知识是有的，问题在于这些知识能不能被搬到几千里外的营帐里，以及搬过去之后还有没有药。</p>
            <p>京师的医疗由太常寺下的太医署掌管，分医、针、按摩、咒禁诸科，另有药园培养药材，学生按科目学习，考核后才许行医。这是为宫廷、官署与京畿服务的系统，规模有限。军中的医疗是另一套：史传与军令残文提到军中有医工、医人，但员额、隶属与考核在现存军令条文里并不完整。随军医工带着方书与草药，处理创伤主要靠清洗、敷药与包扎，伤口感染往往致命。可以确定的是，医疗没有独立的行军编制，多附在辎重与后军之后，随队而行；这意味着一旦急行军或轻装突进，医工最先被留下。</p>
            <p>药从哪里来，是更实际的问题。随军携带的多是丸、散、膏、丹一类成药，体积小、耐存放，汤剂要现煎，行军时难办。药材的另一来源是就地采买与地方贡纳，唐军在辽东能用到当地的人参、麝香之类，但止血与包扎靠的还是绢帛、麻布与金疮药。药材的重量与粮草争车马，这是所有远征军共有的困境，也是军令必须做取舍的地方。</p>
            <p>于是医疗的上限先由运输决定，而不是由医术决定。长安到辽东数千里，一匹驮马、一辆车所能载的重量有限，粮、械、帐、药四者互相挤占；季节窗口又压缩了可用的时间，春夏出兵，入秋必须考虑撤退，伤员要在入冬前处理完。一个重伤员要占一辆车、要两个人扶持、还要消耗一份口粮，这等于从战斗序列里再减去三个人。军令的选择因此并不温情：轻伤包扎后随队，重伤留在已克的城戍，等后一批转运。</p>
            <p>后送依赖两条线。陆路沿辽水与辽东故城的据点逐站转运，水路由辽河口出海，绕辽东半岛到登州一带。海路在秋冬风浪里风险很大，重伤员经不起颠簸，所以多数人留在占领的城邑，等下一批船或下一支队伍。这种安排实际上把医疗责任转移给了后方据点，而据点的医药物资往往更少，医工也更缺。</p>
            <p>阵亡者的处理是另一套制度。唐令对征人战殁有赠官、赙赠、复除的规定，家属可免一部分课役；军中另有勋簿登记战功与伤亡，作为事后抚恤的依据。班师之后，朝廷也曾下诏收瘗辽东战殁者的骸骨；史载太宗在辽东还命人收葬隋末征辽遗留的骸骨，这个举动带有明确的政治意味，用埋葬前朝死者来证明本朝不同。国家有能力把死亡纳入簿册与仪式，却未必能把伤病纳入。勋簿上的战功与伤亡，最后要落到勋赏与抚恤的兑现上，而兑现常拖到几年之后。</p>
            <p>最常被引用的记载是太宗亲为契苾何力傅药。通行说法称，贞观十九年攻白岩城，契苾何力率骑先登，为流矢所中，太宗亲自为他敷药，将士闻之感动。这条材料出自两《唐书》的本传，属于典型的仁君叙事：它要说明的是君主爱惜将士，而不是唐军医疗的水平。它能证明这类故事被生产、被传抄，能证明太宗愿意在公开场合做出体恤的姿态；它不能证明随军医工的数量、药材的供应，更不能证明普通士卒能得到同样的处置。</p>
            <p>数字也帮不上忙。史书对伤亡的表述多是「死者甚众」「士卒冻馁」一类模糊说法，既没有分母，也没有统计口径；同一场战役在不同文本里的死亡描述还会互相沿袭。把这些词换算成比例，是把修辞当数据。真正能反映规模的，是征发簿、勋簿与后方的复除名单，可惜这些文书在七世纪的辽东战场上几乎没有留下来。</p>
            <p>高丽一侧同样沉默。《三国史记》成书于十二世纪，依据本国旧记与传入的中国史书，对唐军的伤病没有记载，对本国军民的伤亡也极简略。双方史书都从胜负与德政的角度写战争，医疗与救护被排除在叙事之外，因为它们是过程，不是结果；而过程最难被朝廷的史官看见。</p>
            <p>还有一个容易被忽略的层面：医疗的组织方式会反过来影响战术。当重伤员意味着三个人减员，指挥官在攻城时就倾向于速决，在撤退时就倾向于弃城；安市城下久攻不克，最后以天寒粮尽撤兵，背后的算式里就有这一项。</p>
            <p>回到这支撤退的队伍。太宗的药敷在一个人身上，制度要照顾的是一万人；前者留下故事，后者留下数字，而数字又多半散失。远征军医疗的真相，大概就藏在这两种记录的空隙里：一边是被反复讲述的恩宠，一边是无人统计的冻伤与痢疾。理解这个空隙，比补上一个精确的死亡率更有意义。</p>
        `,
    },
    {
        id: "homefront-expedition",
        title: "后方的家：征人家庭的生计与赋役",
        date: "2026-12-19",
        tags: ["唐丽战争", "赋役", "家庭"],
        summary: "从贞观年间河北乡村的一次点丁写起，说明租庸调与府兵自备资装如何叠加成家庭的一次性支出，运输与造船差科如何占用农时，摊逃机制如何把一户的破产传导给邻户，减免与复除在执行中又如何折损，并指出正史、政书与墓志的官府视角、统计口径与阶层偏差，以及复员与勋赏兑现的延迟。战争于是从一次征发变成乡村社会的长期重组。",
        content: `
            <p>贞观十八年冬天，河北道的村子里，里正拿着名籍挨户点人。被点到的人要在来年春天自带弓刀、口粮与鞋袜上路，家里剩下的是一块要耕的田、一个要缴的租额，以及一个不知道什么时候回来的男人。名籍上写的是丁与户等，村里人算的是另一本账。</p>
            <p>唐前期的赋役框架是租庸调。丁男受田，岁纳租二石、调绢二丈，役二十日；不服役的可以纳庸代役，每日绢三尺。这套制度的前提是户内有丁、有田、有劳力，三者缺一，账就平不了。战争恰好同时动了这三样：丁被征走，田无人耕，劳力折成现钱。</p>
            <p>府兵出征要自备资装。弓、刀、箭、鞍辔、行装、粮食，多由卫士自己筹备，这在制度上叫自备，在家庭账本上就是一笔一次性的现金支出。为了凑这笔钱，卖一亩口分田、典一件绢衣，都是常见的选择；也有家庭向富户借贷，以秋收后的粮食偿还。这些交易不会进正史，却是征发最直接的社会后果。</p>
            <p>战争把临时负担叠在常规负担上。租调照旧按籍征收，丁却不在家；役期本有二十日的上限，战时却以征行的名义无限延长。名义上可以纳庸代役，实际上战时最缺的是人，官府要的是丁夫，不是绢帛；而且庸价在战时会上涨，穷户拿不出，只能自己去。</p>
            <p>差科按户等高下分摊，理论上户高的出丁与马，户低的出夫与车牛；但战时急征，里正往往按现有人丁点派，户等只是账面上的依据；军粮转输征用车牛与递夫，州县仓廪随之见底。真正决定谁上路的是家里有没有成年男丁、能不能立刻拿出资装，而不是名籍上那几行字。征发令下达到出发只有几个月，正好压在春耕之前，农家要在最缺现钱的时节凑出一笔路费，只能典卖；青黄不接时的价钱最低，这笔损失没有人记。</p>
            <p>真正加剧冲击的是摊逃。一户丁男被征、劳力不足，交不上租调，就可能举家逃亡；逃户的税额并不会消失，里正与州县会把它摊到邻户与亲族身上，于是第二户、第三户跟着破产。这个机制不需要贪官，只需要一套按旧籍征收的硬指标，就能把一次征发变成一连串的逃户。摊逃在唐代财政史上反复出现，征辽只是让它更早、更集中地发生。</p>
            <p>运输与造船是另一条负担线。征辽的粮草要从河北、河南转输到辽西，车牛、民夫按州县的户等差科；水军的船则从江南各州打造，木材、桐油、铁钉与工匠都要地方承担。这些差科不进租调的账，却直接占用农时；一个船匠在江边待三个月，家里的田就得靠别人。</p>
            <p>家庭内部的调整往往不被记录。男人走了，耕田落到妇女与老人身上；婚期推迟，因为男方家里拿不出聘财，也因为不知道人能不能回来；孩子生病，先找的不是医，是邻家的草药与巫祝。分家、过继、招婿这些办法也会被用来保住一户的丁额与田产。这些应对方式在正史里没有位置，只在少量墓志与诗歌的缝隙里露头。</p>
            <p>朝廷并非完全无视。战时与战后有免租、赈给、赐帛的记录，也有对从征者家属复除的令文。但减免通常按道、按州下达，执行到户要经过州县与里正，中间有折损；而且减免的是当年的租调，补不上已经卖掉的田。对一户人家来说，免一年的租，抵不过失去一个主要劳力。</p>
            <p>现存记载几乎都出自官府视角。奏疏里的民不堪命是谏臣用来劝阻战争的话，它有具体的政治目的，不能当作社会统计；《通典》《唐六典》记的是制度条文，条文与实际执行之间有距离，尤其战时。至于家庭内部的分配、借贷、典卖，只有敦煌、吐鲁番所出的籍帐与契约能提供一点线索；敦煌文书多属唐后期至五代，吐鲁番虽有唐初西州的籍帐，却只涉一隅，不能直接搬到七世纪的河北。</p>
            <p>墓志能补充一点。从征者的墓志会写从征辽左、记功与赠官，却很少写家里怎样度过那几年；女性的墓志偶尔提到夫在军，语气是表彰守节，不是记录生计。这些文本的阶层偏向很明显，能读出的只是中上层家庭的轮廓，而负担最重的往往是那些没有能力刻石的下户。</p>
            <p>立功者的回报也要打折。府兵从征有功，授勋官，勋官有品阶与相应的勋田，但勋田的授予要落到实有土地上，州县往往无田可给；勋官的名号于是多于实际收益。对家庭来说，丈夫带回的是一纸告身与几匹赐帛，不是可以立刻耕种的田。这种兑现的延迟，使征发的经济账在战后仍然算不平。</p>
            <p>还有一个性别维度值得点出。征发把家庭的重心推向女性，但制度并不给她们相应的身份：户主仍是出征的男人，授田与课役仍按丁计，女性承担了耕作却不在名籍的劳力栏里。这种错位在文书上表现为户内丁数不变，在生活里表现为一个女人耕两个人的田。</p>
            <p>长期影响要谨慎。征辽确实加重了河北的负担，也会推动逃户与籍帐失实，但把均田制的松动全部归因于这场战争，是把复杂问题单线化。更稳妥的说法是：战争加速了本已存在的趋势，让「人不在籍、田不在户」的情形更常见；而制度的真正危机，要等到赋役对象与土地占有彻底脱钩之后才显现。</p>
            <p>复员也不是一次完成。征行有期限，战事延长则归期推迟，家里的安排只能一年一年往后挪；有的家庭在等待中分了家，有的把田典给邻户后再也赎不回来。史书只记某年班师、某年免租，家庭的日历却是按播种、收获与借贷的节点翻的。</p>
            <p>回到那个冬天被点名的村子。制度看到的是「一丁」，家里看到的是一个儿子；制度记的是课与役，家里记的是谁去耕地、谁来还债。战争在后方留下的，不是一条诏令，而是许多户人家重新排列过的生活。</p>
        `,
    },
    {
        id: "pyeongyang-siege-668",
        title: "平壤之围：都城如何陷落",
        date: "2026-12-18",
        tags: ["唐丽战争", "平壤", "攻城"],
        summary: "以总章元年平壤受降为线索，复原唐军肃清外围、鸭绿栅与辱夷城之战、月余围城、白幡出降与信诚开门的过程，分析渊盖苏文死后贵族分裂如何使内应成为可能，并以安市城久攻不下作对照，说明唐军的胜利来自城内分裂而非攻城器械的突破，围城时间也受自身补给线的限制，投降仪式的细节则多出自唐军报捷文本。",
        content: `
            <p>总章元年九月，平壤城头挂出白幡。史称高丽王高藏遣泉男产率首领九十八人，持白幡到唐营请降；唐军受降之后，城内的泉男建仍然闭门拒守，直到几天后城门从里面被打开。同一座城，一边已经投降，一边还在抵抗。</p>
            <p>唐军到平壤之前，先清了外围。乾封二年，李勣拔新城，薛仁贵连破南苏、木底、苍岩；总章元年，薛仁贵破扶余城，扶余川中四十余城相继归附。高丽派兵五万救扶余，被薛仁贵击破。这些战事的意义不在杀获，而在于把平壤与北方诸城之间的联系一段段切断：援军来不了，粮道也断了。平壤依大同江而建，城北以丘陵为屏障。</p>
            <p>鸭绿栅与辱夷城是最后一道外围。通行说法据《资治通鉴》，唐军在鸭绿栅击破高丽拒战之兵，追奔二百余里，拔辱夷城，契苾何力引兵来会。此后平壤的外援基本断绝，围城才真正开始。所谓围城，先是一场切断联系的工作，然后才是城墙下的事。</p>
            <p>围城的时间并不长，史称月余。平壤不是被长期封锁饿垮的，唐军也没有足够时间筑起完整的攻城主垒；安市城下筑土山、造冲车尚且久攻不下，平壤的城防只会更厚。真正决定结局的是城里的政治。</p>
            <p>唐军这一路的指挥是李勣，诸将分道并进，契苾何力、薛仁贵、庞同善等各当一面，水军另从海道策应。兵力看起来充足，但围一座都城并不只是把人数堆在城下：先要填壕、夺外墙、控制城外的制高点与水源，才能把攻击面收窄到一两处。平壤的城墙沿江与山势展开，攻击面反而更宽，唐军没有时间完成这套准备工作。</p>
            <p>还有粮道。唐军从辽东推进到平壤，补给线拉长到千里以上，沿途要靠新城、扶余这些刚归附的城邑接济；这些城邑的态度并不稳固，唐军必须在身后留兵。围城只能维持月余，与其说是城内撑不住，不如说是唐军自己的补给与后方也不允许更久。</p>
            <p>白幡是投降的仪式语言。王遣贵族持幡出营，等于承认战争结束；但男建仍在城内，说明投降不是全体一致的决定，而是宫廷内部的分裂在仪式上的表现。这个仪式同时也是给唐军看的：它让受降者可以宣布战争已经结束，而不必等城内最后一个人放下武器。</p>
            <p>城内的情况也可以从时间反推。围城月余，储粮不会立刻见底，都城的仓廪与私家窖藏足以撑过整个冬天；真正先耗尽的是耐心。援军被击破的消息传进城里，贵族的私兵开始计算自己的出路，这比饥饿更快地瓦解防守。</p>
            <p>打开城门的是一个僧人，法号信诚。史称他素为男建所信，受唐军招诱，作为内应开门，唐军因此入城。这条记载很简略，却是全篇最关键的一句：都城的失守不是城墙被撞开，而是门闩被人从里面抽掉。史书对信诚的动机没有交代，只留下一个身份与一个动作。</p>
            <p>为什么内应能够成功，要从高丽的政治结构看。渊盖苏文在六百四十二年后专权，王权被架空；他死后，长子泉男生与两个弟弟泉男建、泉男产争权，男生被逐，走保国内城，遣子入唐求救。唐军东来，男生一系成了向导，也成了受降之后可以被扶植的代理人。都城的守军由各家贵族的私兵与部曲拼成，忠诚本来就分散；当外围尽失、援军无望，开门对一部分贵族来说是保全家族的选择。</p>
            <p>平壤的城防本身不弱。通行说法认为平壤由山城与平地城组合而成，大城山城据山险，安鹤宫一带是迁都后的宫城区域，城墙、马面、城门遗迹至今尚存。山城提供最后的退守，平地城容纳人口与仓廪；这种组合适合长期坚守，前提是内部不裂。一旦贵族各怀异心，再厚的墙也只是分隔自己人的障碍。</p>
            <p>与安市城对比更清楚。贞观十九年唐军攻安市，筑土山、造冲车，土山崩塌后被守军夺据，久攻不下，最后因天寒粮尽撤兵。安市证明唐军并不擅长速破坚城；平壤之所以月余而下，靠的是内应，不是攻城技术。把两次围城放在一起看，唐军的胜负差别不在器械，而在城内是否有人愿意开门。</p>
            <p>三种记载的差异值得注意。《旧唐书》与《资治通鉴》都写到信诚内应，《新唐书》较简；《三国史记·高句丽本纪》记王降与男建被擒，对开门者着墨不多。投降的责任由谁承担，在不同文本里有不同的分配。通鉴把灭国归因于兄弟阋墙，这是一种道德化的因果解释，读起来顺，却掩盖了军事压力与贵族离心这两个更基本的原因。</p>
            <p>还有一层：白幡与率首领九十八人这样的细节，是唐军报捷文书喜欢的形式，数字与仪式都在强调高丽君臣主动归命。这类细节能证明受降仪式的存在，不能证明城内多数人的态度；它更像一份对外公告的措辞，而不是一份民意记录。</p>
            <p>战后的安排同样说明这是一场政治收编。高藏被献俘于京师，唐廷另授官职以示优容；高丽故地分置府州，置安东都护府统之，部分高丽民户被迁往内地。这些措施针对的是贵族与王族，只要上层归附，唐廷就认为旧国已经消失，至于乡里的秩序，仍要靠原来的头面人物维持。高藏被俘与男建被擒的先后，两《唐书》与《通鉴》所记并不一致。</p>
            <p>城破之后，唐设安东都护府于平壤，薛仁贵以检校安东都护留镇，史称留兵二万。高丽故地的抵抗并未停止，剑牟岑等人另立安胜，唐的统治在几年内不断收缩，都护府后来内迁。灭国是一夜之间的事，统治是许多年的事；平壤的城门开了，高丽的人心并没有跟着开。</p>
            <p>回到那面白幡。它挂上城头的时候，平壤还没有被攻破；它的意义不在军事，而在政治。一座都城的陷落，往往先从内部的一句话开始，而那句话在史书里只占一行。</p>
        `,
    },
    {
        id: "war-edicts-rhetoric",
        title: "诏令中的战争：唐廷如何论证东征",
        date: "2026-12-17",
        tags: ["唐丽战争", "诏令", "政治修辞"],
        summary: "以贞观十八年亲征诏令为材料，拆解弑君、救新罗、复旧疆三套说辞的分工与互补，说明它们分别面向官僚、军队、藩属与民间，比较诏令、纪功碑与谏表三种文本的受众差异，讨论宣传文本能证明什么、不能证明什么，并指出同一套说辞会随战局由动员转为解释与抚纳，修辞因此是动员机制的一部分，受众不同，同一理由的分量也不同。",
        content: `
            <p>贞观十八年，长安发出一道诏书，宣告将亲征高丽。诏书罗列的理由不止一条：高丽弑其君、虐其民；侵暴新罗，新罗求救；辽东本是中国的旧疆，却被割据。三条理由并置，另以天命与吊民伐罪为纲，又以隋炀帝的覆辙自警，读起来像一份起诉书，而起诉书的作用从来不只是陈述事实。</p>
            <p>第一条理由最重。六百四十二年起，渊盖苏文弑荣留王、立宝藏王，专擅国政。唐廷的反应并不是立即出兵：先遣使吊祭，继而册封高藏，事实上接受了既成局面。等到决定用兵，弑君才被重新拿出来，作为道德上的定性。同一件事，先被搁置，后被声讨，中间的差别不是事实变了，是政策变了。</p>
            <p>第二条理由关乎秩序。新罗遣使求救，称百济与高丽攻取其城；唐作为宗主，有调解与救援的义务。但新罗自己也在扩张，唐廷并非不知道。救援的说辞把一场边界战争翻译成宗藩秩序内的执法行动，好处是把出兵说成尽责，坏处是把战争的目标限定在半岛，而唐廷真正想要的显然不止于此。</p>
            <p>第三条理由关乎历史。辽东、玄菟、乐浪是汉四郡的旧地，这个记忆在唐初的士人心里很清楚。但旧疆的边界是模糊的：汉四郡的实际控制范围、高句丽后来的扩张、羁縻州的实际归属，都不能画成一条线。诏书不需要这条线，它只需要一个可以召唤的记忆，让远征看起来像收复。</p>
            <p>三套说辞为什么要叠在一起？因为单独任何一套都不足以支撑一次举国动员。弑君是道德理由，能说服官僚与士人，却不能解释为什么是现在、为什么必须亲征；救新罗是义务理由，能说服朝廷，却把战争限制在半岛事务；复旧疆是历史理由，能提供领土想象，却容易被反问旧到什么程度。三者互补，覆盖不同的受众：对河北的百姓讲保境与复仇，对军队讲功赏，对藩属讲秩序，对后世讲正义。</p>
            <p>诏令要落地，还得经过一层层转述。诏书下到州县，由长吏宣读、里正传告；军中则由军吏宣谕，把吊民伐罪翻译成士兵能懂的话：立功有赏、扰民者斩、粮草有备。修辞在传播中会被简化，最后留在民间的往往只是一句皇帝要打高丽，理由反而掉在路上。研究诏令的人如果只看文本，会高估理由的传播效果。</p>
            <p>诏令还要处理一段不光彩的记忆。隋炀帝三征高丽，死者无数，最终亡国。唐初的诏令反复强调这次出兵与隋不同：兵少而精、粮运有备、不夺农时。这些承诺本身是修辞，却也说明朝廷知道民间怕什么。动员一个刚刚走出隋末战乱的社会去打同一场仗，必须先证明这一次不会重演。</p>
            <p>太宗还有一句更直白的话，被《资治通鉴》记下来。</p>
            <blockquote>辽东本中国之地，隋氏四出师而不能得；朕今东征，欲为中国报子弟之仇，高丽雪君父之耻耳。</blockquote>
            <p>这句话把旧疆、复仇、雪耻三层意思压在一处，后面还跟着一层更私人的理由：趁自己未老。诏书里不会写这一层，史官却把它记了下来，因为它更像真实的动机。</p>
            <p>诏令与决策之间隔着一段距离。真正推动出兵的，有边疆安全、有个人声望、有太宗晚年的紧迫感，也有对隋朝失败的比较心理；诏令不写这些，它写的是可以公开的理由。朝中并非没有异议，房玄龄在贞观二十二年再次议征高丽时上表谏止，语气近乎遗言；这说明即便在朝廷内部，东征也不是没有成本的共识。《贞观政要》所记的君臣问答，可与诏令对读。</p>
            <p>诏令是宣传文本，这一点必须说清楚。它能证明朝廷认为哪些理由可以说服人，能证明修辞的组合方式与受众的划分；它不能证明高丽方面的实际行为，也不能证明战争的起因就是诏令所列。诏令里的弑君是被选择性使用的：同一件事在六百四十二年后被容忍，在六百四十五年前被声讨，差别不在事实，在需要。</p>
            <p>文本的保存也有层次。《唐大诏令集》与《全唐文》所收的诏令，多经宋人编纂，篇题、字句与原稿未必一致；《资治通鉴》引述的太宗语，来自唐代国史与实录，经过了史官的剪裁。用这些文本做修辞分析是合适的，用它们做事实核对则要小心；研究者通常要把诏令、实录与纪功碑对读，才能看出哪些话是对内说的，哪些是对外说的。</p>
            <p>与诏令配套的还有纪功碑。唐军在百济故地所立的纪功碑至今尚存，碑文与诏令共享同一套词汇：吊伐、归命、永久。碑立在原地，面向的是当地人与后来的过客；诏令发往天下，面向的是官僚与军队。两种文本的受众不同，修辞的强度也不同，但都把战争写成秩序的恢复。</p>
            <p>高丽一侧没有留下对应的宣传文本。《三国史记》记唐使来责，记高丽不受命，语气是从本国立场写的，成书却晚到十二世纪。双方的战争叙述不对称：唐有完整的诏令与纪功碑，高丽只有零散的记事。这种不对称本身也是史料，它说明谁有能力把战争写成文字并留存下来。</p>
            <p>语气还会随战局变化。贞观十九年班师之后，诏令的重点从动员转向解释：为什么没有灭国、为什么还要再举。贞观二十二年再议征辽，诏令与谏表同时出现，一个说必要，一个说不可，朝廷内部的争论因此被文本保留下来。到了总章元年灭国，同一套说辞又变成抚纳与安置的语言。</p>
            <p>回到那份起诉书。它列举的每一条都有事实的影子，也都有选择的角度。诏令不是战争的装饰，它本身就是战争的一部分——它先把一场远征说成一次执法，然后才让军队出发。读诏令的人如果只问它是否真实，会错过它真正的作用；如果只问它如何修辞，又会忘记它背后确有刀兵。</p>
        `,
    },
    {
        id: "battlefield-archaeology",
        title: "战场考古：萨水、安市与白江口的实地",
        date: "2026-12-16",
        tags: ["唐丽战争", "考古", "战场"],
        summary: "从清川江下游的地貌写起，讨论萨水、安市城与白江口三处战场的文献定位与考古现状，说明河道变迁、遗物回收、地层改造与跨国准入如何限制战场考古，评估遥感、地球物理与沉积采样的限度，并指出地名层证据的不可靠，主张以军事地理与后勤条件为解释框架，而不是对某场战役的指认，考古与文献因而是两类证据。",
        content: `
            <p>从清川江下游的一处台地往西看，河道在淤积的平原上摆了几个弯。想在这里找到六百一十二年那场溃败的位置，先要回答一个更朴素的问题：这条江，是不是《隋书》里的萨水。地名对不上，后面的工作都无从谈起。</p>
            <p>通行说法把萨水比定为清川江。依据是里程与方向：隋军从鸭绿江方向南撤，渡萨水时被高丽军半渡而击。但清川江下游的河道在千年里改过道，河口淤积，今天的岸线与七世纪的岸线并不重合。文献给的是相对位置，地貌给的是绝对变化，两者对不上是常态，对上才是运气。</p>
            <p>萨水之战的记载出自《隋书》与《资治通鉴》。隋军九军渡辽，攻平壤不克，粮尽退兵，至萨水，高丽军待其半渡而击，隋军大溃。史书给了一个极端的数字，用来渲染失败之惨；数字本身经不起核算，但它传达的结构是清楚的：退兵时的渡河点，是最脆弱的地方。半渡而击不是巧计，是常识。</p>
            <p>安市城的位置争了一百年。通行说法倾向于今辽宁海城一带的山城，也有学者提出别的候选，至今仍有讨论。城址尚存石筑城墙、马面与城门遗迹；山城多石筑，土城夯土版筑，保存差别很大；安市城山势陡，城内有水源，这种形制适合长期被围。唐军筑土山攻城，土山崩塌后被守军夺据，这个细节与地形有关：土山要筑到与城头齐平，需要大量土方与时间，而山城的城墙本身就建在更高的岩体上。</p>
            <p>白江口在锦江下游。六百六十三年，唐军刘仁轨部与日本援军在此水战，史称四战皆捷，焚舟四百艘。河口的地貌变化比山地更大：泥沙淤积、岸线外推、航道改移，今天的河口与当时的战场可能已不是同一处水面。海战的战场还会随潮汐移动，研究起来比陆战更难。</p>
            <p>沉船线索是白江口最诱人的部分，也是最不可靠的部分。水战焚舟，船体多半烧毁或解体，能被泥沙掩埋保存的只是碎片；即便发现木构件与铁器，要证明它属于六百六十三年的那支船队，需要形制、材种、共存遗物与地层的一整套证据。目前并没有可以确指的战场沉船，通行说法只到有线索、待调查的程度。</p>
            <p>今天的调查手段比过去多。遥感影像可以辨出城址的轮廓与道路的走向，地形分析可以算出视域与坡度，地球物理勘探能在不发掘的情况下看到地下的异常，沉积柱可以取样测年。这些手段能回答这里适不适合设渡口、这条沟是不是护城河，不能回答谁在这里打过仗。技术的进步扩大了可以提问的范围，没有消除证据性质的限制。</p>
            <p>战场遗存难以形成，有几层原因。其一是回收：箭头、甲片、刀剑在战后会被胜方与当地人收捡，金属是值钱的东西。其二是腐朽：木、革、布在多数土壤里留不住，能剩下的只有陶、石、金属。其三是改造：农田、道路、水库、城市建设把地层翻过几遍。其四是规模：一场战役动辄数十里范围，遗物密度极低，靠探铲找到的概率很小。</p>
            <p>即便挖到东西，判读也难。铁镞的形制在几个世纪里变化不大，甲片的编缀方式有区域传统，陶片只能给出粗略的年代。一件兵器能证明这里有过军事活动，不能证明这里就是某场战役。要把遗物与文献对上，需要共存关系、需要地层、需要一批而不是一件；而这样的条件在战场遗址上往往不具备。</p>
            <p>文献本身也不提供坐标。史书的里程是去某城若干里，古今度量不同，道路走向也变了；同名地名在不同时代指不同的地方，安乐、辽东、平壤都出现过这种情形。用文献给考古定点，通常只能定出一个范围，然后在这个范围里找地形最合理的那一处。</p>
            <p>地名层是另一条线索，也常被误用。安市、白江这类名字在后世的地方志里反复出现，有时指同一处，有时只是同名移植；村落以古战场为名，未必因为那里真的打过仗，也可能因为传说好听、因为要争一个古迹。用晚出的地名去追早期的战场，需要先证明名称的连续性与所指的稳定性，而这两点恰恰最难证明。</p>
            <p>还有现实条件。三处战场分属中国与朝鲜半岛，考古工作的准入、资料发表与语言都不统一；朝鲜一侧的调查成果外界不易见到，韩国一侧的白江口研究又与日本学界的问题意识交织。跨国比较因此只能停在定性层面，谁也很难把三国的材料放在同一张图上核对。</p>
            <p>遗址的现状也不容乐观。山城的石墙还在，但墙外的坡地被开成梯田，城内的取土与耕作不断翻动地层；河口的淤积与围垦改变了岸线，水下的遗存可能已被航道疏浚破坏。保护与研究的矛盾在这些地方很具体：越是交通便利、人口稠密的战场，越难保留原始堆积。</p>
            <p>所以这类实地工作的合理目标，不是找到那场战役，而是理解军事地理：道路怎么走、粮怎么运、城怎么守、退却时在哪里最危险。萨水的意义在于渡河点，安市的意义在于山城与土山的对抗，白江口的意义在于河口与潮汐——这些是地形与后勤的问题，不是一件兵器能回答的。沿着这个方向，考古能提供的是一种条件性的解释，而不是一次指认。</p>
            <p>还有一个方法论上的提醒：不要把文献的叙述结构当作地形的事实结构。史书说半渡而击，是因为这个说法能解释失败；考古要问的是，那个季节、那条河、那支军队，究竟有没有可能在一个渡口挤在一起。两种问题不同，答案也不能互相代替。</p>
            <p>站在台地上，能确认的只有一件事：这里曾经是一条需要渡过的河。至于谁在哪个清晨半渡而击，文献说了，地貌没有说，考古也未必能说。战场之所以是战场，不在于留下多少遗物，而在于它曾经迫使一支军队做出选择。</p>
        `,
    }
];

